      g.fillStyle = "#2b2530"; g.font = CF(700, 29); g.fillText(t("acn") + ": " + (m.name || ""), pad, 182);
      g.fillStyle = "#6f6973"; g.font = CF(500, 24); g.fillText("+88 " + (m.phone || "") + "   ·   " + dstr(d.from) + " – " + dstr(d.to), pad, 220);
      y = 262;
