  /* পেছনে যাওয়া: প্রথম ক্যামেরা পাতা থেকে এখন ডকুমেন্ট পাতায়, ডকুমেন্ট থেকে ইন্ট্রোতে */
  const _kb = kBack;
  kBack = function () {
    if (K.step === "doc") { hap(); K.flow = false; K.step = "intro"; kycRender(); return; }
    if (K.step === "front" && !K.pv && !K.cardOnly && !K.redo && !document.getElementById("kpk")) { hap(); K.pv = ""; K.step = "doc"; kycRender(); return; }
    return _kb.apply(this, arguments);
  };
}

/* ---- v3.06 ভাগ ২: ক্যামেরা পাতা (টিক নিচের চিপে, ওপরের হিন্টে শুধু ছবির সমস্যা), যাচাই পাতা, স্থির লোগোর পটভূমি ---- */
{
  /* সব সাধারণ পাতায় (ক্যামেরা বাদে) লগইনের মতো স্থির বড় লোগোর পটভূমি */
  const _kh2 = kHtml;
  kHtml = function () { const h = _kh2.apply(this, arguments); return typeof h === "string" ? h.replace('<div class="kw">', '<div class="kw kw2">') : h; };

  const _ksc = kScan;
  kScan = function (side) {
    let h = _ksc.apply(this, arguments);
    const pv = K.pv, ok = !!pv && K.okp === pv, wm = pv && K.wm && K.wm.img === pv ? K.wm.k : "", busy = !!pv && !!K.vbusy && !ok;
    h = h.replace(/<div class="kdone">[\s\S]*?<\/div>/, "").replace(/<div class="kchk">[\s\S]*?<\/div>/, "").replace(/<div class="kwn">[\s\S]*?<\/div>/, "");
    const hint = wm ? `<p class="khint bad">${kic("info")}<span>${t(wm)}</span></p>` : "";
    const chip = ok ? `<div class="kchp gd"><i class="kck">${kTickI}</i><span>${t("k_got2")}</span></div>` : busy ? `<div class="kchp"><i class="kspin"></i><span>${t("k_chk2")}</span></div>` : "";
    /* হিন্ট ও চিপ কার্ড-ফ্রেমের (.kwr) ভেতরেই বসে, তাই সবসময় কার্ডের ঠিক ওপরে/নিচে থাকে */
    return h.replace(/(<div class="kwr[^"]*">)/, "$1" + hint).replace(/<\/div>\s*<div class="kbt">/, chip + '</div><div class="kbt">');
  };

  /* ---- যাচাই পাতা: ৪টি চেকলিস্ট, % ইউজারকে শুধু ৭০-এর নিচে ---- */
  kMatch = function () {
    const R = K.mres, th = (src, cls) => `<div class="kmf${cls || ""}">${src ? `<img src="${src}" alt="">` : kic("face")}</div>`;
    const keys = ["k_ck1", "k_ck2", "k_ck3", "k_ck4"];
    const list = (state) => `<div class="kck2s">${keys.map((k, i) => `<div class="kck2 ${state}" style="--i:${i}"><em>${kTickI}<i class="kspin"></i></em><span>${t(k)}</span></div>`).join("")}</div>`;
    if (!R) return `<div class="kw">${kTop(t("k_title"), "", 3)}<div class="kbody"><div class="kcard kc1 kmx"><div class="kmp">${th(K.cardThumb, " sc")}<i class="kml"></i>${th(K.selfie, " sc")}</div>
      <h2>${t("k_m_h")}</h2><p id="kmst" class="kmh">${t("k_m_l1")}</p>${list("run")}</div></div></div>`;
    const nm = R.st === "nomodel", md = nm ? "nm" : (R.mode || (R.st === "ok" ? "ok" : "low")), ok = md === "ok", hasP = R.d !== null && R.d !== undefined, pc = hasP ? Math.round(R.pct) : 0;
    const showPct = hasP && R.pct < KM.REVIEW;   /* % ইউজারকে শুধু ৭০-এর নিচে; বাকিটা শুধু সাপোর্ট/অ্যাডমিন দেখে */
    const col = ok ? "#12a15b" : (md === "r1" || md === "rv" || md === "fin") ? "#e8a20c" : nm ? "#8b8590" : "#e5484d";
    const H = {ok: "k_m_okh", r1: "k_m_r1h", rv: "k_m_rvh", fin: "k_m_finh", low: "k_m_lowh", none: "k_m_noh", nm: "k_m_nmh"}[md];
    const SUB = {ok: "k_m_oks", r1: "k_m_r1s", rv: "k_m_rvs", fin: hasP ? "k_m_finp" : "k_m_fin0", low: "k_m_lows", none: "k_m_nos", nm: "k_m_nm"}[md];
    const mid = ok ? `<div class="kmrw kmok">${kRing(100, col)}<span>${kTickI.replace('stroke="#fff"', 'stroke="#12a15b"')}</span></div>` : showPct ? `<div class="kmrw">${kRing(R.pct, col)}<b style="color:${col}">${pc}%</b></div>` : `<div class="kmrw">${kRing(0, col)}<b style="color:${col}">!</b></div>`;
    const retry = md === "low" || md === "none";
    const why = md === "low" ? `<div class="kmwy">${(R.rs || []).map(k => `<div class="kmri">${kic("info") || ""}<span>${t(k)}</span></div>`).join("")}</div>` : "";
    const meta = retry ? `<small class="kmt">${t("k_m_att")} ${Math.min(K.att || 1, 3)}/3</small>` : "";
    const btns = retry ? `<button class="kbtn" onclick="kMatchRetry(0)">${t("k_m_try")}</button>${R.cardBad || md === "none" ? `<button class="klk" onclick="kMatchRetry(1)">${t("k_m_card")}</button>` : ""}`
      : md === "r1" ? `<button class="kbtn" onclick="kMatchGo()">${t("k_m_go")}</button><button class="klk" onclick="kMatchRetry(0)">${t("k_m_try")}</button>`
      : `<button class="kbtn" onclick="kMatchGo()">${t("k_m_go")}</button>`;
    return `<div class="kw">${kTop(t("k_title"), "kBack()", 3)}<div class="kbody"><div class="kcard kc1 kmx kz"><div class="kmp">${th(R.card)}<div class="kmc" style="--c:${col}">${mid}</div>${th(R.self)}</div>
      <h2>${t(H)}</h2><p>${t(SUB)}</p>${meta}${ok || md === "r1" || md === "rv" ? list("on") : ""}${why}</div></div>
      <div class="kbtm">${btns}</div></div>`;
  };
}

/* ---- v3.06 ভাগ ৩: অ্যাপের কোথাও বাংলা সংখ্যা নয় — সব লেখার বাংলা অঙ্ক (০-৯) ইংরেজি অঙ্ক (0-9) হয়ে যায় ---- */
{
  const en = s => typeof s === "string" ? s.replace(/[\u09E6-\u09EF]/g, d => String(d.charCodeAt(0) - 0x09E6)) : s;
  [T.bn, T.en].forEach(L => { if (L) Object.keys(L).forEach(k => { if (typeof L[k] === "string") L[k] = en(L[k]); }); });
}

/* ---- v3.06 ভাগ ৪: ফেস পাতার বাকি লেখাতেও "লাইভ মুখ/মুখ যাচাই" নয়, "Live Checking" ---- */
{
  const F = {
    k_fload: "Live Checking শুরু হচ্ছে…",
    k_fok: "Live Checking সম্পন্ন",
    k_ffb: "Live Checking চালু করা যায়নি (নেট লাগে)। নিচের বাটনে চেপে ছবি তুলুন"
  };
  Object.assign(T.bn, F);
  Object.assign(T.en, {k_fload: "Starting Live Checking…", k_fok: "Live Checking complete", k_ffb: "Live Checking could not start (internet needed). Tap the button below to take a photo"});
}

/* ---- v3.06 ভাগ ৫: ক্যামেরা পাতা — ছোট লোগো+বাংলা শিরোনাম সরিয়ে ডেমোর মতো ওপরে শিরোনাম (NID Front/Back Side), নিচের ডিফল্ট নির্দেশনা বাদ
   (শুধু সমস্যার বার্তা — ক্যামেরা স্থির রাখুন/আরও কাছে ধরুন — আসে); ফেস আইকন হাসিমুখের বদলে ফেস-স্ক্যান আইকন ---- */
{
  KI.face = '<path d="M4 8V6a2 2 0 0 1 2-2h2M16 4h2a2 2 0 0 1 2 2v2M20 16v2a2 2 0 0 1-2 2h-2M8 20H6a2 2 0 0 1-2-2v-2"/><path d="M9 10v1.2M15 10v1.2M12 10v3.2h-1M9.5 16c.7.6 1.5.9 2.5.9s1.8-.3 2.5-.9"/>';
  const N5 = {k_front: "NID Front Side", k_back: "NID Back Side", k_auto: "\u00a0", k_showf: "\u00a0", k_showb: "\u00a0"};
  Object.assign(T.bn, N5); Object.assign(T.en, N5);
  const _ks5 = kScan;
  kScan = function (side) {
    let h = _ks5.apply(this, arguments);
    const ti = t(side === "front" ? "k_front" : "k_back");
    return h.replace(/<div class="klg">[\s\S]*?<\/div>/, "").replace('onclick="kBack()">' + kBk + '</button><b></b>', 'onclick="kBack()">' + kBk + '</button><b>' + ti + '</b>');
  };
}

/* ---- v3.06 ভাগ ৬: তথ্য পাতার ড্রপডাউনের (আয় ইত্যাদি) বাংলা অঙ্কও ইংরেজি অঙ্ক ---- */
{
  const en6 = s => typeof s === "string" ? s.replace(/[\u09E6-\u09EF]/g, d => String(d.charCodeAt(0) - 0x09E6)) : s;
  Object.keys(KOPT).forEach(k => { if (Array.isArray(KOPT[k])) KOPT[k].forEach(o => { if (o && typeof o === "object" && o.bn) o.bn = en6(o.bn); }); });
}

css:
/* FuNPaY v1.9 - বিকাশ স্টাইল ডিজাইন */
:root{--p:#e2136e;--p2:#c70f5f;--pd:#8f0a45;--pl:#fde7f1;--pl2:#fff3f8;--bg:#f3f1f4;--card:#fff;--tx:#2a262b;--mu:#8b8590;--ln:#ece8ed;--red:#e5324b;--grn:#12a15b;--fld:#f2f0f3;
--p1:var(--p);--tint:var(--pl);--g:linear-gradient(180deg,#e2136e,#ee3b8c);--sb:env(safe-area-inset-bottom,0px);--st:env(safe-area-inset-top,0px)}
*{box-sizing:border-box;margin:0;font-family:system-ui,-apple-system,"Noto Sans Bengali","Segoe UI",sans-serif;-webkit-tap-highlight-color:transparent;scrollbar-width:none;-ms-overflow-style:none;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none;touch-action:manipulation}
*::-webkit-scrollbar{display:none;width:0;height:0}
html{-webkit-text-size-adjust:100%;overscroll-behavior:none;background:var(--bg)}
body{background:var(--bg);color:var(--tx);display:flex;justify-content:center;overscroll-behavior:none}
input{-webkit-user-select:text;user-select:text}
button{-webkit-appearance:none;appearance:none;font:inherit;color:inherit}
#app{width:100%;max-width:430px;min-height:100vh;background:var(--bg);padding-bottom:calc(84px + var(--sb));position:relative}
svg.i{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;flex:none}
svg.ci{width:100%;height:100%;display:block}

/* ===== হোম: হেডার + ল্যান্ডস্কেপ ===== */
.hero{background:linear-gradient(180deg,#e2136e 0%,#ea2f82 55%,#f0549a 100%);color:#fff;padding:calc(14px + var(--st)) 16px 74px;position:relative;overflow:hidden}
.scene{position:absolute;left:0;right:0;bottom:0;width:100%;height:132px;display:block;pointer-events:none}
.top{display:flex;align-items:center;gap:10px;position:relative;z-index:1}
.av{width:46px;height:46px;border-radius:50%;background:#fff;color:var(--p);display:grid;place-items:center;font-weight:700;font-size:19px;border:2px solid #ffffffcc;flex:none;cursor:pointer;box-shadow:0 3px 10px #7a0a3a40}
.who{flex:1;min-width:0}
.who small{display:block;font-size:13.5px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-bottom:5px}
.bp{height:32px;padding:0 14px 0 5px;border:0;border-radius:9px;background:#fff;color:#3b3540;font-size:13px;font-weight:600;display:inline-flex;align-items:center;gap:8px;cursor:pointer;min-width:132px;box-shadow:0 3px 10px #7a0a3a33}
.bp u{width:22px;height:22px;border-radius:7px;background:var(--p);color:#fff;display:grid;place-items:center;font-size:13px;font-weight:700;text-decoration:none}
.bp span{display:inline-block;min-width:86px;text-align:left}
.hb{width:44px;height:44px;border-radius:50%;background:#fff;color:var(--p);border:0;display:grid;place-items:center;cursor:pointer;position:relative;flex:none;box-shadow:0 3px 10px #7a0a3a33}
.hb img{width:27px;height:auto;display:block}
.hb em{position:absolute;right:-1px;bottom:-1px;width:14px;height:14px;border-radius:50%;background:#fff;border:1.5px solid #f3c4d9;display:grid;place-items:center}
.hb em:before,.hb em:after{content:"";position:absolute;left:3px;right:3px;height:1.5px;background:var(--p);border-radius:1px}
.hb em:before{top:4px}.hb em:after{top:7.5px}

/* ===== সাদা শিট + সার্ভিস গ্রিড ===== */
.wsheet{background:#fff;border-radius:26px 26px 0 0;margin-top:-30px;position:relative;z-index:2;padding:14px 6px 6px}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:4px 0}
.it{border:0;background:none;display:flex;flex-direction:column;align-items:center;gap:7px;font-size:11.5px;font-weight:500;color:#4a444b;cursor:pointer;padding:8px 2px 6px;line-height:1.25}
.it span{min-height:29px;display:flex;align-items:flex-start;justify-content:center;text-align:center;overflow-wrap:anywhere}
.ic{width:50px;height:50px;border-radius:50%;background:#f3f1f4;display:grid;place-items:center;flex:none;overflow:hidden;color:var(--p)}
.ic>svg.ci{width:30px;height:30px}
.ic>svg.i{width:23px;height:23px}
.more{display:flex;margin:4px auto 10px;height:34px;padding:0 16px;border:1px solid var(--ln);background:#fff;color:var(--p);font-size:12.5px;font-weight:600;align-items:center;justify-content:center;gap:4px;cursor:pointer;border-radius:18px;box-shadow:0 2px 8px #3b1a2a14}
.more svg{width:16px;height:16px}

/* ===== সেকশন, ব্যানার ===== */
.sec{background:#fff;margin-top:8px;padding:6px 0 14px}
.sec.nob{padding-top:16px}
.ttl{padding:12px 16px 10px;font-size:15px;font-weight:700;display:flex;justify-content:space-between;align-items:center;color:#312c33}
.ttl a{font-size:12.5px;color:var(--p);font-weight:600;cursor:pointer}
.ban{display:flex;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;padding:0 14px;scroll-behavior:smooth;overscroll-behavior-x:contain}
.bn{flex:0 0 100%;scroll-snap-align:center;height:136px;border-radius:14px;padding:14px 16px;position:relative;overflow:hidden;color:#fff;display:flex;flex-direction:column;justify-content:flex-end;cursor:pointer}
.bn:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 12% 110%,#ffffff26 0,#ffffff00 55%);pointer-events:none}
.bn svg.d{position:absolute;right:0;top:0;height:100%;width:46%}
.bn small{display:block;font-size:11px;font-weight:600;letter-spacing:.2px;opacity:.92;margin-bottom:3px;position:relative}
.bn b{display:block;font-size:16px;font-weight:700;line-height:1.35;max-width:62%;position:relative}
.bn p{font-size:11.5px;opacity:.9;max-width:60%;margin-top:3px;line-height:1.4;position:relative}
.bn span{align-self:flex-start;background:#fff;color:#c70f5f;font-weight:700;font-size:12px;padding:6px 14px;border-radius:8px;position:relative;margin-top:9px}
.bn.w{flex:none;margin-bottom:10px}
.dts{display:flex;justify-content:center;gap:5px;padding:11px 0 0}.dts i{width:6px;height:6px;border-radius:3px;background:#dcd6dd;transition:width .3s,background .3s}.dts i.on{width:18px;background:var(--p)}
.fv{display:flex;gap:10px;overflow-x:auto;padding:0 16px 4px}
.fc{flex:none;height:44px;padding:0 14px 0 6px;display:flex;align-items:center;gap:8px;border-radius:12px;font-size:13px;font-weight:600;cursor:pointer;background:#fff;border:1px solid var(--ln);max-width:170px;overflow:hidden;white-space:nowrap}
.fc u{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--pl);color:var(--p);font-weight:700;text-decoration:none;flex:none}
.tri{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:12px 16px 0}
.tri div{height:92px;border-radius:12px;display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;padding:12px;font-size:13px;font-weight:700;cursor:pointer;color:#3b3540}
.tri div:nth-child(1){background:#fff3df}.tri div:nth-child(2){background:#e3f5f2}.tri div:nth-child(3){background:#fff6cf}
.tri svg.ci{width:34px;height:34px}

/* ===== লেনদেনের লিস্ট ===== */
.tr{display:flex;align-items:center;gap:12px;background:#fff;padding:12px 16px;border-top:1px solid #f1edf1;min-height:70px}
.tr:first-of-type{border-top:0}
.tr .ic{width:44px;height:44px}.tr .ic>svg.ci{width:27px;height:27px}
.av2{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:17px;text-decoration:none;flex:none}
.tr .m{flex:1;min-width:0}.tr .m b{display:block;font-size:14px;font-weight:600;color:#2f2a30}.tr .m span{display:block;font-size:12.5px;color:#6f6973;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tr .m small{display:block;font-size:11px;color:var(--mu);margin-top:2px}
.tr .r{text-align:right;white-space:nowrap}.tr .r b{display:block;font-size:14.5px;font-weight:700}.tr .r small{font-size:11px;color:var(--mu)}
.pl{color:var(--grn)}.mi{color:var(--red)}
.em{text-align:center;color:var(--mu);padding:30px 20px;font-size:14px}
.sec .em{padding:22px 20px}
.tr.pop{background:var(--pl2);animation:fade .5s ease both}

/* ===== ট্যাব পেজের টপ বার ===== */
.tbar{background:linear-gradient(180deg,#e2136e,#ea2f82);color:#fff;display:flex;align-items:center;justify-content:space-between;padding:calc(10px + var(--st)) 16px 10px;height:calc(56px + var(--st));position:sticky;top:0;z-index:4}
.tbar b{font-size:17px;font-weight:600;position:absolute;left:0;right:0;text-align:center;pointer-events:none}
.tbar .sp{width:30px}.tbar img{width:28px;height:auto;position:relative}
.seg{display:flex;background:#fff;border-bottom:1px solid var(--ln)}
.seg button{flex:1;height:48px;border:0;background:none;font-size:14px;font-weight:600;color:var(--mu);border-bottom:3px solid transparent;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:6px}
.seg button.on{color:var(--p);border-color:var(--p)}
.seg .bd{font-style:normal;background:var(--p);color:#fff;font-size:10.5px;font-weight:700;min-width:18px;height:18px;border-radius:9px;display:grid;place-items:center;padding:0 5px}
.srch{display:flex;gap:10px;padding:14px 16px 4px;background:#fff}
.srch div{flex:1;height:46px;border-radius:10px;background:var(--fld);border:1px solid #e4dfe5;display:flex;align-items:center;gap:8px;padding:0 12px;color:var(--mu)}
.srch input{flex:1;min-width:0;border:0;outline:0;background:none;font-size:13.5px;color:var(--tx)}
.srch button{height:46px;padding:0 14px;border-radius:10px;border:1.5px solid var(--p);background:#fff;color:var(--p);font-size:13px;font-weight:600;cursor:pointer;white-space:nowrap}
.note{font-size:12.5px;color:var(--mu);padding:14px 16px 8px;background:#fff}
#lst{background:#fff;min-height:200px}
.nt{margin:12px 14px 0;background:#fff;border-radius:14px;overflow:hidden;box-shadow:0 2px 10px #3b1a2a14}
.nt .bn{border-radius:0;flex:none;width:100%;height:136px}
.bn:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 12% 110%,#ffffff26 0,#ffffff00 55%);pointer-events:none}
.nt p{padding:12px 14px 2px;font-weight:600;font-size:14px}.nt small{display:block;padding:0 14px 12px;color:var(--mu);font-size:11.5px}

/* ===== আমার FuNPaY ===== */
.prof{background:#fff;display:flex;align-items:center;gap:14px;padding:16px}
.prof .big{width:54px;height:54px;border-radius:50%;background:linear-gradient(135deg,#e2136e,#f0549a);color:#fff;display:grid;place-items:center;font-size:24px;font-weight:700;flex:none}
.pi2{flex:1;min-width:0}.pi2 h3{font-size:17px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pi2 p{font-size:13px;color:#6f6973;margin-top:3px}
.balc{background:#fff;margin-top:1px;padding:14px 16px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid #f1edf1}
.balc span{font-size:13.5px;color:#6f6973;font-weight:500}.balc b{font-size:22px;color:var(--p);font-weight:700}
.msec{background:#fff;margin-top:8px;padding:4px 0 6px}
.msec h4{font-size:12.5px;color:var(--mu);font-weight:500;padding:14px 16px 4px}
.mr{display:flex;align-items:center;gap:16px;width:100%;min-height:54px;border:0;background:none;padding:0 16px;font-size:14.5px;font-weight:500;cursor:pointer;text-align:left;color:#38333a}
.mr:active{background:var(--pl2)}
.mr svg.i{color:#5b555d;width:24px;height:24px}.mr span{flex:1}.mr small{color:var(--mu);font-size:12.5px}
.sw{width:42px;height:24px;border-radius:12px;background:#d6d0d7;position:relative;transition:background .25s;flex:none}
.sw b{position:absolute;left:3px;top:3px;width:18px;height:18px;border-radius:50%;background:#fff;box-shadow:0 1px 4px #0003;transition:transform .25s cubic-bezier(.34,1.56,.64,1)}
.sw.on{background:var(--p)}.sw.on b{transform:translateX(18px)}
em.ag{display:inline-block;font-style:normal;font-size:10.5px;font-weight:700;padding:2px 9px;border-radius:10px;background:linear-gradient(135deg,#fbbf24,#f97316);color:#fff;vertical-align:middle;margin-left:4px}

/* ===== নেভিগেশন ===== */
nav{position:fixed;left:50%;transform:translateX(-50%);bottom:0;width:100%;max-width:430px;height:calc(64px + var(--sb));padding-bottom:var(--sb);display:flex;align-items:center;background:#fff;box-shadow:0 -3px 16px #3b1a2a1c;z-index:5;border-radius:18px 18px 0 0}
nav button{flex:1;height:100%;border:0;background:none;color:#7d777f;font-size:11px;font-weight:500;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;cursor:pointer;white-space:nowrap}
nav button.on{color:var(--p);font-weight:700}
nav button.on svg.i{fill:var(--pl)}
.ni{position:relative;display:grid;place-items:center;width:26px;height:26px}
.ni svg.i{width:25px;height:25px}
.bg{position:absolute;top:-5px;right:-9px;background:var(--p);color:#fff;font-size:10px;font-weight:700;min-width:17px;height:17px;border-radius:9px;display:grid;place-items:center;padding:0 4px;border:1.5px solid #fff}
nav .qrb .ni{width:40px;height:40px;border-radius:13px;background:linear-gradient(135deg,#e2136e,#f0549a);color:#fff;margin-top:-16px;box-shadow:0 6px 14px #e2136e55,0 0 0 4px #fff}
nav .qrb .ni svg.i{width:23px;height:23px;fill:none}
nav .qrb{color:var(--p);font-weight:600;gap:5px}

/* ===== ফুল পেজ (সেন্ড মানি, ক্যাশ আউট ইত্যাদি) ===== */
#sheet{position:absolute;width:0;height:0}
.sh{position:fixed;inset:0;z-index:9;display:flex;justify-content:center;background:#1c0a14a0}
.sh .box{width:100%;max-width:430px;height:100%;background:var(--bg);display:flex;flex-direction:column;overflow:hidden}
.ph{background:linear-gradient(180deg,#e2136e,#ea2f82);color:#fff;display:flex;align-items:center;justify-content:space-between;padding:calc(8px + var(--st)) 8px 8px 6px;height:calc(58px + var(--st));flex:none;position:relative}
.ph b{position:absolute;left:56px;right:56px;text-align:center;font-size:17px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ph img{width:28px;height:auto;margin-right:8px;position:relative}
.pb{width:44px;height:44px;border:0;background:none;color:#fff;display:grid;place-items:center;cursor:pointer;border-radius:50%;position:relative;z-index:1}
.pb:active{background:#ffffff30}.pb svg.i{width:26px;height:26px;stroke-width:2.2}
.pbody{flex:1;overflow-y:auto;overscroll-behavior:contain;padding:0 0 18px}
.pfoot{flex:none;background:#fff;padding:10px 16px calc(10px + var(--sb));box-shadow:0 -3px 14px #3b1a2a14}
.btn{width:100%;height:50px;border:0;border-radius:12px;background:var(--p);color:#fff;font-size:16px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;box-shadow:0 6px 16px #e2136e40}
.btn svg.i{width:22px;height:22px;stroke-width:2.2}
.btn.l{background:#fff;color:var(--p);border:1.5px solid var(--p);box-shadow:none;margin-top:10px}
.pcard{background:#fff;margin-top:8px;padding:14px 16px 16px}
.pcard:first-child{margin-top:0}
.lb{font-size:12.5px;color:var(--mu);font-weight:500;margin:0 2px 8px}
.fld{display:flex;align-items:center;gap:10px;height:52px;border-radius:10px;background:var(--fld);border:1.5px solid #e4dfe5;padding:0 14px;color:var(--mu);transition:border-color .2s,background .2s}
.fld:focus-within{border-color:var(--p);background:#fff}
.fld input,.pcard>input{flex:1;min-width:0;width:100%;height:100%;border:0;background:none;outline:0;font-size:16.5px;color:var(--tx);letter-spacing:.2px}
.fld.big{height:64px}.fld.big input{font-size:30px;font-weight:700;text-align:center;color:var(--p)}
.fld.big u{text-decoration:none;font-size:26px;font-weight:700;color:var(--p)}
.fld.pin input{text-align:center;font-size:24px;letter-spacing:10px;font-weight:700}
.chs{display:flex;flex-wrap:wrap;gap:8px}.chs button{height:38px;padding:0 16px;border-radius:19px;border:1.5px solid var(--ln);background:#fff;font-size:13px;font-weight:600;cursor:pointer;color:#4a444b}.chs button.on{border-color:var(--p);background:var(--pl);color:var(--p)}
.rl p{font-size:12.5px;color:var(--mu);margin:16px 2px 4px}
.rr{display:flex;align-items:center;gap:12px;padding:10px 4px;border-top:1px solid #f1edf1;cursor:pointer;border-radius:8px}
.rr:first-of-type{border-top:0}.rr:active{background:var(--pl2)}
.rr b{display:block;font-size:14.5px;font-weight:600}.rr span{display:block;font-size:12.5px;color:var(--mu);margin-top:1px}
.err{color:var(--red);font-size:13px;font-weight:600;min-height:20px;margin:8px 4px 0}
.rcp{display:flex;align-items:center;gap:12px;padding:4px 0 2px}
.rcp b{display:block;font-size:16px;font-weight:700}.rcp span{display:block;font-size:13px;color:var(--mu);margin-top:2px}
.rcp .ic{width:48px;height:48px}.rcp .av2{width:48px;height:48px;font-size:19px}
.sm{margin-top:12px;border-top:1px dashed #e7e1e8;padding-top:4px}
.sm div{display:flex;justify-content:space-between;gap:14px;padding:10px 0;font-size:14px;border-bottom:1px solid #f4f0f4}
.sm div:last-child{border:0;font-weight:700;font-size:16px;color:var(--p)}.sm span{color:var(--mu);font-weight:500}.sm b{font-weight:600;text-align:right;overflow-wrap:anywhere}.sm div:last-child b{font-weight:700}
.tw{background:#fff4e5;color:#b45309;font-size:12px;font-weight:600;padding:9px 12px;border-radius:10px;margin:0 16px 0}
.ok{text-align:center;padding:26px 16px 6px;position:relative;background:#fff}
.ok .tick{width:76px;height:76px;border-radius:50%;background:var(--grn);color:#fff;display:grid;place-items:center;margin:2px auto 14px;box-shadow:0 8px 22px #12a15b55}
.ok h2{font-size:20px;font-weight:700}.ok .amt{font-size:32px;font-weight:700;margin:8px 0 4px;color:var(--p)}.ok .sv{color:var(--mu);font-size:13.5px}
.ok+.pcard{margin-top:0}
.ok .tick svg.i{width:38px;height:38px}
.tick svg{width:40px;height:40px;fill:none;stroke:#fff;stroke-width:3.4;stroke-linecap:round;stroke-linejoin:round}

/* ===== ডায়ালগ (আপডেট, ফিঙ্গারপ্রিন্ট) ===== */
.sh.dlg{align-items:flex-end}
.sh.dlg .box{height:auto;max-height:92vh;border-radius:24px 24px 0 0;background:#fff;padding:10px 18px calc(18px + var(--sb));overflow:auto}
.grip{width:40px;height:4px;border-radius:4px;background:#ddd6de;margin:0 auto 14px}
.sh.dlg .ok{padding:8px 0 4px}.sh.dlg .ok .tick{background:var(--p);box-shadow:0 8px 22px #e2136e55}
.sh.dlg .btn{margin-top:12px}.sh.dlg .lb{margin-top:12px}
.sh.dlg .fld{margin-top:2px}

/* ===== আমার QR + স্ক্যানার ===== */
.qpage{padding:18px 16px 8px}
.qcard{background:linear-gradient(160deg,#e2136e,#c70f5f 60%,#a00b4a);border-radius:22px;padding:22px 18px 18px;text-align:center;color:#fff;position:relative;overflow:hidden;box-shadow:0 12px 28px #e2136e40}
.qcard:before{content:"";position:absolute;right:-60px;top:-70px;width:200px;height:200px;border-radius:50%;background:#ffffff1c}
.qcard .qav{width:56px;height:56px;border-radius:50%;background:#fff;color:var(--p);display:grid;place-items:center;font-size:25px;font-weight:700;margin:0 auto 8px;position:relative}
.qcard b{display:block;font-size:18px;font-weight:700;position:relative}.qcard span{display:block;font-size:13.5px;opacity:.92;margin:3px 0 14px;position:relative}.qcard small{display:block;font-size:12px;opacity:.9;margin-top:14px;position:relative}
.qwrap{width:228px;height:228px;margin:0 auto;padding:10px;border-radius:20px;background:#fff;position:relative;overflow:hidden}
.qrs{width:100%;height:100%;display:block}
.sh.scanx{background:transparent}
.sh.scanx .box{max-width:none;background:#12050c;position:relative}
html.camon .sh.scanx .box{background:transparent}
html.scanning,html.scanning body,html.scanning #app{background:transparent!important}
html.scanning #app,html.scanning nav{visibility:hidden}
.sct{position:absolute;left:0;right:0;top:0;z-index:3;display:flex;align-items:center;justify-content:space-between;padding:calc(8px + var(--st)) 8px 22px 6px;background:linear-gradient(#000000b0,#00000000);color:#fff}
.sct b{position:absolute;left:56px;right:56px;text-align:center;font-size:17px;font-weight:600;top:calc(20px + var(--st))}
.sct{height:calc(86px + var(--st))}
.pb.tq{background:#ffffff22}.pb.tq.on{background:#fff;color:var(--p)}
.scm{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:22px;padding:0 24px;z-index:1}
.scf{width:min(72vw,292px);aspect-ratio:1;position:relative;border-radius:24px;box-shadow:0 0 0 100vmax #12050cb0;margin-top:-30px}
.scf i{position:absolute;width:40px;height:40px;border:5px solid #ff4f98;transition:border-color .25s}
.scf .k1{left:-3px;top:-3px;border-right:0;border-bottom:0;border-radius:22px 0 0 0}
.scf .k2{right:-3px;top:-3px;border-left:0;border-bottom:0;border-radius:0 22px 0 0}
.scf .k3{left:-3px;bottom:-3px;border-right:0;border-top:0;border-radius:0 0 0 22px}
.scf .k4{right:-3px;bottom:-3px;border-left:0;border-top:0;border-radius:0 0 22px 0}
.scf .sl{position:absolute;left:14px;right:14px;top:8%;height:3px;border-radius:3px;background:linear-gradient(90deg,#ff4f9800,#ff4f98,#ff4f9800);box-shadow:0 0 18px 5px #ff4f9899;animation:sline 2.2s ease-in-out infinite alternate}
@keyframes sline{from{top:8%}to{top:90%}}
.scf .sck{position:absolute;inset:0;display:grid;place-items:center;opacity:0;transform:scale(.4);transition:opacity .2s,transform .35s cubic-bezier(.34,1.56,.64,1)}
.scf .sck svg{width:84px;height:84px;padding:20px;border-radius:50%;background:#12a15b;fill:none;stroke:#fff;stroke-width:3.4;stroke-linecap:round;stroke-linejoin:round;box-shadow:0 8px 24px #12a15b88}
.scf.hit i{border-color:#34d27b}.scf.hit .sl{display:none}.scf.hit .sck{opacity:1;transform:none}
.scp{color:#fff;font-size:14px;text-align:center;text-shadow:0 1px 8px #000a;max-width:300px;line-height:1.5;margin-top:-8px}
.pill{height:42px;padding:0 22px;border-radius:21px;border:0;background:var(--p);color:#fff;font-size:14px;font-weight:700;cursor:pointer;margin-top:-6px}
.pill.ghost{background:#ffffff26;border:1px solid #ffffff66;margin-top:-10px}
.scb{position:absolute;left:0;right:0;bottom:0;z-index:3;display:flex;flex-direction:column;align-items:center;gap:12px;padding:30px 20px calc(18px + var(--sb));background:linear-gradient(#00000000,#000000b8)}
.sctabs{display:flex;background:#ffffff26;border:1px solid #ffffff3d;border-radius:24px;padding:4px;backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}
.sctabs button{height:40px;min-width:118px;padding:0 18px;border:0;border-radius:20px;background:none;color:#ffffffd0;font-size:14px;font-weight:600;cursor:pointer}
.sctabs button.on{background:#fff;color:var(--p)}
.lnk2{border:0;background:none;color:#fff;font-size:13.5px;font-weight:600;padding:6px 10px;cursor:pointer;text-decoration:underline;text-underline-offset:3px;text-decoration-color:#ffffff80}

/* ===== লগ ইন (গোলাপি থিম) ===== */
.fl{--lp:#e2136e;--lp2:#ef3c8d;--lpd:#8f0a45;--lg:linear-gradient(165deg,#e2136e 0%,#c70f5f 50%,#8f0a45 100%);min-height:100vh;min-height:100dvh;position:relative;overflow:hidden;display:flex;flex-direction:column;color:#fff;background:var(--lg)}
.fl *{font-family:system-ui,-apple-system,"Noto Sans Bengali","Segoe UI",sans-serif}
.fl .o1{width:300px;height:300px;right:-110px;top:-90px}.fl .o2{width:260px;height:260px;left:-120px;top:38%;background:#ffffff12;animation-duration:12s}
.fl h1{font-size:34px;font-weight:700;letter-spacing:.3px;margin-top:10px}
.lglogo{width:112px;height:auto;display:block;margin:0 auto;filter:drop-shadow(0 8px 18px #5b0f3a66)}
.land .ltop{position:relative;z-index:2;padding:calc(14px + var(--st)) 16px 0;display:flex;justify-content:flex-end}
.land .lhero{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:10px 28px 30px;position:relative;z-index:1}
.land .lhero p{font-size:15px;opacity:.92;margin-top:8px}
.pills{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:22px}
.pills span{font-size:12px;font-weight:600;padding:7px 14px;border-radius:16px;background:#ffffff26;border:1px solid #ffffff3d}
.lpanel{position:relative;z-index:1;background:#6e0a3a55;backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);border-radius:26px 26px 0 0;padding:20px 20px calc(24px + var(--sb));text-align:center}
.lwb{width:100%;height:54px;border:0;border-radius:12px;background:#fff;color:var(--lp);font-size:17px;font-weight:700;cursor:pointer;box-shadow:0 8px 22px #4b0b2e44;transition:transform .15s}
.lwb:active{transform:scale(.96)}
.lpanel small{display:block;margin-top:12px;font-size:12px;opacity:.88}
.flang{display:inline-flex;gap:4px;align-items:center;font-size:12px}
.flang button{height:28px;min-width:42px;padding:0 9px;border-radius:6px;border:1px solid #c9c4cb;background:transparent;color:#6c6670;font-size:12px;font-weight:600;cursor:pointer}
.flang button.on{border-color:var(--lp);color:var(--lp);background:#fff}
.flang.w button{border-color:#ffffff77;color:#ffffffcc}.flang.w button.on{background:#fff;color:var(--lp);border-color:#fff}
.fl.light{background:#f7f5f7;color:#26212a}
.fbar{display:flex;align-items:center;justify-content:space-between;padding:calc(12px + var(--st)) 14px 0}
.fback{width:40px;height:40px;border:0;background:none;color:var(--lp);display:grid;place-items:center;cursor:pointer;border-radius:50%}
.fback:active{background:#e2136e1a}.fback svg{width:26px;height:26px;stroke-width:2.2}
.fbody{flex:1;padding:18px 22px 20px}
.fbody .mini{width:54px;height:auto;display:block;margin:6px 0 20px}
.fbody h2{font-size:23px;line-height:1.4;font-weight:500;color:#2b2530}
.fbody .sub{font-size:13px;color:#8a8490;margin-top:6px}
.fbody label{display:block;font-size:12.5px;color:#8a8490;margin:22px 0 8px}
.cfield{height:50px;border-radius:6px;background:#ece9ed;display:flex;align-items:center;gap:12px;padding:0 14px;font-size:15px;color:#3a343f}
.flag{width:22px;height:22px;border-radius:50%;background:radial-gradient(circle at 44% 50%,#e0243c 0 36%,#0a7a4c 38%);display:block;flex:none}
.pfield{display:flex;align-items:center;gap:12px;border-bottom:1.5px solid #ddd8de;transition:border-color .2s}
.pfield:focus-within{border-color:var(--lp)}
.pfield b{font-size:17px;font-weight:600;color:#2b2530}
.fl .pfield input{flex:1;min-width:0;height:48px;border:0;background:transparent;font-size:17px;color:#2b2530;outline:0;padding:0;letter-spacing:.3px}
.fl .pfield input::placeholder{color:#b3adb8}
.le{min-height:20px;font-weight:700;font-size:14px;color:#ffd0d6;margin-top:4px;position:relative}
.fl.light .le{color:#d92d4f;min-height:22px;margin-top:10px;font-size:13.5px;font-weight:600}
.terms{font-size:12px;color:#8a8490;margin-top:26px}
.lnk{border:0;background:none;color:var(--lp);font-size:14px;font-weight:700;padding:14px 0 6px;cursor:pointer}
.nbar{position:sticky;bottom:0;width:100%;height:calc(54px + var(--sb));border:0;background:#8a8490;color:#fff;font-size:16px;font-weight:600;display:flex;align-items:center;justify-content:space-between;padding:0 20px var(--sb);cursor:pointer;transition:background .2s}
.nbar:active{background:#6f6a74}.nbar svg{width:24px;height:24px;stroke-width:2}
.fl.light:focus-within .nbar{background:var(--lp)}
.nbar.lb2{margin:0;border-radius:0;background:var(--lp)}
.nbar.ld,.btn.ld{opacity:.6;pointer-events:none;background-image:linear-gradient(110deg,transparent 30%,#ffffff55 50%,transparent 70%);background-size:200% 100%;animation:shim 1s linear infinite}
@keyframes shim{from{background-position:200% 0}to{background-position:-200% 0}}
.pinp .phead{position:relative;z-index:1;text-align:center;padding:calc(26px + var(--st)) 20px 22px;display:flex;flex-direction:column;align-items:center;gap:4px}
.pinp .lglogo{width:76px}
.pinp .phead b{font-size:19px;margin-top:8px}.pinp .phead span{font-size:14px;opacity:.9}
.psheet{position:relative;z-index:1;flex:1;background:#fff;color:#26212a;border-radius:28px 28px 0 0;padding:20px 18px calc(16px + var(--sb));display:flex;flex-direction:column;align-items:center;text-align:center}
.psheet .pl{font-weight:700;font-size:15px;color:#3a343f}
.dots{display:flex;gap:13px;margin:16px 0 2px;position:relative}
.dt{width:14px;height:14px;border-radius:50%;border:2px solid #efb3cf;background:transparent;transition:background .15s,transform .25s cubic-bezier(.34,1.56,.64,1),border-color .15s}
.dt.on{background:var(--lp);border-color:var(--lp);transform:scale(1.3)}
.psheet .le{min-height:22px;color:#d92d4f;font-weight:700;font-size:13.5px;margin-top:4px}
.kp{display:grid;grid-template-columns:repeat(3,68px);gap:12px 18px;margin-top:4px}
.kp button{width:68px;height:68px;border-radius:50%;border:0;background:#f8eef3;color:#3a1f2e;font-size:25px;font-weight:600;cursor:pointer;display:grid;place-items:center;transition:transform .15s,background .2s}
.kp button:active{background:#f4cfe0}.kp .z{visibility:hidden}.kp svg{stroke:var(--lp)}
.psheet .lrow{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-top:12px}
.chip{height:34px;padding:0 14px;border-radius:17px;border:1px solid #f0c2d6;background:#fff;color:var(--lp);font-size:12.5px;font-weight:600;margin-top:4px;cursor:pointer}
.psheet .dm{display:block;margin-top:10px;font-size:11.5px;color:#8a8490}
.login{min-height:100vh;background:var(--g);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px 20px;text-align:center}
@media (max-height:700px){.pinp .phead{padding-top:14px;padding-bottom:12px}.pinp .lglogo{width:76px}}

/* ===== অ্যানিমেশন ===== */
@keyframes pgin{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@keyframes pop{from{opacity:0;transform:scale(.8)}to{opacity:1;transform:none}}
@keyframes fade{from{opacity:0}to{opacity:1}}
@keyframes fadeo{from{opacity:1}to{opacity:0}}
@keyframes up{from{transform:translateY(100%)}to{transform:none}}
@keyframes down{from{transform:none}to{transform:translateY(100%)}}
@keyframes slin{from{transform:translateX(100%)}to{transform:none}}
@keyframes slout{from{transform:none}to{transform:translateX(100%)}}
@keyframes shake{20%{transform:translateX(-10px)}40%{transform:translateX(10px)}60%{transform:translateX(-6px)}80%{transform:translateX(6px)}}
@keyframes draw{to{stroke-dashoffset:0}}
@keyframes tickpop{from{transform:scale(0) rotate(-30deg)}to{transform:none}}
@keyframes conf{0%{opacity:1;transform:translate(0,0) scale(1)}100%{opacity:0;transform:translate(var(--x),var(--y)) scale(.3)}}
@keyframes rowpop{from{opacity:0;transform:translateX(-34px) scale(.92)}to{opacity:1;transform:none}}
@keyframes ring{0%{transform:scale(1);opacity:.5}100%{transform:scale(1.5);opacity:0}}
@keyframes toast{0%{opacity:0;transform:translate(-50%,20px)}12%{opacity:1;transform:translate(-50%,0)}86%{opacity:1}100%{opacity:0}}
@keyframes lg{from{opacity:0;transform:scale(.5) rotate(-10deg)}to{opacity:1;transform:none}}
@keyframes orb{from{transform:translate(0,0) scale(1)}to{transform:translate(-26px,20px) scale(1.14)}}
.it,.fc,.tri div,.tr,.hb,.av,.btn,.chs button,.bp,.more,.mr,.rr,.srch button,.seg button,nav button,.kp button,.chip,.pill,.pb{transition:transform .16s cubic-bezier(.3,1,.4,1),background-color .2s,border-color .2s,color .2s}
.it:active,.fc:active,.tri div:active,.hb:active,.av:active,.more:active,.chip:active,.pill:active,.bn:active{opacity:.7}
.btn:active{opacity:.88}
nav button:active{opacity:.6}
.sh{animation:fade .26s ease both}
.sh .box{animation:slin .28s cubic-bezier(.22,1,.36,1) both}
.sh.dlg .box{animation:up .3s cubic-bezier(.22,1,.36,1) both}
.sh.scanx .box{animation:fade .3s ease both}
.sh.re,.sh.re .box{animation:none}
.sh.out{animation:fadeo .24s ease both}.sh.out .box{animation:slout .24s cubic-bezier(.5,0,.9,.4) both}
.sh.dlg.out .box{animation:down .23s cubic-bezier(.5,0,.9,.4) both}
.sh.scanx.out .box{animation:fadeo .2s ease both}
.sh .box.shake,.sh.re .box.shake{animation:shake .42s}
.stp.go{animation:fade .2s ease both}
.tick{animation:pop .3s ease-out both}
.tick.d path{stroke-dasharray:30;stroke-dashoffset:30;animation:draw .4s .15s ease forwards}
.dots.shake{animation:shake .45s}
.toast{position:fixed;left:50%;bottom:calc(92px + var(--sb));transform:translateX(-50%);background:#2a1620;color:#fff;padding:12px 20px;border-radius:22px;font-size:13px;font-weight:600;z-index:30;animation:toast 2.3s both;max-width:90%;text-align:center;box-shadow:0 8px 24px #0004}
@media(prefers-reduced-motion:reduce){*,*:before{animation-duration:.01ms!important;animation-delay:0s!important;transition-duration:.01ms!important}}
.dl div{display:flex;justify-content:space-between;gap:14px;padding:10px 0;font-size:14px;border-bottom:1px solid #f4f0f4}.dl div:last-child{border:0}.dl span{color:var(--mu)}.dl b{font-weight:600;text-align:right;overflow-wrap:anywhere}
.sh.dlg input{width:100%;height:50px;padding:0 14px;border-radius:10px;border:1.5px solid #e4dfe5;background:var(--fld);font-size:20px;text-align:center;letter-spacing:8px;outline:0;color:var(--tx)}
.sh.dlg input:focus{border-color:var(--p);background:#fff}

.pg.in{animation:fade .22s ease both}

/* =====================================================================
   FuNPaY v2.0 - কাচের মতো স্বচ্ছ (glass) ডিজাইন, নতুন ব্যানার, মসৃণ অ্যানিমেশন
   ===================================================================== */
:root{--gl:rgba(255,255,255,.66);--gl2:rgba(255,255,255,.84);--glb:1px solid rgba(255,255,255,.75);--gsh:0 8px 26px rgba(170,20,95,.10),inset 0 1px 0 rgba(255,255,255,.85);--ease:cubic-bezier(.22,1,.36,1);--spring:cubic-bezier(.34,1.56,.64,1)}
html,body{background:#f7eef4}
body:before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(70vmax 46vmax at 96% -6%,rgba(226,19,110,.24),transparent 62%),radial-gradient(54vmax 44vmax at -14% 40%,rgba(150,95,235,.14),transparent 62%),radial-gradient(56vmax 40vmax at 104% 86%,rgba(255,140,175,.22),transparent 62%),linear-gradient(180deg,#fcedf4,#f6eff6 46%,#f5f0f5)}
#app{background:transparent;padding-bottom:0}#app.au{padding-bottom:calc(98px + var(--sb))}
.pg{padding-bottom:6px}

/* গ্লাস সারফেস */
.wsheet,.sec,.pcard,.msec,.prof,.balc,.nt,.pg>.seg,.pg>.srch,.pg>.note,.pg>#lst{background:var(--gl);-webkit-backdrop-filter:blur(18px) saturate(1.5);backdrop-filter:blur(18px) saturate(1.5);border:var(--glb);box-shadow:var(--gsh)}
.wsheet{margin:-36px 10px 0;border-radius:24px;padding:14px 4px 4px}
.sec{margin:10px 10px 0;border-radius:22px;padding:4px 0 14px}
.sec.nob{padding-top:14px}
.tr{background:transparent;border-top:1px solid rgba(160,60,110,.08)}
.pcard{margin:10px 12px 0;border-radius:20px}
.pcard:first-child,.prg+.pcard{margin-top:12px}
.msec{margin:10px 12px 0;border-radius:20px;padding:4px 0 6px}
.prof{margin:12px 12px 0;border-radius:20px 20px 0 0}
.balc{margin:0 12px;border-radius:0 0 20px 20px;border-top:1px solid rgba(160,60,110,.08)}
.pg>.seg{margin:10px 10px 0;border-radius:18px 18px 0 0;overflow:hidden;border-bottom:1px solid rgba(160,60,110,.08)}
.pg>.srch{margin:0 10px;border-radius:0;border-top:0;border-bottom:0;box-shadow:none}
.pg>.note{margin:0 10px;border-radius:0;border-top:0;border-bottom:0;box-shadow:none}
.pg>#lst{margin:0 10px;border-radius:0 0 20px 20px;border-top:0}
.nt{margin:12px 12px 0;border-radius:20px}
.ic{background:rgba(255,255,255,.7);box-shadow:inset 0 0 0 1px rgba(226,19,110,.07),0 2px 8px rgba(160,20,95,.07)}
.more{background:rgba(255,255,255,.7)}
.fc{background:rgba(255,255,255,.7);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
.fld{background:rgba(255,255,255,.7);border:1.5px solid rgba(226,19,110,.14)}
.fld:focus-within{background:#fff;border-color:var(--p);box-shadow:0 0 0 4px rgba(226,19,110,.10)}
.chs button{background:rgba(255,255,255,.75)}
.srch div{background:rgba(255,255,255,.7)}

/* হেডার (গোলাপি কাচ) */
.hero{background:linear-gradient(165deg,#e2136e 0%,#ee3584 60%,#f4609f 100%)}
.hero:before,.hero:after{content:"";position:absolute;border-radius:50%;background:rgba(255,255,255,.12);pointer-events:none}
.hero:before{width:230px;height:230px;right:-70px;top:-100px}.hero:after{width:150px;height:150px;left:-56px;top:46px;background:rgba(255,255,255,.08)}
.bp{background:rgba(255,255,255,.9);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}
.hb{background:rgba(255,255,255,.92)}
.tbar,.ph{background:linear-gradient(180deg,rgba(226,19,110,.96),rgba(238,56,138,.9));-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);border-radius:0 0 22px 22px;box-shadow:0 8px 22px rgba(190,20,100,.18)}
.av svg.i,.big svg.i,.av2 svg.i,.qav svg.i,.fc u svg.i{width:58%;height:58%;stroke-width:2}
.big svg.i{stroke:#fff}

/* ফ্লোটিং গ্লাস নেভিগেশন */
nav{left:50%;bottom:calc(10px + var(--sb));width:calc(100% - 24px);max-width:406px;height:66px;padding-bottom:0;border-radius:26px;background:rgba(255,255,255,.74);-webkit-backdrop-filter:blur(22px) saturate(1.6);backdrop-filter:blur(22px) saturate(1.6);border:var(--glb);box-shadow:0 12px 32px rgba(150,20,90,.20),inset 0 1px 0 rgba(255,255,255,.9)}
nav button.on svg.i{fill:rgba(226,19,110,.14)}
nav button.on .ni{animation:navpop .45s var(--spring)}
nav .qrb .ni{box-shadow:0 8px 18px rgba(226,19,110,.42),0 0 0 4px rgba(255,255,255,.75)}
nav.fx{animation:navin .5s var(--ease) both}
@keyframes navin{from{opacity:0;transform:translate(-50%,28px)}to{opacity:1;transform:translate(-50%,0)}}
@keyframes navpop{0%{transform:scale(.7)}60%{transform:scale(1.18)}100%{transform:scale(1)}}

/* ব্যানার: পরিষ্কার, সমান রঙের পরিবার, কাচের আইকন */
.ban{gap:10px;padding:0 12px 2px}
.bn{height:140px;padding:0;border-radius:20px;flex-direction:row;align-items:center;justify-content:space-between;color:#fff;box-shadow:0 10px 24px rgba(160,20,95,.22);transition:transform .2s var(--ease)}
.bn:active{transform:scale(.985);opacity:1}
.bn.b0{background:linear-gradient(125deg,#d80f66,#f23e86)}
.bn.b1{background:linear-gradient(125deg,#8c1456,#c92a76)}
.bn.b2{background:linear-gradient(125deg,#34162f,#6a1f4e)}
.bn:before{inset:auto;right:-46px;bottom:-70px;width:210px;height:210px;border-radius:50%;background:rgba(255,255,255,.11)}
.bn:after{content:"";position:absolute;left:-30px;top:-52px;width:120px;height:120px;border-radius:50%;background:rgba(255,255,255,.07);pointer-events:none}
.bn .bt{position:relative;z-index:1;flex:1;min-width:0;padding:16px 4px 16px 18px;display:flex;flex-direction:column;align-items:flex-start;gap:4px}
.bn small{font-size:11px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;opacity:.82;margin:0}
.bn .bt b{font-size:17px;line-height:1.4;font-weight:700;max-width:100%;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.bn .bt span{align-self:flex-start;margin-top:8px;background:#fff;color:#c70f5f;font-weight:700;font-size:12.5px;padding:7px 8px 7px 14px;border-radius:20px;display:inline-flex;align-items:center;gap:2px;box-shadow:0 4px 12px rgba(0,0,0,.14)}
.bn.b2 .bt span{color:#6a1f4e}
.bn .bt span svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.bn svg.bv{position:relative;z-index:1;flex:none;width:92px;height:92px;margin-right:16px;padding:20px;border-radius:50%;background:rgba(255,255,255,.17);border:1px solid rgba(255,255,255,.4);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);fill:none;stroke:#fff;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 8px 18px rgba(0,0,0,.12);animation:bfloat 4.5s ease-in-out infinite}
@keyframes bfloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}
.nt .bn{border-radius:0;height:128px;box-shadow:none}
.nt .bn:active{transform:none}
.dts i.on{box-shadow:0 2px 8px rgba(226,19,110,.35)}

/* সেন্ড মানি / পেমেন্ট ফ্লো */
.sh{background:rgba(48,8,30,.36);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}
.sh.scanx{background:transparent;-webkit-backdrop-filter:none;backdrop-filter:none}
.sh .box{background:linear-gradient(180deg,#fcedf4,#f6eff6 50%,#f5f0f5)}
.sh.scanx .box{background:#12050c}
html.camon .sh.scanx .box{background:transparent}
.sh.dlg .box{background:rgba(255,255,255,.9);-webkit-backdrop-filter:blur(26px) saturate(1.5);backdrop-filter:blur(26px) saturate(1.5);border:var(--glb);border-bottom:0}
.prg{height:4px;margin:0 12px;margin-top:10px;border-radius:4px;background:rgba(226,19,110,.12);overflow:hidden}
.prg i{display:block;height:100%;border-radius:4px;background:linear-gradient(90deg,#e2136e,#f2569a);transition:width .45s var(--ease)}
.rcp .vf{margin-left:auto;width:26px;height:26px;border-radius:50%;background:var(--grn);display:grid;place-items:center;flex:none;font-style:normal;animation:pop .4s var(--spring) .15s both}
.rcp .vf svg{width:15px;height:15px;fill:none;stroke:#fff;stroke-width:3.4;stroke-linecap:round;stroke-linejoin:round}
.fld.big{height:78px;border-radius:18px}
.fld.big input{font-size:38px}.fld.big u{font-size:30px}
.avl{margin:12px 2px 0;font-size:13px;color:var(--mu)}.avl b{color:var(--tx);font-weight:700}
.fee{min-height:18px;margin:4px 2px 0;font-size:12.5px;color:#b45309;font-weight:600}
.qa{display:flex;gap:8px;margin-top:10px;overflow-x:auto}
.qa button{flex:none;height:36px;padding:0 15px;border-radius:18px;border:1.5px solid rgba(226,19,110,.2);background:rgba(255,255,255,.75);color:var(--p);font-size:13px;font-weight:700;cursor:pointer}
.qa button:active{background:var(--pl);transform:scale(.94)}
.pinc{text-align:center;padding-bottom:12px}
.pinc .lb.c{text-align:center;font-size:13.5px;margin-bottom:2px}
.pinc .dots{justify-content:center;margin:14px 0 2px}
.pinc .err.c{text-align:center;min-height:22px;margin-top:6px}
.pinc .kp{justify-content:center;margin:2px auto 0;grid-template-columns:repeat(3,64px);gap:10px 22px}
.pinc .kp button{width:64px;height:64px;font-size:23px;background:rgba(255,255,255,.85);box-shadow:0 2px 8px rgba(160,20,95,.08)}
.pinc .kp button:active{background:#f6cfe1;transform:scale(.92)}
.pinc .dt{width:13px;height:13px}
.btn{height:52px;border-radius:16px;background:linear-gradient(180deg,#ec2c80,#dc1068);box-shadow:0 8px 20px rgba(226,19,110,.34),inset 0 1px 0 rgba(255,255,255,.3)}
.btn.dis{opacity:.45;box-shadow:none}
.btn:active{transform:scale(.98);opacity:.92}
.btn.l{background:rgba(255,255,255,.8);box-shadow:none}
.pfoot{background:rgba(255,255,255,.78);-webkit-backdrop-filter:blur(18px);backdrop-filter:blur(18px);border-top:1px solid rgba(255,255,255,.8)}
.ok{background:transparent}
.ok .tick{box-shadow:0 10px 26px rgba(18,161,91,.4)}
.ok .tick:after{content:"";position:absolute;inset:-8px;border-radius:50%;border:2px solid rgba(18,161,91,.35);animation:ring 1.3s ease-out .35s 2 both}
.ok .tick{position:relative}
.nl>div{display:flex;justify-content:space-between;gap:12px;padding:10px 2px;font-size:13px;border-bottom:1px solid rgba(160,60,110,.1)}
.nl span{color:var(--mu)}.nl b{font-weight:700}.nl b.g{color:var(--grn)}.nl b.r{color:var(--red)}
.nl{margin-top:6px}

/* ব্যাকগ্রাউন্ড ইন্টারনেট বার + টোস্ট */
#offbar{position:fixed;left:12px;right:12px;top:calc(10px + var(--st));z-index:40;margin:auto;max-width:406px;padding:9px 14px;border-radius:14px;background:rgba(42,22,32,.9);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);color:#fff;font-size:13px;font-weight:600;text-align:center;transform:translateY(-140%);transition:transform .35s var(--ease);pointer-events:none}
#offbar.on{transform:none}
.toast{left:16px;right:16px;margin:auto;width:max-content;max-width:calc(100% - 32px);transform:none;bottom:calc(102px + var(--sb));background:rgba(42,22,32,.92);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);animation:toastin .35s var(--ease) both;white-space:normal;line-height:1.45}
.toast.o{animation:toastout .25s ease both}
@keyframes toastin{from{opacity:0;transform:translateY(16px) scale(.96)}to{opacity:1;transform:none}}
@keyframes toastout{from{opacity:1}to{opacity:0;transform:translateY(8px)}}

/* অ্যানিমেশন: পেজ, গ্রিড, লিস্ট, টাচ */
.pg.in{animation:pgin2 .38s var(--ease) both}
@keyframes pgin2{from{opacity:0;transform:translateY(14px) scale(.99)}to{opacity:1;transform:none}}
@keyframes rise{from{opacity:0;transform:translateY(14px) scale(.9)}to{opacity:1;transform:none}}
.pg.in .it{animation:rise .5s var(--ease) both;animation-delay:calc(var(--i,0)*38ms + 80ms)}
.pg.in .tr,.pg.in .tri div,.pg.in .fc{animation:rise .5s var(--ease) both;animation-delay:.18s}
.pg.in .tr:nth-child(2){animation-delay:.25s}.pg.in .tr:nth-child(3){animation-delay:.32s}
.it:active,.fc:active,.tri div:active,.mr:active,.rr:active{transform:scale(.95);opacity:1}
.it:active .ic{background:var(--pl)}
.tr{transition:background .2s}.tr:active{background:rgba(226,19,110,.06)}
.sh .box{animation:slin .34s var(--ease) both}
.sh.dlg .box{animation:up .36s var(--ease) both}
.sh.re,.sh.re .box{animation:none}
.stp.go{animation:stepin .32s var(--ease) both}
@keyframes stepin{from{opacity:0;transform:translateX(26px)}to{opacity:1;transform:none}}
.dots.shake,.sh .box.shake{animation:shake .42s}
.dt.on{animation:dtpop .3s var(--spring)}
@keyframes dtpop{from{transform:scale(.6)}to{transform:scale(1.3)}}
.sw,.sw b{transition-duration:.3s}
@media(prefers-reduced-motion:reduce){.bn svg.bv{animation:none}}
.ban{padding-bottom:16px;margin-bottom:-14px}
.bn{box-shadow:0 8px 14px -8px rgba(160,20,95,.45)}
.pinc .dt{border-color:#e9a9c6;background:transparent}
.pinc .dt.on{background:var(--p);border-color:var(--p)}
.pinc .kp svg{stroke:var(--p)}
.qa{gap:6px}.qa button{padding:0 11px;font-size:12.5px}


/* =====================================================================
   FuNPaY v2.1 - স্থিতিশীলতা, কম অ্যানিমেশন, ছোট ও গোছানো সাইজ
   ===================================================================== */
/* 1) ভারী blur বন্ধ (ফোনে ল্যাগের প্রধান কারণ ছিল), তার বদলে প্রায় অস্বচ্ছ সাদা */
*{-webkit-backdrop-filter:none!important;backdrop-filter:none!important}
html.scanning body:before,html.scanning .scene{display:none!important}
:root{--gl:#fff;--gsh:0 3px 12px rgba(170,20,95,.08)}
.wsheet,.sec,.pcard,.msec,.prof,.balc,.nt,.pg>.seg,.pg>.srch,.pg>.note,.pg>#lst{background:#fff;border:1px solid rgba(160,60,110,.06);box-shadow:var(--gsh)}
.fc,.ic,.more,.chs button,.srch div,.qa button,.kp button{background:#fff}
.pinc .kp button{background:#f8eef3}
.ic{box-shadow:none;background:#f6f1f5}
nav{background:#fff;box-shadow:0 6px 18px rgba(150,20,90,.16)}
.tbar,.ph{background:linear-gradient(180deg,#e2136e,#ea2f82);box-shadow:0 4px 12px rgba(190,20,100,.16)}
.sh{background:rgba(48,8,30,.5)}
.sh.dlg .box{background:#fff}
.pfoot{background:#fff}
.lpanel{background:rgba(110,10,58,.45)}
#offbar,.toast{background:rgba(42,22,32,.96)}
.sctabs{background:rgba(255,255,255,.22)}

/* 2) লগইনের চৌকো বক্স ঠিক: .orb এর মূল স্টাইল হারিয়ে গিয়েছিল */
.orb{position:absolute;border-radius:50%;background:rgba(255,255,255,.08);pointer-events:none;z-index:0}
.fl .o2{background:rgba(255,255,255,.06)}

/* 3) অ্যানিমেশন শান্ত ও ছোট */
.pg.in{animation:fade .16s ease both}
nav button.on .ni{animation:navpop .26s var(--spring)}
.sh{animation-duration:.2s}
.sh .box{animation-duration:.26s;will-change:transform}
.sh.dlg .box{animation-duration:.28s}
.stp.go{animation:stepin2 .2s var(--ease) both}
@keyframes stepin2{from{opacity:0;transform:translateX(14px)}to{opacity:1;transform:none}}
.tr.pop{animation:fade .3s ease both}
.ok .tick:after{animation-iteration-count:1}

/* 4) সাইজ ছোট ও গোছানো */
.hero{padding:calc(10px + var(--st)) 14px 58px}
.scene{height:100px}
.av{width:40px;height:40px;font-size:17px}
.hb{width:38px;height:38px}.hb img{width:23px}
.bp{height:28px;font-size:12px;min-width:116px}
.wsheet{margin:-30px 10px 0;padding:10px 4px 2px}
.it{gap:5px;font-size:11px;padding:6px 2px 4px}
.it span{min-height:26px}
.ic{width:42px;height:42px}.ic>svg.ci{width:26px;height:26px}.ic>svg.i{width:20px;height:20px}
.more{height:30px;font-size:12px;margin:2px auto 8px;padding:0 14px}
.ttl{padding:10px 14px 8px;font-size:14px}
.bn{height:112px;border-radius:16px}
.bn .bt{padding:12px 4px 12px 14px}
.bn .bt b{font-size:15px}
.bn .bt span{padding:5px 6px 5px 12px;font-size:12px;margin-top:6px}
.bn svg.bv{width:68px;height:68px;padding:16px;margin-right:14px}
.fc{height:38px;font-size:12.5px}.fc u{width:28px;height:28px}
.tri div{height:74px;font-size:12.5px;padding:10px}
nav{height:60px;border-radius:22px}
#app.au{padding-bottom:calc(84px + var(--sb))}
.btn{height:48px;border-radius:14px;font-size:15px}
.ph{height:calc(52px + var(--st))}
.pcard{margin:8px 12px 0}
.fl h1{font-size:30px}
.lglogo{width:96px}
.lwb{height:50px;font-size:16px}
.pinp .phead{padding:calc(18px + var(--st)) 20px 14px}
.pinp .lglogo{width:64px}
.psheet{padding-top:16px}
.kp{grid-template-columns:repeat(3,60px);gap:10px 18px}
.kp button{width:60px;height:60px;font-size:22px}
.pinc .kp{grid-template-columns:repeat(3,58px);gap:8px 20px}
.pinc .kp button{width:58px;height:58px;font-size:21px}
@media (max-height:700px){.kp{grid-template-columns:repeat(3,54px)}.kp button{width:54px;height:54px;font-size:20px}.pinc .kp{grid-template-columns:repeat(3,52px)}.pinc .kp button{width:52px;height:52px}}

/* 5) ধরে রাখুন বাটন (বিকাশ স্টাইল) */
.btn.hold{position:relative;overflow:hidden;touch-action:none;display:flex;align-items:center;justify-content:center}
.btn.hold i{position:absolute;left:0;top:0;bottom:0;width:0;background:rgba(255,255,255,.34);transition:width .12s linear}
.btn.hold.hd i{width:100%;transition:width .7s linear}
.btn.hold span{position:relative}
.hint{text-align:center;color:var(--mu);font-size:12.5px;margin:12px 16px 0}
.sm.one{margin-top:8px}

/* =====================================================================
   FuNPaY v2.2 - নেটিভ অ্যাপের মতো স্থির স্ক্রল, বিকাশ স্টাইল ধাপ/রিসিট, PIN পেজ
   ===================================================================== */
/* স্ক্রল ভেতরের কন্টেইনারে: টানলে স্ক্রিন বড়/নরম হবে না, ওয়েবসাইটের মতো লাগবে না */
html,body{height:100%;width:100%;overflow:hidden;overscroll-behavior:none;position:fixed;inset:0}
body{display:block}
#app{position:fixed;top:0;bottom:0;left:0;right:0;margin:0 auto;width:100%;max-width:430px;min-height:0;height:auto;overflow-y:auto;overflow-x:hidden;overscroll-behavior:none;-webkit-overflow-scrolling:touch}
.fl{min-height:100%}

/* লগইন PIN পেজ: ওপরে লোগো মাঝখানে, নিচে PIN আর কিপ্যাড */
.pinp .phead{flex:1;justify-content:center;padding:calc(20px + var(--st)) 20px 16px}
.pinp .phead b{font-size:20px}
.psheet{flex:none;padding:20px 18px calc(18px + var(--sb))}
.psheet .pl{font-size:15px}
.dots{margin:18px 0 4px;gap:14px}
.kp{grid-template-columns:repeat(3,66px);gap:12px 22px;margin-top:6px}
.kp button{width:66px;height:66px;font-size:24px}
.kp .fpk{background:#fde7f1}
.kp .fpk svg{width:30px;height:30px}
.kp .fpk.dim{opacity:.45}
.psheet .lrow{margin-top:14px}
@media (max-height:720px){.kp{grid-template-columns:repeat(3,56px);gap:8px 20px}.kp button{width:56px;height:56px;font-size:21px}.pinp .lglogo{width:56px}}

/* ফর্ম ঘর: স্পষ্ট ও গোছানো */
.fld{height:54px;border-radius:14px;border:1.5px solid #e6dce3;background:#fff}
.fld.big{height:auto;border:0;border-bottom:2px solid var(--p);border-radius:0;background:transparent;padding:6px 0;justify-content:center;box-shadow:none}
.fld.big:focus-within{box-shadow:none}
.fld.big input{font-size:34px;font-weight:700;text-align:center;width:60%}
.fld.big u{font-size:28px;font-weight:700;color:var(--p);text-decoration:none}
.avl{text-align:center}
.qa{justify-content:center}
.pcard .err.c{color:#d92d4f}

/* নিচে ধরে রাখুন বাটন (বিকাশ স্টাইল): সাদা ভেতর, গোলাপি বর্ডার, আঙুলের চিহ্ন, ধীরে ধীরে ভরে */
.holdw{padding:8px 16px 4px}
.holdw p{text-align:center;font-size:12.5px;color:var(--mu);margin:0 0 10px}
button.hold{position:relative;width:100%;height:58px;border-radius:29px;border:2px solid var(--p);background:#fff;color:var(--p);overflow:hidden;display:flex;align-items:center;justify-content:center;gap:10px;font-size:16px;font-weight:700;touch-action:none;box-shadow:0 6px 16px rgba(226,19,110,.16);animation:hpulse 2s ease-in-out infinite}
button.hold i{position:absolute;left:0;top:0;bottom:0;width:0;background:rgba(226,19,110,.24);transition:width .15s linear;font-style:normal}
button.hold.hd i{width:100%;transition:width 1s linear}
button.hold.hd{animation:none}
button.hold.ld{opacity:.6;pointer-events:none}
button.hold svg,button.hold b{position:relative;z-index:1}
button.hold svg.i{width:26px;height:26px;stroke:var(--p)}
@keyframes hpulse{0%,100%{box-shadow:0 6px 16px rgba(226,19,110,.16),0 0 0 0 rgba(226,19,110,.28)}60%{box-shadow:0 6px 16px rgba(226,19,110,.16),0 0 0 9px rgba(226,19,110,0)}}

/* সফল পেজ / রিসিট */
.rct{padding:6px 0 10px}
.rct .ok{padding:14px 0 4px}
.rct .ok .tick{width:78px;height:78px}
.rct .ok h2{font-size:19px;margin-top:12px}
.rct .ok .sv{font-size:13px;color:var(--mu);margin-top:2px}
.rct .ok .amt{font-size:32px;font-weight:700;color:var(--p);margin-top:6px}
.rcc{margin-top:14px;border-radius:18px;position:relative}
.rcc .rcp{padding:2px 0 8px;border-bottom:1px dashed #e7e1e8;margin-bottom:2px}
.rcc .dl div{padding:9px 0;font-size:13.5px}
.nbv{display:inline-flex;align-items:center;gap:6px}
.nbv em{font-style:normal}
.eye{border:0;background:none;color:var(--mu);width:28px;height:28px;display:grid;place-items:center;border-radius:50%;cursor:pointer}
.eye svg.i{width:19px;height:19px}
.rbt{display:flex;gap:10px;padding:8px 16px 2px}
.rbt .btn{flex:1;margin:0}
.rbt .btn.l{border:1.5px solid var(--p);color:var(--p);background:#fff}

/* ===== FuNPaY রিং লোগো অ্যানিমেশন ===== */
.fpa{overflow:visible}.fpa *{transform-box:view-box;transform-origin:50% 50%}
.land .lglogo.fpa{width:156px}
.pinp .lglogo.fpa{width:96px}
@media (max-height:720px){.pinp .lglogo.fpa{width:74px}.land .lglogo.fpa{width:128px}}
.fpa-tk{font-weight:700;font-size:54px;fill:#e2136e;text-anchor:middle;dominant-baseline:central;font-family:system-ui,sans-serif}
.fpa-dt{animation:fpa-fly calc(var(--k)*1.1s) cubic-bezier(.2,1.3,.4,1) backwards}
@keyframes fpa-fly{from{transform:translate(var(--x),var(--y)) scale(.3);opacity:0}30%{opacity:1}}
.fpa-spin{animation:fpa-sn 26s linear calc(var(--k)*2.2s) infinite}
@keyframes fpa-sn{to{transform:rotate(360deg)}}
.fpa-rg{opacity:0;animation:fpa-fd calc(var(--k)*1s) ease-out calc(var(--k)*1.4s) forwards}
@keyframes fpa-fd{to{opacity:.55}}
.fpa-ry{opacity:0;animation:fpa-ry 3.2s ease-out calc(var(--k)*1.8s) infinite}
@keyframes fpa-ry{0%{opacity:0;transform:scale(.8)}12%{opacity:1}38%{opacity:0;transform:scale(1.18)}100%{opacity:0}}
.fpa-ct{opacity:0;animation:fpa-pp calc(var(--k)*.7s) cubic-bezier(.2,1.6,.4,1) calc(var(--k)*1.6s) forwards,fpa-pulse 3.2s ease-in-out calc(var(--k)*2.6s) infinite}
@keyframes fpa-pp{from{opacity:0;transform:scale(0)}to{opacity:1;transform:none}}
@keyframes fpa-pulse{50%{transform:scale(1.07)}}
.fpa-rp{opacity:0;animation:fpa-rp 3.2s ease-out calc(var(--k)*2.2s) infinite}
@keyframes fpa-rp{0%{opacity:.6;transform:scale(1)}100%{opacity:0;transform:scale(1.6)}}
/* রি-রেন্ডারে (যেমন ভাষা বদল) আবার প্রথম থেকে শুরু হবে না */
.fpa-s .fpa-dt{animation:none}.fpa-s .fpa-rg{animation:none;opacity:.55}
.fpa-s .fpa-ct{opacity:1;animation:fpa-pulse 3.2s ease-in-out infinite}
.fpa-s .fpa-spin{animation:fpa-sn 26s linear infinite}
/* স্প্ল্যাশ */
#fpsplash{position:fixed;inset:0;z-index:99999;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(circle at 50% 38%,#f0207b,#c40f5e 60%,#a30c4d);color:#fff;overflow:hidden;transition:opacity .5s}
#fpsplash.out{opacity:0;pointer-events:none}
.fps-orb{position:absolute;border-radius:50%;background:rgba(255,255,255,.08);animation:fpa-float 9s ease-in-out infinite}
.fps-o1{width:75vmax;height:75vmax;top:-20vmax;right:-28vmax}.fps-o2{width:40vmax;height:40vmax;bottom:-8vmax;left:-12vmax;animation-delay:-4s}
@keyframes fpa-float{50%{transform:translate(8px,-14px) scale(1.06)}}
.fps-lg{width:64vw;max-width:300px;position:relative}
#fpsplash .lglogo{width:100%;height:auto;filter:none;display:block}
.fps-name{display:flex;font-size:38px;font-weight:700;letter-spacing:.04em;margin-top:14px;position:relative}
.fpa-ch{display:inline-block;opacity:0;animation:fpa-chr .6s cubic-bezier(.2,1.6,.4,1) forwards}
@keyframes fpa-chr{from{opacity:0;transform:translateY(24px) scale(.6)}to{opacity:1;transform:none}}
.fps-tag{font-size:15px;opacity:0;margin-top:6px;position:relative;animation:fpa-up .6s ease-out 1.5s forwards}
@keyframes fpa-up{from{opacity:0;transform:translateY(10px)}to{opacity:.88;transform:none}}
.fps-ld{position:absolute;bottom:calc(7% + env(safe-area-inset-bottom,0px));display:flex;gap:8px;opacity:0;animation:fpa-up .4s ease-out 1.7s forwards}
.fps-ld i{width:9px;height:9px;border-radius:50%;background:#fff;animation:fpa-dot 1.2s ease-in-out infinite}
.fps-ld i:nth-child(2){animation-delay:.2s}.fps-ld i:nth-child(3){animation-delay:.4s}
@keyframes fpa-dot{0%,100%{opacity:.35}40%{opacity:1;transform:translateY(-5px)}}

/* ===== PIN ঘর: চিকন লম্বা বক্স ===== */
.dots{gap:10px}
.dt,.pinc .dt{width:34px;height:54px;border-radius:10px;border:2px solid #efb3cf;background:#fff8fb;display:grid;place-items:center;font-size:26px;font-weight:700;line-height:1;color:#e2136e;transition:border-color .15s,background .15s,box-shadow .15s}
.dt.on,.pinc .dt.on{background:#fdeaf3;border-color:#e2136e;transform:none;animation:none}
.dt.cur{border-color:#e2136e;box-shadow:0 0 0 3px #e2136e24}
@media (max-height:720px){.dt,.pinc .dt{width:30px;height:46px;font-size:22px}}


/* =====================================================================
   FuNPaY v2.3 - মসৃণ অ্যানিমেশন (ধীর ও নরম), বিকাশ স্টাইল ফিল্টার/মেনু/বিবরণ, ক্যামেরা ঠিক
   ===================================================================== */
html,body{background:#c40f5e}
body:before{background:linear-gradient(180deg,#fcedf4,#f6eff6 46%,#f5f0f5)}
#app{background:#f7eef4}
html.scanning,html.scanning body,html.scanning #app{background:transparent!important}
html.scanning .sh.scanx,html.scanning .sh.scanx .box{background:transparent!important}
html.scanning:not(.camon) .sh.scanx .box{background:#12050c!important}
/* নরম অ্যানিমেশন (আগে সব বন্ধ ছিল, তাই লাফিয়ে লাফিয়ে মনে হতো) */
.pg.in{animation:pgin2 .45s var(--ease) both}
.pg.in .it{animation:rise .55s var(--ease) both;animation-delay:calc(var(--i,0)*45ms + 90ms)}
.pg.in .tr{animation:rise .5s var(--ease) both;animation-delay:calc(var(--i,0)*55ms + 160ms)}
.pg.in .tri div,.pg.in .fc{animation:rise .5s var(--ease) both;animation-delay:.28s}
.pg.in .wsheet,.pg.in .sec,.pg.in .msec,.pg.in .prof,.pg.in .balc,.pg.in .nt{animation:rise .5s var(--ease) both}
.pg.in .sec:nth-of-type(2){animation-delay:.1s}.pg.in .sec:nth-of-type(3){animation-delay:.18s}.pg.in .msec:nth-of-type(2){animation-delay:.08s}.pg.in .msec:nth-of-type(3){animation-delay:.16s}
nav.fx{animation:navin .5s var(--ease) both}
.bn svg.bv{animation:bfloat 4.5s ease-in-out infinite}
.dt.on{animation:dtpop .28s var(--spring)}
.sh{animation-duration:.28s}.sh .box{animation-duration:.36s}.sh.dlg .box{animation-duration:.38s}
.stp.go{animation:stepin2 .3s var(--ease) both}
.grid{transition:none}
.more svg{transition:transform .3s var(--ease)}
.tr:active,.it:active,.mr:active{transition:transform .12s}
.it,.tr,.mr,.fr,.dmi{will-change:auto}
.tr{cursor:pointer}
@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.bn svg.bv{animation:none!important}}

/* সার্চ + ফিল্টার বাটন (বাইরে উপচে পড়া ঠিক) */
.srch{align-items:center}
.srch div{min-width:0}
.srch button.fb{flex:none;display:flex;align-items:center;gap:6px;padding:0 14px}
.srch button.fb svg.i{width:18px;height:18px;stroke-width:2.2}
.srch button.fb i{font-style:normal;background:var(--p);color:#fff;font-size:11px;font-weight:700;min-width:18px;height:18px;border-radius:9px;display:grid;place-items:center;padding:0 5px}
.srch button.fb.on{background:var(--pl)}

/* বিকাশ স্টাইল ফিল্টার শিট */
.sh.dlg.flt .box{padding:6px 0 calc(14px + var(--sb));border-radius:18px 18px 0 0}
.sh.dlg.flt .grip{margin-bottom:6px}
.fth{display:flex;align-items:center;justify-content:space-between;padding:8px 18px 10px;border-bottom:1px solid #f1edf1}
.fth b{font-size:15px;font-weight:700;color:#38333a}
.fth button{border:0;background:none;color:var(--p);font-size:14px;font-weight:700;cursor:pointer;padding:6px 0 6px 12px}
.fls{padding:2px 0}
.fr{display:flex;align-items:center;gap:14px;width:100%;border:0;background:none;padding:10px 18px;font-size:14.5px;font-weight:500;color:#38333a;cursor:pointer;text-align:left}
.fr:active{background:var(--pl2)}
.fr .ic{width:36px;height:36px;background:#f6f1f5}.fr .ic>svg.ci{width:22px;height:22px}.fr .ic>svg.i{width:18px;height:18px}
.fr span{flex:1}
.cb{width:22px;height:22px;border-radius:50%;border:2px solid #dcd3dc;display:grid;place-items:center;transition:background .2s,border-color .2s,transform .25s var(--spring)}
.cb svg{width:14px;height:14px;fill:none;stroke:#fff;stroke-width:3.6;stroke-linecap:round;stroke-linejoin:round;opacity:0;transform:scale(.4);transition:opacity .15s,transform .25s var(--spring)}
.fr.on .cb{background:var(--p);border-color:var(--p);transform:scale(1.08)}.fr.on .cb svg{opacity:1;transform:none}
.fbt{display:flex;gap:10px;padding:12px 18px 0}.fbt .btn{flex:1;margin:0!important}

/* সাইড মেনু (বিকাশ মেনুর মতো, বাঁ দিক থেকে) */
.sh.drw{justify-content:flex-start}
.sh.drw .box{width:84%;max-width:340px;height:100%;background:#fff;border-radius:0 22px 22px 0;padding:calc(14px + var(--st)) 0 calc(10px + var(--sb));animation:dslin .34s var(--ease) both}
.sh.drw.re .box{animation:none}
.sh.drw.out .box{animation:dslout .24s cubic-bezier(.5,0,.9,.4) both}
@keyframes dslin{from{transform:translateX(-100%)}to{transform:none}}
@keyframes dslout{from{transform:none}to{transform:translateX(-100%)}}
.dhd{display:flex;align-items:center;justify-content:space-between;padding:0 18px 10px}
.dhd b{font-size:20px;font-weight:700;color:var(--p)}
.dpf{display:flex;align-items:center;gap:12px;margin:4px 14px 8px;padding:12px;border-radius:14px;background:var(--pl2);border:1px solid #fbd9e8}
.dpf .big{width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,#e2136e,#f0549a);color:#fff;display:grid;place-items:center;font-size:19px;font-weight:700;flex:none}
.dpf b{display:block;font-size:15px;font-weight:700}.dpf span{display:block;font-size:12.5px;color:var(--mu);margin-top:2px}
.dls{flex:1;overflow-y:auto;padding:4px 0}
.dmi{display:flex;align-items:center;gap:18px;width:100%;border:0;background:none;padding:0 20px;min-height:52px;font-size:14.5px;font-weight:500;color:#38333a;cursor:pointer;text-align:left}
.dmi:active{background:var(--pl2)}.dmi svg.i{color:#5b555d;width:23px;height:23px}
.dver{text-align:center;color:var(--mu);font-size:12px;padding-top:6px}
.sh.drw .flang button{height:26px}

/* লেনদেনের বিবরণ + তথ্য শিট */
.tdh{display:flex;justify-content:center;margin:2px 0 8px}.tdh .ic,.tdh .av2{width:56px;height:56px;font-size:22px}.tdh .ic>svg.ci{width:34px;height:34px}
.sh.dlg .ok .amt{font-size:28px}
.tdl{padding:6px 2px 0}
.sh.dlg .rbt{padding:12px 0 0}
.sh.dlg h3{font-size:17px;font-weight:700;margin:6px 0 12px;color:#312c33}
.ip{font-size:14px;line-height:1.7;color:#4a444b;margin-bottom:6px}
.lms>div{display:flex;flex-direction:column;gap:3px;padding:11px 0;border-bottom:1px solid #f4f0f4}.lms span{font-size:13px;color:var(--mu)}.lms b{font-size:14.5px;font-weight:600}
#app:empty{background:#c40f5e}

/* লোগো: ঘোলা ভাব বন্ধ (ছায়া/গ্লো/পালস রিং বাদ), বড় ও স্পষ্ট */
.lglogo,#fpsplash .lglogo{filter:none!important}
.fpa-rp{display:none}
.fpa-rg{animation:none;opacity:1;stroke:#fff;stroke-width:4}
.fpa-ry{animation:none;opacity:1}
.fpa-ct,.fpa-s .fpa-ct{animation:fpa-pp .35s cubic-bezier(.2,1.6,.4,1) .7s both}
.fpa-s .fpa-ct{animation:none;opacity:1}
.fpa{shape-rendering:geometricPrecision}
.land .lglogo.fpa{width:210px}
.pinp .lglogo.fpa{width:128px}
.pinp .phead{padding-top:calc(30px + var(--st))}
@media (max-height:720px){.land .lglogo.fpa{width:168px}.pinp .lglogo.fpa{width:96px}}
.hb img{width:30px}.tbar img,.ph img{width:32px}
.fbody .mini{width:64px}

/* ===== v2.6: ছোট PIN ঘর + আলাদা ডায়েল কিবোর্ড, প্রোফাইল ছবি, বিকাশ-স্টাইল সেন্ড/ক্যাশ আউট/পেমেন্ট ===== */
.pinw{position:relative;display:flex;justify-content:center;width:100%;margin:12px 0 2px}
.pinw .dots{margin:0;gap:9px}
.pinw .dt,.pinc .pinw .dt{width:24px;height:32px;border-radius:8px;border-width:1.5px;font-size:18px}
.pinw .dt.cur{box-shadow:0 0 0 2px #e2136e24}
input.pinin{position:absolute;left:0;top:0;width:100%;height:100%;opacity:0;border:0;margin:0;padding:0;background:transparent;font-size:16px;z-index:3;outline:0;caret-color:transparent;-webkit-appearance:none;appearance:none;letter-spacing:0;text-align:center}
.pinp .phead b{font-size:22px;font-weight:700;margin-top:10px}
.pinp .psheet{padding:22px 18px calc(22px + var(--sb))}
.fpgo{display:inline-flex;align-items:center;justify-content:center;gap:8px;margin-top:8px;height:40px;padding:0 18px;border-radius:20px;border:1.5px solid #f3c3d9;background:#fff7fb;color:var(--p);font-weight:700;font-size:13.5px;cursor:pointer}
.fpgo svg{width:20px;height:20px;stroke:var(--p)}
.phint{font-size:12px;color:var(--mu);text-align:center;margin:6px 0 0}

.av,.big,.qav{overflow:hidden}
.av img,.big img,.qav img{width:100%;height:100%;object-fit:cover;display:block;border-radius:50%}
