/* =====================================================================
   FuNPaY v2.13 - নেটিভ অ্যাপের মতো শান্ত নড়াচড়া, লোগো লোডার, টেনে রিফ্রেশ
   ===================================================================== */
/* 1) ওয়েবসাইটের মতো আচরণ বন্ধ: ফোকাস বর্ডার, ছবি টানা, লেখা নির্বাচন, টেক্সট ফোলা */
*{outline:none}
input,textarea{-webkit-user-select:text;user-select:text;-webkit-appearance:none;appearance:none}
img,svg{-webkit-user-drag:none;user-drag:none}
img{pointer-events:none}
button,a,.it,.tr,.mr,.rr,.fc,.bn,.hb,.av{cursor:default}
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}

/* 2) আগের "সব অ্যানিমেশন বন্ধ" নিয়ম v2.14 এ সরানো হয়েছে, নতুন অ্যানিমেশন ফাইলের শেষে */
.more svg{transition:transform .25s}

/* 3) লোগো লোডার: অ্যাপের যেকোনো জায়গায় লোড হলে FuNPaY লোগো ছোট করে ঘোরে */
@keyframes lgspin{to{transform:rotate(360deg)}}
.lgl{display:inline-block;width:30px;height:30px;background:url(../icons/logo-pink.png) center/contain no-repeat;animation:lgspin .9s linear infinite;vertical-align:middle}
.cpe .lgl{display:block;margin:6px auto}
/* বাটন লোড হচ্ছে: লেখা লুকিয়ে সাদা গোল ঘরে লোগো ঘোরে */
.btn.ld,.nbar.ld{color:transparent!important;position:relative;opacity:1!important;pointer-events:none;animation:none!important}
.btn.ld{background:linear-gradient(180deg,#ec2c80,#dc1068)!important}
.nbar.ld{background:var(--lp,#e2136e)!important}
.btn.ld>*,.nbar.ld>*{visibility:hidden}
.btn.ld::after,.nbar.ld::after{content:"";position:absolute;left:50%;top:50%;width:32px;height:32px;margin:-16px 0 0 -16px;border-radius:50%;background:#fff url(../icons/logo-pink.png) center/26px no-repeat;animation:lgspin .9s linear infinite}
.btn.l.ld::after{background-color:#fde7f1}
button.hold.ld{opacity:1!important}
button.hold.ld>*{visibility:hidden}
button.hold.ld::after{content:"";position:absolute;left:50%;top:50%;width:34px;height:34px;margin:-17px 0 0 -17px;background:url(../icons/logo-pink.png) center/contain no-repeat;animation:lgspin .9s linear infinite}

/* 5) নোটিফিকেশন তালিকা */
.nf{transition:background .6s}
.nf.un{background:var(--pl2)}
.nf .m span{white-space:normal;overflow:visible;text-overflow:clip;line-height:1.4}
.nf .m b{font-size:13px;color:var(--mu);font-weight:600}
.nf .m span{color:#2b2530;font-size:13.5px;font-weight:500;margin-top:3px}
.nf .r{align-self:flex-start;padding-top:2px}
.ud{display:block;width:9px;height:9px;border-radius:50%;background:var(--p);margin:8px 0 0 auto}

/* 6) অবস্থা ব্যাজ (সফল / ব্যর্থ) আর লগইনের নতুন অ্যাকাউন্ট লিংক */
.stc.bad{background:#fde8eb;color:var(--red)}
.lnk3{margin-top:14px;background:none;border:0;color:var(--p);font-size:14px;font-weight:700;padding:8px 10px;cursor:default}
.lnk3:active{opacity:.6}

/* =====================================================================
   FuNPaY v2.14 - ভালো অ্যানিমেশন (বেশিও না, কমও না), সুন্দর ইনপুট ঘর,
   মাঝখানে লোগো লোডার, ছোট হোল্ড বাটন
   ===================================================================== */
@keyframes fup{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@keyframes fin{from{opacity:0;transform:translateX(-18px)}to{opacity:1;transform:none}}
@keyframes zoomin{from{opacity:0;transform:scale(.9)}to{opacity:1;transform:none}}
@keyframes fpglow{0%,100%{box-shadow:0 0 0 0 rgba(226,19,110,.30)}60%{box-shadow:0 0 0 10px rgba(226,19,110,0)}}

/* 1) পেজ খুললে: একটার পর একটা নরম করে উঠে আসে */
.pg.in{animation:fade .25s ease both}
.pg.in>*{animation:fup .5s var(--ease) both}
.pg.in>*:nth-child(2){animation-delay:.06s}.pg.in>*:nth-child(3){animation-delay:.12s}
.pg.in>*:nth-child(4){animation-delay:.18s}.pg.in>*:nth-child(5){animation-delay:.24s}
.pg.in>*:nth-child(n+6){animation-delay:.3s}
.pg.in .it{animation:zoomin .45s var(--spring) both;animation-delay:calc(var(--i,0)*36ms + 100ms)}
.pg.in .tr,.pg.in .mr,.pg.in .nf{animation:fin .42s var(--ease) both;animation-delay:.2s}
.pg.in .tr:nth-child(2),.pg.in .mr:nth-child(3){animation-delay:.26s}
.pg.in .tr:nth-child(3),.pg.in .mr:nth-child(4){animation-delay:.32s}
.pg.in .tr:nth-child(4),.pg.in .mr:nth-child(5){animation-delay:.38s}
.pg.in .tr:nth-child(5),.pg.in .mr:nth-child(6){animation-delay:.44s}
.pg.in .tr:nth-child(n+6),.pg.in .mr:nth-child(n+7){animation-delay:.5s}
.pg.in .tri div{animation:zoomin .45s var(--spring) both}
.pg.in .tri div:nth-child(1){animation-delay:.3s}.pg.in .tri div:nth-child(2){animation-delay:.38s}.pg.in .tri div:nth-child(3){animation-delay:.46s}
.pg.in .fc{animation:zoomin .4s var(--spring) both;animation-delay:.28s}

/* 2) চাপ দিলে নরম করে ছোট হয়ে ফিরে আসে */
.it,.fc,.tri div,.mr,.rr,.opc,.hb,.av,.more,.pill,.chip,.lwb,.kp button{transition:transform .18s var(--ease),opacity .18s,background-color .2s,border-color .2s}
.it:active,.fc:active,.tri div:active,.hb:active,.av:active,.opc:active{transform:scale(.93)}
.mr:active,.tr:active,.rr:active{background:rgba(226,19,110,.07)}
.btn:active,.lwb:active{transform:scale(.97)}
.btn,.nbar,.bknx{transition:transform .18s var(--ease),background-color .2s,opacity .2s}
nav button .ni{transition:transform .25s var(--spring)}
nav button:active .ni{transform:scale(.86)}
nav button.on .ni{animation:navpop .45s var(--spring)}
.sw b{transition:transform .25s var(--spring)}
.seg button,.seg2 button{transition:color .2s,border-color .25s,background-color .2s}

/* 3) নিচ থেকে ওঠা পেজ/শিট আর ধাপ বদল */
.sh{animation-duration:.26s}
.sh .box{animation-duration:.36s}
.sh.dlg .box{animation-duration:.38s}
.stp.go{animation:stepin .34s var(--ease) both}
.pinp .psheet{animation:fup .6s var(--ease) .12s both}
.fl .fbody>*{animation:fup .5s var(--ease) both}
.fl .fbody>*:nth-child(2){animation-delay:.05s}.fl .fbody>*:nth-child(3){animation-delay:.1s}
.fl .fbody>*:nth-child(4){animation-delay:.15s}.fl .fbody>*:nth-child(5){animation-delay:.2s}
.fl .fbody>*:nth-child(n+6){animation-delay:.25s}
.lpanel{animation:fup .6s var(--ease) .25s both}
.nbar{animation:fup .45s var(--ease) .2s both}
.nbar.ld{animation:none}
.sh .pcard{animation:fup .45s var(--ease) both}
.sh.re .pcard{animation:none}

/* 4) সুন্দর ইনপুট ঘর: গোল কোণা, নরম বর্ডার, ফোকাসে গোলাপি আভা */
.fld,.pcard>input{height:54px;border-radius:16px;background:#fff;border:1.5px solid #eadce4;box-shadow:0 2px 8px rgba(160,40,100,.05);transition:border-color .2s,box-shadow .25s,background .2s,transform .2s}
.fld:focus-within{border-color:var(--p);background:#fff;box-shadow:0 0 0 4px rgba(226,19,110,.12),0 6px 16px rgba(226,19,110,.10)}
.fld svg{transition:stroke .2s,color .2s}
.fld:focus-within svg{color:var(--p);stroke:var(--p)}
.fld.sf{height:48px;border-radius:14px}
.fld.big{height:auto;border:0;border-bottom:2px solid var(--p);border-radius:0;background:transparent;box-shadow:none}
.fld.big:focus-within{box-shadow:none}
.srch div{height:48px;border-radius:16px;background:#fff;border:1.5px solid #eadce4;box-shadow:0 2px 8px rgba(160,40,100,.05);transition:border-color .2s,box-shadow .25s}
.srch div:focus-within{border-color:var(--p);box-shadow:0 0 0 4px rgba(226,19,110,.12)}
.srch button.fb{height:48px;border-radius:16px;border-width:1.5px}
.lb{letter-spacing:.2px}
.cpadd input{height:50px;border-radius:14px;border:1.5px solid #eadce4;background:#fff;padding:0 14px;outline:0;transition:border-color .2s,box-shadow .25s}
.cpadd input:focus{border-color:var(--p);box-shadow:0 0 0 4px rgba(226,19,110,.12)}
.pinrow{border-radius:16px!important}
.pinrow:focus-within{box-shadow:0 0 0 4px rgba(226,19,110,.12)}
/* লগইন পেজের ঘর: আন্ডারলাইনের বদলে নরম বক্স */
.cfield{height:54px;border-radius:16px;background:#f4eff3;border:1.5px solid #eee3ea}
.fl .pfield{border:1.5px solid #e6d9e1;border-radius:16px;background:#fff;padding:0 16px;box-shadow:0 2px 10px rgba(160,40,100,.06);transition:border-color .2s,box-shadow .25s}
.fl .pfield:focus-within{border-color:var(--lp);box-shadow:0 0 0 4px rgba(226,19,110,.12),0 8px 20px rgba(226,19,110,.10)}
.fl .pfield input{height:52px}
.fl .pfield.ro{background:#f4eff3;box-shadow:none}
.bkn{border:1.5px solid #eee3ea;border-radius:16px;background:#faf6f9;padding:14px 16px}
.bkp{border:1.5px solid #e6d9e1;border-bottom-width:1.5px;border-radius:16px;background:#fff;padding:0 8px 0 16px;box-shadow:0 2px 10px rgba(160,40,100,.06);transition:border-color .2s,box-shadow .25s}
.bkp:focus-within{border-color:var(--lp,#e2136e);box-shadow:0 0 0 4px rgba(226,19,110,.12),0 8px 20px rgba(226,19,110,.10)}
.bkp input.pinin{height:52px}
.bkfp{border-radius:14px;transition:background .2s,transform .2s var(--spring)}
.bkfp:active{transform:scale(.88)}
.bkfp.on{animation:fpglow 2.2s ease-out infinite;border-radius:50%}
.psheet .pgbtn{border-radius:16px}

/* 5) পেমেন্ট কনফার্ম হোল্ড বাটন: উচ্চতা ছোট (লম্বা আগের মতোই), ভেতরের রং আরও গাঢ় */
.holdw{padding:8px 18px 4px}
button.hold{height:46px;border-radius:23px;border:1.5px solid var(--p);gap:8px;font-size:15px;box-shadow:0 5px 14px rgba(226,19,110,.18);animation:hpulse 2s ease-in-out infinite!important;-webkit-tap-highlight-color:transparent;-webkit-user-select:none;user-select:none}
button.hold i{background:linear-gradient(90deg,#d10f63,#a50a4c);overflow:hidden;transition:width .18s ease-out}
button.hold.hd i{width:100%;transition:width 1s linear}
button.hold.hd{animation:none!important;box-shadow:0 6px 18px rgba(165,10,76,.35);transform:scale(.985)}
button.hold svg.i{width:24px;height:24px}
button.hold .hc{position:absolute;left:0;top:0;bottom:0;display:flex;align-items:center;justify-content:center;gap:8px;color:#fff;white-space:nowrap}
button.hold .hc svg.i{stroke:#fff;fill:none;stroke-width:2.2;width:24px;height:24px}
button.hold .hc b{color:#fff;font-size:15px;font-weight:700}
button.hold.hd b,button.hold.hd svg.i{color:var(--p);stroke:var(--p)}
button.hold.hd .hc b{color:#fff}button.hold.hd .hc svg.i{stroke:#fff}
button.hold.ld{opacity:1!important;animation:none!important;background:#fff}
button.hold.ld>*{visibility:hidden}
button.hold.ld::after{width:30px;height:30px;margin:-15px 0 0 -15px}

/* 6) লোগো লোডার: যেকোনো জায়গায় লোড হলে আমাদের লোগো, টেনে রিফ্রেশে স্ক্রিনের ঠিক মাঝখানে */
.lgl{width:34px;height:34px}
#ptrv{position:fixed;left:0;right:0;top:0;bottom:0;background:rgba(255,244,249,.72);-webkit-backdrop-filter:blur(3px);backdrop-filter:blur(3px);opacity:0;pointer-events:none;z-index:55;transition:opacity .25s}
#ptrv.on{opacity:1}
#ptr{position:fixed;left:50%;top:50%;margin:0;z-index:60;width:68px;height:68px;border-radius:50%;background:#fff;box-shadow:0 12px 34px rgba(190,20,100,.30),0 0 0 6px rgba(226,19,110,.08);display:grid;place-items:center;opacity:0;pointer-events:none;transform:translate(-50%,-50%) scale(.4);will-change:transform,opacity}
#ptr .lgl{width:46px;height:46px;animation:none}
#ptr.spin .lgl{animation:lgspin .85s linear infinite;transform:none!important}
.nl .lgl{width:22px;height:22px}
@media(prefers-reduced-motion:reduce){.pg.in>*,.pg.in .it,.pg.in .tr,.pg.in .mr,.pg.in .tri div{animation-duration:.01s!important}}
/* হোল্ড বাটন: গাঢ় রঙের ওপর সাদা লেখা ওপরের স্তরে থাকে */
button.hold i{z-index:2;pointer-events:none}
button.hold.hd>svg.i,button.hold.hd>b{transition:none}

/* ===== v2.16: KYC (NID স্ক্যান, মুখ যাচাই, PIN, অপেক্ষা) ===== */
.toast{z-index:70}
#kyc{position:fixed;inset:0;z-index:50;background:var(--bg);display:flex;justify-content:center}
#kyc.kin{animation:kin .38s var(--ease,cubic-bezier(.22,1,.36,1)) both}
@keyframes kin{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
#kyc .kw{width:100%;max-width:430px;height:100%;display:flex;flex-direction:column;background:var(--bg);position:relative}
#kyc .kt{background:linear-gradient(180deg,#e2136e,#ea2f82);color:#fff;display:flex;align-items:center;justify-content:space-between;padding:calc(8px + var(--st)) 8px 8px 6px;height:calc(58px + var(--st));flex:none;border-radius:0 0 22px 22px;box-shadow:0 4px 12px rgba(190,20,100,.16)}
#kyc .kt b{font-size:17px;font-weight:700}
#kyc .kt span{width:44px}
#kyc .kbk{width:44px;height:44px;border:0;background:none;color:#fff;display:grid;place-items:center;cursor:pointer;border-radius:50%}
#kyc .kbk.h{visibility:hidden}
#kyc .kbk:active{background:#ffffff26}
#kyc .ksg{display:flex;gap:6px;padding:14px 20px 0}
#kyc .ksg i{flex:1;height:4px;border-radius:4px;background:#e4dfe6;transition:background .4s}
#kyc .ksg i.on{background:var(--p)}
#kyc .kbody{flex:1;overflow-y:auto;padding:16px 16px 20px;-webkit-overflow-scrolling:touch}
#kyc .kbtm{padding:12px 16px calc(14px + var(--sb));background:var(--bg);flex:none}
#kyc .kbtn{width:100%;height:52px;border:0;border-radius:14px;background:var(--p);color:#fff;font-size:16px;font-weight:700;cursor:pointer;box-shadow:0 8px 18px rgba(226,19,110,.28);transition:transform .15s,opacity .2s}
#kyc .kbtn:active{transform:scale(.98)}
#kyc .kbtn.ld{opacity:.65;pointer-events:none;background-image:linear-gradient(110deg,transparent 30%,#ffffff55 50%,transparent 70%);background-size:200% 100%;animation:shim 1s linear infinite}
#kyc .klk{display:block;margin:10px auto 0;border:0;background:none;color:var(--mu);font-size:14px;font-weight:600;padding:6px 14px;cursor:pointer}
#kyc .kcard{background:#fff;border-radius:20px;padding:18px;box-shadow:0 6px 20px rgba(170,20,95,.08);margin-bottom:14px;opacity:0;animation:kup .5s var(--ease,ease) forwards}
#kyc .kc1{text-align:center;animation-delay:.05s}
#kyc .kc2{animation-delay:.2s}
@keyframes kup{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
#kyc .kc1 h2{font-size:20px;font-weight:700;color:#2a262b;margin:6px 0 6px}
#kyc .kc1 p{font-size:14px;color:var(--mu);line-height:1.55}
#kyc .kill{width:190px;height:auto;display:block;margin:0 auto}
#kyc .kshield{transform-origin:150px 100px;animation:kpop .7s .35s var(--spring,ease) both}
@keyframes kpop{from{opacity:0;transform:scale(.3)}to{opacity:1;transform:scale(1)}}
#kyc .kli{display:flex;align-items:center;gap:14px;padding:11px 0;font-size:15px;font-weight:600;color:#3b3540}
#kyc .kli+.kli{border-top:1px solid var(--ln)}
#kyc .kli svg{width:38px;height:38px;padding:9px;border-radius:12px;background:var(--pl);color:var(--p);stroke-width:1.8}
#kyc .knote{font-size:13px;color:var(--mu);text-align:center;line-height:1.55;padding:2px 10px}
#kyc .krej{display:flex;gap:12px;align-items:flex-start;background:#fff0f2;border:1px solid #ffd0d7;color:#b3202f;border-radius:16px;padding:14px;margin-bottom:14px;animation:kup .4s both}
#kyc .krej svg{width:24px;height:24px;flex:none;margin-top:1px}
#kyc .krej b{display:block;font-size:15px;margin-bottom:3px}
#kyc .krej span{font-size:14px;line-height:1.5}
/* ক্যামেরা */
#kyc .kcam{position:absolute;inset:0;background:#12050c;overflow:hidden;width:100%;max-width:430px;margin:0 auto}
#kyc .kcam video,#kyc .kcam .kpvi{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;background:#12050c}
#kyc .kcam video.mir{transform:scaleX(-1)}
#kyc .kfr{position:absolute;left:50%;top:44%;width:min(88%,380px);aspect-ratio:1.586;transform:translate(-50%,-50%);border-radius:18px;box-shadow:0 0 0 100vmax rgba(14,4,10,.66);pointer-events:none}
#kyc .kfr i{position:absolute;width:34px;height:34px;border:4px solid #fff;transition:border-color .3s}
#kyc .kfr.dn i{border-color:#2ed47a}
#kyc .kfr .c1{left:-2px;top:-2px;border-right:0;border-bottom:0;border-top-left-radius:18px}
#kyc .kfr .c2{right:-2px;top:-2px;border-left:0;border-bottom:0;border-top-right-radius:18px}
#kyc .kfr .c3{left:-2px;bottom:-2px;border-right:0;border-top:0;border-bottom-left-radius:18px}
#kyc .kfr .c4{right:-2px;bottom:-2px;border-left:0;border-top:0;border-bottom-right-radius:18px}
#kyc .kln{position:absolute;left:10px;right:10px;top:8%;height:3px;border-radius:3px;background:linear-gradient(90deg,transparent,#ff5fa8,transparent);box-shadow:0 0 16px #ff5fa8;animation:kscan 2.3s ease-in-out infinite}
@keyframes kscan{0%,100%{top:8%}50%{top:90%}}
#kyc .ktp{position:absolute;left:0;right:0;top:0;padding:calc(8px + var(--st)) 12px 0 6px;display:flex;align-items:center;gap:6px;color:#fff;z-index:3}
#kyc .ktp b{flex:1;font-size:17px;font-weight:700}
#kyc .ktp em{font-style:normal;font-size:12px;font-weight:700;background:#ffffff26;padding:5px 11px;border-radius:12px}
#kyc .kbt{position:absolute;left:0;right:0;bottom:0;padding:34px 20px calc(22px + var(--sb));z-index:3;text-align:center;color:#fff;background:linear-gradient(0deg,rgba(14,4,10,.9) 40%,transparent)}
#kyc .kbt p{font-size:14px;margin-bottom:16px;line-height:1.5;opacity:.92}
#kyc .ksh{display:flex;align-items:center;justify-content:space-between;padding:0 12px}
#kyc .kshut{width:74px;height:74px;border-radius:50%;border:4px solid #fff;background:none;display:grid;place-items:center;padding:0;cursor:pointer}
#kyc .kshut i{width:56px;height:56px;border-radius:50%;background:#fff;transition:transform .15s}
#kyc .kshut:active i{transform:scale(.86)}
#kyc .kgal{width:48px;height:48px;border-radius:50%;background:#ffffff26;display:grid;place-items:center;color:#fff;cursor:pointer}
#kyc .kgal.sp{visibility:hidden}
#kyc .kgal svg{width:24px;height:24px}
#kyc .krow{display:flex;gap:12px}
#kyc .kgh,#kyc .kgo{flex:1;height:50px;border-radius:14px;border:0;font-weight:700;font-size:15px;cursor:pointer}
#kyc .kgh{background:#ffffff26;color:#fff}
#kyc .kgo{background:var(--p);color:#fff;box-shadow:0 8px 18px rgba(226,19,110,.35)}
#kyc .knc{display:block;margin-top:12px;font-size:12.5px;color:#ffb3cf;min-height:16px}
#kyc .kov{position:absolute;inset:0;pointer-events:none}
#kyc .kov u{position:absolute;left:50%;top:42%;width:min(68%,290px);aspect-ratio:.78;transform:translate(-50%,-50%);border-radius:50%;box-shadow:0 0 0 100vmax rgba(14,4,10,.66);border:3px solid #fff;animation:kpulse 2s ease-in-out infinite}
#kyc .kov u.dn{border-color:#2ed47a;animation:none}
@keyframes kpulse{0%,100%{border-color:#ffffffcc}50%{border-color:#ff7ab4}}
#kyc .kcnt{position:absolute;left:0;right:0;top:42%;transform:translateY(-50%);text-align:center;color:#fff;font-size:96px;font-weight:700;text-shadow:0 4px 24px #0008;z-index:4;pointer-events:none}
#kyc .kcnt.pop{animation:kcn .9s ease both}
@keyframes kcn{0%{opacity:0;transform:translateY(-50%) scale(1.8)}25%{opacity:1;transform:translateY(-50%) scale(1)}85%{opacity:1}100%{opacity:0;transform:translateY(-50%) scale(.8)}}
/* তথ্যের ঘর */
#kyc .ksubt{font-size:14px;color:var(--mu);line-height:1.55;margin:2px 4px 14px}
#kyc .kf{display:flex;align-items:center;gap:12px;background:#fff;border-radius:18px;padding:12px 14px;margin-bottom:10px;box-shadow:0 4px 14px rgba(170,20,95,.07);opacity:0;animation:kup .5s var(--ease,ease) forwards;animation-delay:calc(var(--n) * .16s)}
#kyc .kfi{width:44px;height:44px;border-radius:14px;background:var(--pl);color:var(--p);display:grid;place-items:center;flex:none}
#kyc .kfi svg{width:22px;height:22px}
#kyc .kfb{flex:1;min-width:0}
#kyc .kfb label{display:block;font-size:12px;font-weight:600;color:var(--mu);margin-bottom:2px}
#kyc .kfb input,#kyc .kfb textarea{width:100%;border:0;outline:0;background:transparent;font-size:16px;font-weight:600;color:#2a262b;padding:2px 0;resize:none;line-height:1.35}
#kyc .kfb input::placeholder,#kyc .kfb textarea::placeholder{color:#c1bac6;font-weight:500;font-size:14px}
#kyc .kt2{width:26px;height:26px;border-radius:50%;flex:none;display:grid;place-items:center;font-style:normal;font-weight:700;font-size:14px;color:#fff;transform:scale(0);animation:kpop .45s var(--spring,ease) forwards;animation-delay:calc(var(--n) * .16s + .4s)}
#kyc .kt2.gd{background:#12a15b}
#kyc .kt2.no{background:#f29a1f}
#kyc .kt2 svg{width:16px;height:16px;fill:none;stroke:#fff;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
#kyc .kle{min-height:20px;color:var(--red);font-size:13.5px;text-align:center;margin-top:6px;font-weight:600}
/* পড়ার সময় */
#kyc .krd{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:20px 34px;text-align:center}
#kyc .krd b{font-size:18px;color:#2a262b}
#kyc .krd span{font-size:30px;font-weight:700;color:var(--p)}
#kyc .krd small{font-size:13px;color:var(--mu)}
#kyc .kscn{position:relative;width:210px;overflow:hidden;border-radius:16px;margin-bottom:10px;filter:drop-shadow(0 10px 20px rgba(226,19,110,.18))}
#kyc .kscn svg{display:block;width:100%;height:auto}
#kyc .kscn u{position:absolute;left:0;right:0;top:0;height:3px;background:linear-gradient(90deg,transparent,#e2136e,transparent);box-shadow:0 0 14px #e2136e;animation:kscan2 1.8s ease-in-out infinite}
@keyframes kscan2{0%,100%{top:2%}50%{top:96%}}
#kyc .kbar{width:100%;max-width:260px;height:8px;border-radius:8px;background:#eadfe6;overflow:hidden}
#kyc .kbar i{display:block;height:100%;width:0;border-radius:8px;background:linear-gradient(90deg,#e2136e,#ff5fa8);transition:width .4s}
/* PIN */
#kyc .kths{display:flex;justify-content:center;gap:10px;margin-bottom:12px}
#kyc .kth{width:76px;height:54px;border-radius:12px;overflow:hidden;border:2px solid #fff;box-shadow:0 4px 12px rgba(0,0,0,.14)}
#kyc .kth img{width:100%;height:100%;object-fit:cover;display:block}
#kyc .kpf{margin:16px 0 0;border-bottom:2px solid #ddd8de;transition:border-color .2s}
#kyc .kpf:focus-within{border-color:var(--p)}
#kyc .kpf input{width:100%;height:52px;border:0;background:transparent;text-align:center;font-size:26px;letter-spacing:10px;font-weight:700;outline:0;color:#2a262b}
#kyc .kmsg{min-height:18px;font-size:13.5px;color:var(--p);font-weight:600;text-align:center;margin-top:4px}
/* অপেক্ষা / সফল */
#kyc .kdone{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:20px 32px;gap:10px}
#kyc .kdone h2{font-size:21px;font-weight:700;color:#2a262b;margin-top:14px}
#kyc .kdone p{font-size:14.5px;color:var(--mu);line-height:1.6}
#kyc .kcir{width:112px;height:112px;border-radius:50%;display:grid;place-items:center;position:relative}
#kyc .kcir svg{width:54px;height:54px;fill:none;stroke:#fff;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
#kyc .kcir.wt{background:linear-gradient(160deg,#e2136e,#ff5fa8)}
#kyc .kcir.wt svg{animation:khg 2.4s ease-in-out infinite}
@keyframes khg{0%,40%{transform:rotate(0)}60%,100%{transform:rotate(180deg)}}
#kyc .kcir.wt:after,#kyc .kcir.ok:after{content:"";position:absolute;inset:-10px;border-radius:50%;border:3px solid #e2136e55;animation:kring 1.8s ease-out infinite}
#kyc .kcir.ok{background:linear-gradient(160deg,#12a15b,#2ed47a);animation:kpop .6s var(--spring,ease) both}
#kyc .kcir.ok:after{border-color:#12a15b55}
#kyc .kcir.ok svg{stroke-dasharray:30;stroke-dashoffset:30;animation:kdraw .6s .35s ease forwards}
@keyframes kring{0%{transform:scale(.9);opacity:1}100%{transform:scale(1.35);opacity:0}}
@keyframes kdraw{to{stroke-dashoffset:0}}
/* মেসেজ বক্সের KYC সারি, প্রোফাইলের ব্যাজ */
.ic.knt{background:var(--pl);color:var(--p)}
.ic.knt.bad{background:#ffe9ec;color:#e5324b}
.mr .kok{margin-left:auto;color:var(--grn);font-weight:700;font-size:12.5px}

/* ===== v2.19: ভিডিও-লোগো বন্ধ, অটো স্ক্যান, মুখ ধাপ, তথ্য পাতা, কোড পাতা, অপেক্ষা পাতা ===== */
#kyc video{opacity:0;transition:opacity .25s;pointer-events:none;background:#12050c}
#kyc video.on{opacity:1}
#kyc video::-webkit-media-controls,#kyc video::-webkit-media-controls-panel,#kyc video::-webkit-media-controls-overlay-play-button,#kyc video::-webkit-media-controls-start-playback-button,#kyc video::-webkit-media-controls-enclosure{display:none!important;-webkit-appearance:none;opacity:0}
/* শাটার শুরুতে লুকানো, কিছুক্ষণ পরে আসে */
#kyc .ksh .kshut{opacity:0;transform:scale(.6);pointer-events:none;transition:opacity .4s,transform .4s}
#kyc .ksh.man .kshut{opacity:1;transform:none;pointer-events:auto}
#kyc .kchk{position:absolute;left:50%;top:44%;transform:translate(-50%,-50%);z-index:4;display:flex;align-items:center;gap:10px;background:rgba(14,4,10,.78);color:#fff;padding:11px 18px;border-radius:30px;font-size:14px;font-weight:700;white-space:nowrap}
#kyc .kchk.gd{background:#12a15b}
#kyc .kchk svg{width:20px;height:20px;fill:none;stroke:#fff;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
#kyc .kspin{width:18px;height:18px;border-radius:50%;border:3px solid #ffffff55;border-top-color:#fff;animation:kspn .8s linear infinite}
@keyframes kspn{to{transform:rotate(360deg)}}
/* পপআপ */
#kyc .kpop{position:absolute;inset:0;z-index:30;background:rgba(14,4,10,.62);display:flex;align-items:center;justify-content:center;padding:26px;animation:kfade .2s both}
@keyframes kfade{from{opacity:0}to{opacity:1}}
#kyc .kpb{background:#fff;border-radius:22px;padding:24px 22px 20px;width:100%;max-width:340px;text-align:center;animation:kpop .35s var(--spring,ease) both}
#kyc .kpi{width:54px;height:54px;border-radius:50%;background:#ffe9ec;color:#e5324b;font-size:30px;font-weight:700;display:grid;place-items:center;margin:0 auto 12px}
#kyc .kpb h3{font-size:18px;font-weight:700;color:#2a262b;margin-bottom:8px}
#kyc .kpb p{font-size:14px;line-height:1.55;color:var(--mu);margin-bottom:18px}
/* মুখ যাচাই */
#kyc .kpls{position:absolute;left:12px;right:12px;top:calc(62px + var(--st));display:flex;gap:8px;z-index:3}
#kyc .kpl{flex:1;display:flex;align-items:center;justify-content:center;gap:5px;height:34px;border-radius:17px;background:#ffffff1f;color:#ffffffb3;font-size:12.5px;font-weight:700;position:relative;transition:background .3s,color .3s}
#kyc .kpl i{display:grid;place-items:center}#kyc .kpl i svg{width:14px;height:14px}
#kyc .kpl u{display:none;text-decoration:none}
#kyc .kpl.on{background:#fff;color:var(--p)}
#kyc .kpl.dn2{background:#12a15b;color:#fff}
#kyc .kpl.dn2 i{display:none}#kyc .kpl.dn2 u{display:grid;place-items:center}#kyc .kpl.dn2 u svg{width:14px;height:14px}
#kyc .kfarr{position:absolute;z-index:3;width:52px;height:52px;border-radius:50%;background:var(--p);display:grid;place-items:center;box-shadow:0 6px 18px rgba(226,19,110,.5);top:42%;margin-top:-26px;transition:opacity .2s}
#kyc .kfarr.h{opacity:0}
#kyc .kfarr svg{width:28px;height:28px}
#kyc .kfarr.right{right:5%;animation:knr 1s ease-in-out infinite}
#kyc .kfarr.left{left:5%;animation:knl 1s ease-in-out infinite}
#kyc .kfarr.up{left:50%;margin-left:-26px;top:calc(42% - min(40%,205px) - 40px);animation:knu 1s ease-in-out infinite}
#kyc .kfarr.down{left:50%;margin-left:-26px;top:calc(42% + min(40%,205px) + 14px);animation:knd 1s ease-in-out infinite}
@keyframes knr{50%{transform:translateX(8px)}}@keyframes knl{50%{transform:translateX(-8px)}}@keyframes knu{50%{transform:translateY(-8px)}}@keyframes knd{50%{transform:translateY(8px)}}
#kyc .kfm{font-size:16px!important;font-weight:700;opacity:1!important;margin-bottom:10px!important}
#kyc .kfbar{height:8px;border-radius:8px;background:#ffffff2b;overflow:hidden;margin:0 6px}
#kyc .kfbar i{display:block;height:100%;width:0;border-radius:8px;background:linear-gradient(90deg,#ff5fa8,#2ed47a);transition:width .12s}
#kyc .kfpc{font-size:13px;font-weight:700;margin:6px 0 10px;min-height:18px;opacity:.9}
#kyc .kfok{position:absolute;left:50%;top:42%;width:96px;height:96px;margin:-48px 0 0 -48px;border-radius:50%;background:#12a15b;display:grid;place-items:center;transform:scale(0);transition:transform .4s var(--spring,ease)}
#kyc .kfok svg{width:52px;height:52px}
#kyc .kov.fin .kfok{transform:scale(1)}
/* তথ্য পাতা */
#kyc .ksum{background:#fff;border-radius:18px;padding:14px 16px;margin-bottom:12px;box-shadow:0 4px 14px rgba(170,20,95,.07)}
#kyc .ksum div:first-child{display:flex;align-items:baseline;gap:8px;margin-bottom:10px}
#kyc .ksum b{font-size:22px;font-weight:700;color:var(--p)}
#kyc .ksum span{font-size:13.5px;font-weight:600;color:var(--mu)}
#kyc .ksum .kbar{max-width:none}
#kyc .ksubt{font-size:13px}
#kyc .kf{border:1.5px solid transparent;transition:border-color .3s}
#kyc .kf.gd{border-color:#bfe9d1}
#kyc .kf.bd{border-color:#ffc9d1}
#kyc .kt2{width:30px;height:30px}
#kyc .kt2.gd{background:linear-gradient(160deg,#12a15b,#2ed47a)}
#kyc .kt2.no{background:linear-gradient(160deg,#e5324b,#ff6b81)}
#kyc .kt2 svg{width:17px;height:17px;display:block}
/* শুরুর পাতা: লেখা ছোট ও সমান লাইনে */
#kyc .kli{font-size:13.5px;gap:12px;padding:10px 0;white-space:nowrap}
#kyc .kli svg{width:34px;height:34px;padding:8px;flex:none}
#kyc .kc1 h2{font-size:18px}#kyc .kc1 p{font-size:13px}
/* অপেক্ষা পাতা */
#kyc .kfv{width:150px;height:150px;margin-bottom:4px}
#kyc .kfv svg{width:100%;height:100%;overflow:visible}
#kyc .kfr2{stroke-dasharray:100;stroke-dashoffset:100;animation:kfrr 5s linear infinite}
@keyframes kfrr{0%{stroke-dashoffset:100}80%,100%{stroke-dashoffset:0}}
#kyc .kfa{transform-origin:70px 70px;animation:kfhd 5s ease-in-out infinite}
@keyframes kfhd{0%{transform:none;opacity:1}10%{transform:translateX(11px) scaleX(.82)}20%{transform:none}30%{transform:translateX(-11px) scaleX(.82)}40%{transform:none}50%{transform:translateY(-9px) scaleY(.94)}60%{transform:none}70%{transform:translateY(9px) scaleY(.94)}78%{transform:none;opacity:1}84%,96%{opacity:0;transform:scale(.7)}100%{opacity:1;transform:none}}
#kyc .kfc{transform-origin:70px 70px;opacity:0;animation:kfck 5s ease-in-out infinite}
@keyframes kfck{0%,80%{opacity:0;transform:scale(.3)}86%{opacity:1;transform:scale(1.08)}90%,96%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(.3)}}
#kyc .kst3{display:flex;align-items:flex-start;width:100%;max-width:330px;margin:18px 0 6px}
#kyc .kst3 .n{width:84px;display:flex;flex-direction:column;align-items:center;gap:8px;flex:none}
#kyc .kst3 .n i{width:34px;height:34px;border-radius:50%;background:#e4dfe6;color:#9a93a0;font-style:normal;font-weight:700;font-size:15px;display:grid;place-items:center}
#kyc .kst3 .n i svg{width:18px;height:18px}
#kyc .kst3 .n span{font-size:12.5px;font-weight:700;color:var(--mu);text-align:center}
#kyc .kst3 .n.done i{background:#12a15b;color:#fff}
#kyc .kst3 .n.done span{color:#12a15b}
#kyc .kst3 .n.act i{background:var(--p);position:relative}
#kyc .kst3 .n.act i:after{content:"";position:absolute;inset:-6px;border-radius:50%;border:3px solid #e2136e44;animation:kring 1.6s ease-out infinite}
#kyc .kst3 .n.act span{color:var(--p)}
#kyc .kdot{width:10px;height:10px;border-radius:50%;background:#fff;animation:kdt 1.1s ease-in-out infinite}
@keyframes kdt{50%{transform:scale(.5);opacity:.6}}
#kyc .kst3 s{flex:1;height:4px;margin-top:15px;border-radius:4px;background:#e4dfe6;position:relative;overflow:hidden}
#kyc .kst3 s.full{background:#12a15b}
#kyc .kst3 s.run:after{content:"";position:absolute;inset:0;width:50%;background:linear-gradient(90deg,#e2136e,#ff5fa8);border-radius:4px;animation:klr 1.6s ease-in-out infinite}
@keyframes klr{0%{transform:translateX(-100%)}100%{transform:translateX(200%)}}
#kyc .kdone h2{font-size:19px;margin-top:8px}#kyc .kdone p{font-size:13.5px}
/* লগইন / নিবন্ধন / কোড পাতার লেখা ছোট ও গোছানো */
.fl.light .fbody h2{font-size:20px;font-weight:700;line-height:1.35}
.fl.light .fbody .mini{width:52px;margin:4px 0 14px}
.fl.light .fbody .sub{font-size:13.5px;line-height:1.5;margin-top:6px}
.fl.light .fbody label{font-size:12.5px;margin:16px 0 6px}
.fl.light .fbody .pfield b{font-size:16px}
/* কোড পাতা: ৬ ঘর */
.otpph{display:inline-block;margin:10px 0 4px;padding:7px 14px;border-radius:20px;background:#fde7f1;color:#c40f5e;font-size:15px;font-weight:700;letter-spacing:.6px;white-space:nowrap}
.otpb{position:relative;display:flex;gap:9px;margin:22px 0 4px}
.otpb i{flex:1;height:56px;max-width:54px;border-radius:14px;background:#fff;border:1.5px solid #e6d9e1;display:grid;place-items:center;font-style:normal;font-size:24px;font-weight:700;color:#2b2530;box-shadow:0 2px 8px rgba(160,40,100,.06);transition:border-color .2s,box-shadow .2s,transform .2s}
.otpb i.f{border-color:#e2136e66;background:#fff7fb}
.otpb i.a{border-color:var(--lp);box-shadow:0 0 0 4px rgba(226,19,110,.12);position:relative}
.otpb i.a:after{content:"";width:2px;height:24px;background:var(--lp);animation:otpc 1s steps(1) infinite}
@keyframes otpc{50%{opacity:0}}
.otpi{position:absolute;inset:0;width:100%;height:100%;opacity:0;border:0;background:transparent;font-size:16px;color:transparent;caret-color:transparent}
.otpb.shk{animation:otps .4s}
@keyframes otps{20%{transform:translateX(-8px)}40%{transform:translateX(8px)}60%{transform:translateX(-5px)}80%{transform:translateX(5px)}}
.otpw{margin-top:12px!important;font-size:12.5px!important}
.otpp{display:block;margin-top:14px;height:42px;padding:0 18px;border-radius:21px;border:1.5px solid var(--lp);background:#fff;color:var(--lp);font-size:14px;font-weight:700}
.otpp:active{background:#fde7f1}
.fl.light .lnk3{display:block;margin-left:0;padding-left:0}

/* ---------- v2.20: মুখ মেলানো পাতা ---------- */
#kyc .kfarr.blink{left:50%;margin-left:-26px;top:calc(42% + min(40%,205px) + 14px);animation:kblink 1.1s ease-in-out infinite}
@keyframes kblink{0%,100%{transform:scale(1)}50%{transform:scale(.8);opacity:.7}}
#kyc .kmx{text-align:center}#kyc .kmx .kbar{margin:14px auto 0}
#kyc .kmp{display:flex;align-items:center;justify-content:center;gap:0;margin:4px 0 14px}
#kyc .kmf{width:92px;height:92px;border-radius:50%;overflow:hidden;background:#fde7f1;border:3px solid #fff;box-shadow:0 6px 18px rgba(170,20,95,.2);position:relative;flex:none;display:grid;place-items:center;color:#e2136e}
#kyc .kmf img{width:100%;height:100%;object-fit:cover;display:block}
#kyc .kmf .i{width:40px;height:40px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
#kyc .kmf.sc::after{content:"";position:absolute;left:0;right:0;top:6%;height:3px;background:linear-gradient(90deg,transparent,#e2136e,transparent);box-shadow:0 0 10px #e2136e;animation:kmscan 1.5s ease-in-out infinite}
@keyframes kmscan{0%,100%{top:6%}50%{top:90%}}
#kyc .kml{display:block;width:42px;height:3px;margin:0 6px;background:repeating-linear-gradient(90deg,#e2136e 0 6px,transparent 6px 12px);background-size:12px 3px;animation:kmflow .8s linear infinite;border-radius:2px}
@keyframes kmflow{to{background-position:12px 0}}
#kyc .kmc{display:grid;place-items:center;margin:0 -6px;z-index:2}
#kyc .kmrw{position:relative;width:118px;height:118px;display:grid;place-items:center;background:#fff;border-radius:50%;box-shadow:0 8px 22px rgba(0,0,0,.1)}
#kyc .kmr{position:absolute;inset:0;width:100%;height:100%}
#kyc .kmr circle:last-child{animation:kmfill 1.1s cubic-bezier(.22,1,.36,1) both}
@keyframes kmfill{from{stroke-dashoffset:var(--c)}to{stroke-dashoffset:var(--o)}}
#kyc .kmrw b{font-size:26px;font-weight:700;letter-spacing:-.5px}
#kyc .kmt{display:block;margin-top:10px;color:#8a6b7b;font-size:12.5px}
#kyc .kmwy{margin-top:14px;text-align:left;display:flex;flex-direction:column;gap:8px}
#kyc .kmri{display:flex;gap:10px;align-items:flex-start;background:#fff3f3;border:1px solid #f7c9cb;border-radius:12px;padding:10px 12px;font-size:13.5px;line-height:1.45;color:#7a1f23;animation:kup .4s ease both}
#kyc .kmri .i{width:18px;height:18px;flex:none;margin-top:1px;fill:none;stroke:#e5484d;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
#kyc .kbar i.kmind{display:block;height:100%;width:40%;border-radius:8px;background:linear-gradient(90deg,#ff5fa8,#e2136e);animation:kmind 1.2s ease-in-out infinite}
@keyframes kmind{0%{margin-left:-40%}100%{margin-left:100%}}
#kyc .kbtm .klk{display:block;margin:8px auto 0}

/* ========== v2.21 ফেজ A: কোড যাচাই পাতা + নতুন অ্যাকাউন্ট পাতা ========== */
/* ৬ ঘর: কার্সর এখন ঘরের ভেতরে ঠিক মাঝে (আগে ৬ নম্বর ঘরে অঙ্ক উপরে উঠে যেত) */
.otpb{gap:10px;margin:24px 0 2px}
.otpb i{position:relative;overflow:visible;height:58px;max-width:56px;border-radius:15px;transition:border-color .22s,box-shadow .25s,background-color .25s,color .25s,transform .25s var(--spring)}
.otpb i.a:after{content:"";position:absolute;left:50%;top:50%;width:2px;height:26px;margin:-13px 0 0 -1px;background:var(--lp);border-radius:2px;animation:otpc 1s steps(1) infinite}
.otpb i.a{transform:translateY(-2px)}
.otpb i.pp{animation:otppop .34s var(--spring)}
@keyframes otppop{0%{transform:scale(.8)}60%{transform:scale(1.1)}100%{transform:scale(1)}}
.otpb.chk i{border-color:#e2136e88;background:#fff7fb;animation:otpwave 1.05s ease-in-out infinite}
.otpb.chk i:nth-child(2){animation-delay:.07s}.otpb.chk i:nth-child(3){animation-delay:.14s}.otpb.chk i:nth-child(4){animation-delay:.21s}.otpb.chk i:nth-child(5){animation-delay:.28s}.otpb.chk i:nth-child(6){animation-delay:.35s}
@keyframes otpwave{0%,100%{transform:translateY(0)}40%{transform:translateY(-6px)}}
.otpb.ok i{border-color:#2cc47c;background:#ecfaf3;color:#0f8a52;box-shadow:0 4px 14px rgba(44,196,124,.2);animation:otpok .5s var(--spring) both}
.otpb.ok i:nth-child(2){animation-delay:.05s}.otpb.ok i:nth-child(3){animation-delay:.1s}.otpb.ok i:nth-child(4){animation-delay:.15s}.otpb.ok i:nth-child(5){animation-delay:.2s}.otpb.ok i:nth-child(6){animation-delay:.25s}
@keyframes otpok{0%{transform:scale(1)}50%{transform:scale(1.14)}100%{transform:scale(1)}}
.otpb.bad i{border-color:#ef5a73;background:#fff1f3;color:#c9243f;box-shadow:none}
.otpb.shk{animation:otps .42s}
/* অবস্থার লাইন: যাচাই হচ্ছে / যাচাই হয়েছে / ভুল */
.otst{display:flex;align-items:center;gap:9px;min-height:30px;margin-top:16px;font-size:14.5px;font-weight:700;letter-spacing:.1px;color:var(--lp)}
.otst:not(:empty){animation:fup .3s var(--ease) both}
.otst.ok,.otst.info{color:#12a15b}.otst.err{color:#d92d4f}
.otst svg{width:20px;height:20px;flex:none;fill:none;stroke:currentColor;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.otst.ok svg path{stroke-dasharray:24;stroke-dashoffset:24;animation:draw .45s .05s ease forwards}
.otsp{width:17px;height:17px;border-radius:50%;border:2.5px solid #e2136e33;border-top-color:var(--lp);animation:lgspin .75s linear infinite;flex:none}
/* নিচের দুই বাটন এক লাইনে, সমান মাপের */
.otpact{display:flex;gap:10px;margin-top:14px}
.otpact .otpp,.otpact .otprs{flex:1;margin:0;height:48px;padding:0 12px;border-radius:24px;display:flex;align-items:center;justify-content:center;gap:8px;font-size:14px;font-weight:700;white-space:nowrap;cursor:pointer;transition:transform .18s var(--ease),background-color .2s,color .2s,border-color .2s,opacity .2s}
.otpact .otpp{border:1.5px solid var(--lp);background:#fff;color:var(--lp)}
.otpact .otpp svg{width:18px;height:18px;flex:none}
.otpact .otpp:active,.otpact .otprs:active{transform:scale(.96)}
.otprs{border:1.5px solid #ebe2e8;background:#f1ecf0;color:#9a8f98}
.otprs:disabled{opacity:1;cursor:default}
.otprs.rdy{border-color:#f3b9d3;background:#fde7f1;color:var(--lp);animation:otrdy .5s var(--spring) both}
.otprs.ld2{opacity:.6;pointer-events:none}
@keyframes otrdy{0%{transform:scale(.94)}100%{transform:scale(1)}}
.otrg{width:19px;height:19px;flex:none}
.otrg .bg{fill:none;stroke:#e1d6dd;stroke-width:3}
