.sh.scanx .scbg .b1{left:-26vmin;top:-22vmin;background:#e2136e;opacity:.38}
.sh.scanx .scbg .b2{right:-30vmin;bottom:-24vmin;background:#ffb800;opacity:.16}
.sh.scanx .scbg .wm{position:absolute;width:58px;height:58px;opacity:.16;animation:kwmf 5s ease-in-out infinite}
.sh.scanx .scbg .w1{left:12px;top:calc(110px + var(--st));transform:rotate(-14deg)}
.sh.scanx .scbg .w2{right:12px;top:calc(110px + var(--st));transform:rotate(14deg);animation-delay:-1.2s}
.sh.scanx .scbg .w3{left:12px;bottom:130px;transform:rotate(12deg);animation-delay:-2.4s}
