.kgf .gm{fill:none;stroke:#e2136e;stroke-width:2;stroke-linecap:round}
.kgf .gf,.kgf .gr,.kgf .gk{transform-origin:32px 32px}
.kgf{animation:kgfl 3s ease-in-out infinite}
@keyframes kgfl{50%{transform:translateY(-1px)}}
.kgf.right .gf{animation:kgr 2.4s cubic-bezier(.45,0,.2,1) infinite}.kgf.right .gr{animation:kgrh 2.4s cubic-bezier(.45,0,.2,1) infinite}
.kgf.left .gf{animation:kgl 2.4s cubic-bezier(.45,0,.2,1) infinite}.kgf.left .gr{animation:kglh 2.4s cubic-bezier(.45,0,.2,1) infinite}
.kgf.up .gf{animation:kgu 2.4s cubic-bezier(.45,0,.2,1) infinite}.kgf.up .gr{animation:kguh 2.4s cubic-bezier(.45,0,.2,1) infinite}
.kgf.down .gf{animation:kgd 2.4s cubic-bezier(.45,0,.2,1) infinite}.kgf.down .gr{animation:kgdh 2.4s cubic-bezier(.45,0,.2,1) infinite}
.kgf.blink .ge ellipse{animation:kgb 2.2s ease-in-out infinite}
@keyframes kgr{0%,12%{transform:none}38%,66%{transform:translateX(7px) scaleX(.86)}92%,100%{transform:none}}
@keyframes kgrh{0%,12%{transform:none}38%,66%{transform:translateX(3.5px) scaleX(.94)}92%,100%{transform:none}}
@keyframes kgl{0%,12%{transform:none}38%,66%{transform:translateX(-7px) scaleX(.86)}92%,100%{transform:none}}
@keyframes kglh{0%,12%{transform:none}38%,66%{transform:translateX(-3.5px) scaleX(.94)}92%,100%{transform:none}}
@keyframes kgu{0%,12%{transform:none}38%,66%{transform:translateY(-5px) scaleY(.94)}92%,100%{transform:none}}
@keyframes kguh{0%,12%{transform:none}38%,66%{transform:translateY(-2.5px)}92%,100%{transform:none}}
@keyframes kgd{0%,12%{transform:none}38%,66%{transform:translateY(5px) scaleY(.94)}92%,100%{transform:none}}
@keyframes kgdh{0%,12%{transform:none}38%,66%{transform:translateY(3px)}92%,100%{transform:none}}
@keyframes kgb{0%,10%,44%,100%{transform:scaleY(1)}17%,23%{transform:scaleY(.08)}30%{transform:scaleY(1)}37%{transform:scaleY(.08)}}
