/* =====================================================================
   v2.28 — সেন্ড মানি: প্রাপক ঘর, পরিমাণ পাতা (স্ক্রল ছাড়া), PIN ঘর, নিশ্চিত পাতা, সফল পাতা,
   লেনদেনের বিস্তারিত (ছোট শুভেচ্ছা কার্ড), হিস্টোরির সারি
   ===================================================================== */
/* ---- প্রাপক ঘর (সব ধাপে একই) ---- */
.bk2>.bkc:first-child,.bk3>.bkc:first-child{background:transparent;padding:14px 16px 4px}
.bkp{position:relative;display:flex;align-items:center;gap:12px;min-height:66px;padding:11px 14px;border:1.5px solid #f1dce8;border-radius:18px;background:linear-gradient(180deg,#fff 0%,#fff8fb 100%);box-shadow:0 4px 16px rgba(226,19,110,.08);overflow:visible}
.bkp .avs{display:block;margin:0;flex:none;position:relative;line-height:0}
.bkp .av2{width:44px;height:44px;font-size:18px;font-weight:700}
.bkp>div{flex:1;min-width:0}
.bkp b{display:block;font-size:15.5px;line-height:1.3;font-weight:700;color:#2a1a22;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bkp>div span{display:block;font-size:13.5px;line-height:1.3;margin-top:2px;color:#7d7580;letter-spacing:.2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bkp .vf{margin-left:auto;flex:none;width:24px;height:24px}
.bkp .vf svg{width:13px;height:13px}

/* ---- ধাপ ২: পরিমাণ (কিবোর্ড খোলা থাকলেও স্ক্রল ছাড়া) ---- */
.bk2 .bkl{font-size:12.5px;margin:10px 16px 2px}
.bk2>.bkc{padding-top:6px;padding-bottom:6px}
.bk2 .fld.big{height:48px;padding:0}
.bk2 .fld.big input{font-size:28px;height:46px}
.bk2 .avl{margin:6px 0 0;font-size:13px;text-align:center}
.bk2 .fee{min-height:0;margin:0}.bk2 .fee:empty{display:none}
.bk2 .qa{margin-top:10px;gap:8px;justify-content:center;overflow:visible}
.bk2 .qa button{height:36px;padding:0 13px;font-size:13px}
.bk2 .err{min-height:0;margin:4px 4px 0;text-align:center}.bk2 .err:empty{display:none}
.bk2 .gadd{margin:10px 16px 4px;padding:10px 14px;border-radius:16px}
.bk2 .tw{margin:6px 16px 0}

/* ---- ধাপ ৩: অঙ্ক · রেফারেন্স · কার্ড · PIN ---- */
.bk3 .bk3t{margin:10px 16px 0;padding:12px 14px;border-radius:16px;background:#fff;box-shadow:0 2px 10px rgba(160,40,100,.06)}
.bk3 .bk3t span{font-size:12.5px}.bk3 .bk3t b{font-size:16px;margin-top:3px}
.bk3 .bkref{margin:10px 16px 0;padding:11px 14px 12px;border-radius:16px;box-shadow:0 2px 10px rgba(160,40,100,.06)}
.bk3 .bkref input{font-size:15px;padding:8px 0 0}
.bk3 .gmrow{display:flex;align-items:center;gap:10px;margin:10px 16px 0;padding:13px 14px;border-radius:16px;background:#fff;box-shadow:0 2px 10px rgba(160,40,100,.06);font-size:14.5px;color:#2a1a22}
.bk3 .gmrow b{font-weight:700}
.bk3 .gmrow svg{width:24px;height:24px;flex:none;stroke:var(--p);fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.bk3 .pinrow.bkpin{margin:12px 16px 0;min-height:62px;padding:6px 8px 6px 16px!important;gap:12px;background:#fff;border:1.5px solid #f1dce8!important;border-radius:18px!important;box-shadow:0 4px 16px rgba(226,19,110,.08)!important}
.bk3 .pinrow.bkpin:focus-within{border-color:var(--p)!important;box-shadow:0 0 0 4px rgba(226,19,110,.12)!important}
.bk3 .bkpin>svg,.bk3 .bkpin .i{width:24px;height:24px;flex:none}
.bk3 .bkpin input{height:48px!important;font-size:20px!important;font-weight:600;letter-spacing:7px;text-align:center;padding:0 0 0 4px!important}
.bk3 .bkpin input::placeholder{font-size:15px;letter-spacing:0;font-weight:400;text-align:center}
.bk3 .bkpin .fpb{width:46px;height:46px;border-radius:50%}
.bk3 .bkpin .fpb svg{width:28px;height:28px}

/* ---- ধাপ ৪: নিশ্চিত করুন ---- */
.c4 .box{background:#faf5f8}
.c4h{padding:calc(20px + var(--st)) 20px 6px}
.c4h b{font-size:19px;line-height:1.3}
.c4x{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;padding:0;background:#fff;box-shadow:0 2px 8px rgba(160,40,100,.10)}
.c4x svg{width:20px;height:20px}
.c4b{padding:10px 16px 16px}
.c4w{padding:0;border:0;margin-bottom:12px}
.c4g{display:grid;grid-template-columns:1fr 1fr;gap:10px;border:0}
.c4g>div{padding:13px 14px;border:0!important;border-radius:16px;background:#fff;box-shadow:0 2px 10px rgba(160,40,100,.07);min-width:0}
.c4g>div:first-child{grid-column:1/-1;background:linear-gradient(135deg,#e2136e,#c70f5f);box-shadow:0 8px 20px rgba(226,19,110,.25)}
