.c4g>div:first-child b{color:#fff;font-size:26px;font-weight:700;letter-spacing:.2px}
.c4g span{font-size:12.5px;margin-bottom:4px}
.c4g b{font-size:16px;font-weight:700;line-height:1.3}
.c4g small{font-size:12.5px;margin-top:3px}
.c4g .wide{grid-column:1/-1}
