.bkr .bkh em{font-size:16px;line-height:1.3;font-weight:700;margin-top:2px}
.bkr .bkck{width:42px;height:42px;border-width:2.2px}
.bkr .bkck svg{width:22px;height:22px}
.bkr .rcp{padding:6px 0 12px}
.bkr .rcp b{font-size:15px}.bkr .rcp span{font-size:13px}
.bkg>div{padding:10px 14px}
.bkg span{font-size:12px}
.bkg b{font-size:14.5px;margin-top:3px}
.bkg .nbv{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%}
.bkg .nbv em{font-style:normal;min-width:0}
