/* ---- লেনদেনের বিস্তারিত: শুভেচ্ছা কার্ড ছোট, বিস্তারিত নিজের জায়গায় ---- */
.trdd .gcd{padding:2px 0 10px;display:block}
.trdd .gcd .gc{aspect-ratio:auto;width:100%;max-width:none;min-height:86px;height:auto;padding:12px 16px;align-items:flex-start;justify-content:center;text-align:left;border-radius:16px}
.trdd .gcd .gc .gct{font-size:17px;line-height:1.25;font-weight:700;max-width:56%}
.trdd .gcd .gc .gca{font-size:12.5px;margin-top:3px;max-width:56%}
.trdd .gcd .gc .gcn{font-size:12.5px;margin-top:3px;max-width:56%;overflow-wrap:anywhere}
.trdd .gcd .gc svg{left:auto;right:0;bottom:0;width:46%;height:100%}
.trdd .tnote{margin:0 4px 8px}
.trdd .tgrid{margin-top:8px}

/* ---- লেনদেনের সারি (হিস্টোরি): আলাদা আলাদা ঘর ---- */
.tr{margin:0 12px 8px;padding:12px 14px;min-height:72px;gap:12px;background:#fff;border:1px solid #f3e6ee!important;border-radius:18px;box-shadow:0 2px 10px rgba(160,40,100,.06);transition:transform .18s var(--ease),box-shadow .2s,background-color .2s}
.tr:first-of-type{margin-top:10px}
.tr:active{transform:scale(.985);background:#fff6fa;box-shadow:0 1px 4px rgba(160,40,100,.08)}
.tr .m b{font-size:14.5px;font-weight:700;color:#2a1a22}
.tr .m span{font-size:13px}
.tr .m small{font-size:11.5px}
.tr .r b{font-size:15px;font-weight:700}
.tr .r small{font-size:11.5px;display:block;margin-top:3px}
.tr .r b.mi{color:#d8135f}.tr .r b.pl{color:#12a15b}
.pg>#lst{padding:2px 0 10px;background:transparent!important;border:0!important;box-shadow:none!important;-webkit-backdrop-filter:none;backdrop-filter:none;margin:0}
.sec .tr:last-child{margin-bottom:0}
.pg>.note{border-radius:0 0 18px 18px;margin-bottom:6px}
.bk2>.bkl+.bkc{padding:8px 16px 10px}
.tr{gap:10px;padding:12px 12px 12px 14px}
.tr .m span{white-space:normal;overflow:visible;text-overflow:clip;line-height:1.3}
.tr .r b{font-size:14.5px}

/* ===== v2.28 — অ্যাপের কিপ্যাড: কোনো অ্যানিমেশন/ট্রানজিশন নেই (ল্যাগ কমানোর জন্য) ===== */
#kpad{transition:none!important;box-shadow:0 -2px 10px rgba(40,10,30,.10)}
#kpad .kpb,#kpad .kpb svg,#kpad .kk i{transition:none!important}
#kpad .kpg button{transition:none!important;box-shadow:none;border:1px solid #e6e3e8}
#kpad .kpg button:active{transform:none!important;background:#f0eef2}
#kpad .kpg .kd,#kpad .kpg .kk{border-color:transparent;background:transparent}
#kpad .kpg .kd:active,#kpad .kpg .kk:active{background:transparent}
#kpad.on .kpb svg{transform:none}
#kpad.sk .kpb{animation:none}
#kpad .kpg.dc{display:none}
#kpad.dec .kpg.pn{display:none}
#kpad.dec .kpg.dc{display:grid}
html.pinkb .pgx .pbody{scroll-behavior:auto}

/* =====================================================================
   v2.29 — লগইন পাতা স্থির (স্ক্রল নেই), ফিঙ্গারপ্রিন্ট ঘর (স্থির, ফাঁপা), My QR সাজ,
   স্ক্যান পাতার রং, নিশ্চিত পাতার নতুন মাথা/মোট ঘর, অ্যানিমেশন পরিষ্কার
   ===================================================================== */

/* ---- ১) লগইন (PIN) পাতা: একদম দাঁড়ানো, স্ক্রল হয় না, কিপ্যাড উঠলেও সব মাপে বসে ---- */
html:has(.pinp),body:has(.pinp){overflow:hidden;overscroll-behavior:none}
#app:has(.pinp){overflow:hidden;height:100vh;height:100dvh}
.fl.pinp{height:100vh;height:100dvh;min-height:0;max-height:100dvh;overflow:hidden}
.fl.pinp .phead{flex:1 1 0;min-height:0;justify-content:center;gap:0;padding:calc(56px + var(--st)) 20px 8px;overflow:hidden}
.fl.pinp .phead .lglogo.fpa{width:clamp(62px,15dvh,112px);height:auto;flex:none}
.fl.pinp .phead b{font-size:clamp(16px,2.7dvh,21px);line-height:1.35;margin-top:clamp(2px,1.2dvh,10px);font-weight:700}
.fl.pinp .psheet.bkl{flex:none;padding:18px 20px calc(16px + var(--sb))}
html.pinkb .fl.pinp .psheet.bkl{padding-bottom:calc(var(--kph,330px) + 12px)}
html.pinkb .fl.pinp .pgbtn{display:none}
.fl.pinp .psheet .bkf{margin-bottom:0}
.fl.pinp .bkn{padding:11px 16px;font-size:17px}
.fl.pinp .bkp input.pinin{height:46px}
.fl.pinp .psheet.bkl .le{min-height:18px;font-size:13px}
@media (max-height:700px){.fl.pinp .phead{padding-top:calc(50px + var(--st))}.fl.pinp .psheet.bkl{padding-top:12px}.fl.pinp .bkn{padding:8px 14px}}
@media (max-height:620px){.fl.pinp .phead b{display:none}}

/* ---- ২) ফিঙ্গারপ্রিন্ট: ফাঁপা (রং ভরা নয়) আইকন, চারপাশে হালকা ঘর, একদম স্থির ---- */
.bkfp,.fpb,.kp .fpk{
  flex:none;width:46px;height:46px;border:1.6px solid #ecbdd5;border-radius:15px;background:transparent;
  color:#e2136e;display:grid;place-items:center;box-shadow:none;animation:none!important;transition:none!important;transform:none!important;
  -webkit-tap-highlight-color:transparent;padding:0}
.bkfp.on{animation:none!important;border-radius:15px;border-color:#e2136e99}
.bkfp:active,.fpb:active,.kp .fpk:active{background:#e2136e12;border-color:#e2136e}
.bkfp svg,.fpb svg,.kp .fpk svg,.bk3 .bkpin .fpb svg{width:28px;height:28px;fill:none!important;stroke:#e2136e!important;stroke-width:1.45!important;stroke-linecap:round;stroke-linejoin:round}
.bk3 .bkpin .fpb{width:46px;height:46px;border-radius:15px}
.bkp{padding-right:6px}

/* ---- ৩) My QR: ফাঁকা জায়গায় লোগো ও নকশা ---- */
.pgx:has(.qpage) .box{background:linear-gradient(180deg,#fdf0f7 0%,#f8e7f0 55%,#fdf2f8 100%)}
.pgx:has(.qpage) .pbody{background:none;display:flex;flex-direction:column;padding-bottom:0}
.qpage{position:relative;overflow:hidden;flex:1 0 auto;display:flex;flex-direction:column;padding:18px 16px 12px}
.qpage>*{position:relative;z-index:1}
.qpage>.qdeco{position:absolute;z-index:0;inset:0;pointer-events:none;overflow:hidden}
.qdeco .d1,.qdeco .d2{position:absolute;border-radius:50%}
.qdeco .d1{width:320px;height:320px;left:-130px;bottom:-70px;background:radial-gradient(circle,rgba(226,19,110,.20),rgba(226,19,110,0) 68%)}
.qdeco .d2{width:260px;height:260px;right:-110px;bottom:60px;background:radial-gradient(circle,rgba(255,184,0,.22),rgba(255,184,0,0) 68%)}
.qdeco .d3{position:absolute;left:0;right:0;bottom:0;height:55%;background-image:radial-gradient(rgba(226,19,110,.22) 1.4px,transparent 1.7px);background-size:18px 18px;
  -webkit-mask-image:linear-gradient(transparent,#000 70%);mask-image:linear-gradient(transparent,#000 70%)}
.qdeco .qwm{position:absolute;width:56px;height:56px;opacity:.20;animation:qwf 6s ease-in-out infinite}
.qdeco .q1{left:10px;bottom:150px;transform:rotate(-14deg)}
.qdeco .q2{right:12px;bottom:190px;transform:rotate(12deg);animation-delay:-1.5s;width:48px;height:48px}
.qdeco .q3{left:46%;bottom:74px;transform:rotate(8deg);animation-delay:-3s;width:40px;height:40px;opacity:.16}
.qdeco .q4{left:14%;bottom:28px;transform:rotate(14deg);animation-delay:-2s;width:36px;height:36px;opacity:.14}
.qdeco .q5{right:16%;bottom:36px;transform:rotate(-10deg);animation-delay:-4s;width:44px;height:44px;opacity:.16}
.qdeco .q6{right:-8px;bottom:300px;transform:rotate(-18deg);animation-delay:-5s;width:40px;height:40px;opacity:.14}
.qcard{z-index:1;animation:zoomin .5s var(--ease) both}
.qcard:after{content:"";position:absolute;left:-56px;bottom:-64px;width:180px;height:180px;border-radius:50%;background:#ffffff14;pointer-events:none}
.qwrap{box-shadow:0 8px 22px rgba(60,0,30,.28)}
.qfoot{margin-top:auto;padding:26px 0 8px;display:flex;flex-direction:column;align-items:center;gap:3px;text-align:center}
.qfoot img{width:46px;height:46px;border-radius:15px;box-shadow:0 6px 16px rgba(226,19,110,.30);background:#fff}
.qfoot b{font-size:17px;font-weight:700;color:#c70f5f;letter-spacing:.5px;line-height:1.4}
.qfoot span{font-size:12.5px;color:#8a7380;line-height:1.4}

/* ---- ৪) স্ক্যান পাতা: কালো নয়, গোলাপি-বেগুনি রং, নকশা পরিষ্কার দেখা যায় ---- */
.sh.scanx .box,html.scanning:not(.camon) .sh.scanx .box{background:radial-gradient(120% 70% at 50% 0%,#c4156b 0%,#85104f 40%,#470a38 78%,#2f0828 100%)!important}
.sh.scanx .scf{box-shadow:0 0 0 200vmax #4a0b3a;border-radius:24px}
.sh.scanx .scbg .b1{background:#ff2f8e;opacity:.62;filter:blur(40px)}
.sh.scanx .scbg .b2{background:#ffb800;opacity:.30;filter:blur(44px)}
.sh.scanx .scbg .wm{width:66px;height:66px;opacity:.40;filter:drop-shadow(0 4px 10px rgba(0,0,0,.25))}
.sh.scanx .scbg .w1{left:16px;top:calc(104px + var(--st))}
.sh.scanx .scbg .w2{right:16px;top:calc(104px + var(--st))}
.sh.scanx .scbg .w3{left:16px;bottom:128px}
.sh.scanx .scbg .w4{right:16px;bottom:128px}
.sh.scanx .scbg:before{content:"";position:absolute;inset:0;background-image:radial-gradient(rgba(255,255,255,.20) 1.3px,transparent 1.6px);background-size:20px 20px;
  -webkit-mask-image:linear-gradient(#000 0,#000 24%,transparent 32%,transparent 66%,#000 74%,#000 100%);mask-image:linear-gradient(#000 0,#000 24%,transparent 32%,transparent 66%,#000 74%,#000 100%)}
.sh.scanx .scf i{border-color:#ff8cc0;width:42px;height:42px}
.sh.scanx .scf.hit i{border-color:#34d27b}
.sh.scanx .sctabs{background:rgba(255,255,255,.26);border-color:rgba(255,255,255,.5)}
.sh.scanx .scp{text-shadow:0 1px 10px rgba(60,0,40,.7)}
/* KYC ক্যামেরা/স্ক্যানের বাইরের অংশও একই রঙে */
#kyc .kcam{background:radial-gradient(130% 75% at 50% -8%,#a8186a 0%,#68104d 46%,#34082f 100%)}
#kyc .kcam .kbg .b1{background:radial-gradient(circle,rgba(255,60,150,.45) 0%,rgba(255,60,150,.16) 40%,rgba(255,60,150,0) 70%)}
#kyc .kwm{opacity:.34;width:64px;height:64px}
#kyc .kov u{box-shadow:0 0 0 100vmax rgba(52,8,47,.80)}

/* ---- ৫) নিশ্চিত পাতা: মাথার লেখা × এর সোজা, এক লাইনে, সব সমান মাপ; মোট ঘর ছোট ও সুন্দর ---- */
.c4h{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:calc(16px + var(--st)) 18px 4px}
.c4h b.c4t{flex:1;min-width:0;margin:0;display:flex;align-items:center;gap:6px;font-size:18px;line-height:1.7;font-weight:700;color:#2b2530;white-space:nowrap;overflow:hidden}
.c4t em,.c4t span{font-style:normal;font-size:inherit;line-height:inherit;display:inline-block}
.c4t em{color:#e2136e;font-weight:700}
.c4x{flex:none;width:38px;height:38px}
.c4g>div.c4tot{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 16px;border-radius:16px;
  background:linear-gradient(135deg,#e8197a,#c70f5f);box-shadow:0 6px 16px rgba(226,19,110,.22);animation:rise29 .45s var(--ease) both}
.c4g>div.c4tot:first-child b{color:#fff;font-size:23px;font-weight:700;line-height:1.35;letter-spacing:.2px;margin:0}
.c4g>div.c4tot:first-child small{margin:0;padding:4px 11px;border-radius:999px;background:rgba(255,255,255,.20);color:#fff!important;font-size:12px;line-height:1.45;white-space:nowrap}
.c4g>div:not(.c4tot){animation:rise29 .45s var(--ease) both;animation-delay:.06s}
.c4g>div:not(.c4tot):nth-child(n+3){animation-delay:.12s}
.c4n{animation:rise29 .45s var(--ease) both;animation-delay:.16s}

/* ---- ৬) অ্যানিমেশন পরিষ্কার: হোল্ড বাটন, চাপার অনুভূতি, নরম ওঠা-নামা ---- */
:root{--ease:cubic-bezier(.22,1,.36,1);--spring:cubic-bezier(.34,1.4,.64,1)}
*{-webkit-tap-highlight-color:transparent}
.lgh{transition:transform .18s var(--ease),box-shadow .25s}
.lgh.hd{transform:scale(.95);box-shadow:0 0 0 6px rgba(255,255,255,.18),0 6px 18px #0003}
.lgh .r1{transition:stroke-dashoffset .35s var(--ease)}
.lgh.hd .r1{transition:stroke-dashoffset 1s linear}
.lgh.ld{animation:lgp 1.1s ease-in-out infinite}
.c4f p{transition:opacity .2s}
.btn,.nbar,.bknx,.pill,.chip,.mr,.rr,.it,.fc{transition:transform .16s var(--ease),background-color .2s,opacity .2s,box-shadow .2s}
.btn:active,.nbar:active,.pill:active,.chip:active,.mr:active,.rr:active{transform:scale(.97)}
@keyframes rise29{from{opacity:0;transform:translateY(12px) scale(.985)}to{opacity:1;transform:none}}
@keyframes qwf{50%{translate:0 -7px}}
@media (prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}

/* ===== v2.31: গ্লাস নিচের বার (পুরো প্রস্থ, পেছনের লেখা ঝাপসা দেখা যায়) ===== */
.fback-sp{display:block;width:40px;height:40px}
nav,nav.fx{left:50%;bottom:0;width:100%;max-width:430px;height:calc(68px + var(--sb));padding:0 4px var(--sb);border-radius:0;
  background:linear-gradient(180deg,rgba(255,255,255,.50),rgba(255,255,255,.72));
  -webkit-backdrop-filter:blur(22px) saturate(1.8)!important;backdrop-filter:blur(22px) saturate(1.8)!important;will-change:transform;
  border:0;border-top:1px solid rgba(255,255,255,.75);
  box-shadow:0 -1px 0 rgba(226,19,110,.07),0 -10px 28px rgba(150,20,90,.09)}
nav button{position:relative;gap:4px;color:#6f6873;font-size:11.5px;font-weight:500;letter-spacing:.01em;transition:color .25s ease}
nav button em{font-style:normal;line-height:1.15;transition:color .25s ease,transform .3s var(--spring)}
nav button.on{color:var(--p);font-weight:700}
nav button .ni{width:30px;height:30px;transition:transform .32s var(--spring)}
nav button:active .ni{transform:scale(.88)}
nav button.on .ni{animation:navpop .42s var(--spring)}
nav .nvi{width:27px;height:27px;display:block;overflow:visible;fill:none;stroke:#6f6873;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;transition:stroke .25s ease}
nav .nvi.on{stroke:none}
nav .nvi.on .f{fill:var(--p);stroke:none}
nav .nvi.on .s{fill:none;stroke:var(--p);stroke-width:1.8}
nav .nvi.on .w{fill:none;stroke:#fff;stroke-width:1.9}
nav .nvi.on .wf{fill:#fff;stroke:none}
/* QR: উঁচু বোতাম নয়, বাকিদের মতোই এক সারিতে */
nav .qrb,nav .qrb .ni{color:inherit}
nav .qrb .ni{width:30px;height:30px;margin:0;background:none;border-radius:0;box-shadow:none}
nav .qrb .nvi .q{fill:none;stroke:var(--p);stroke-width:1.9}
nav .qrb .nvi .qf{fill:#3a3340;stroke:none}
nav .qrb{color:#3a3340;font-weight:600;gap:4px}
nav .ni .bg{top:-4px;right:-8px;min-width:19px;height:19px;border-radius:10px;font-size:11px;border:2px solid #fff;box-shadow:0 2px 6px rgba(226,19,110,.35)}

/* ===== v2.31 স্প্ল্যাশ: লোগো প্রথম ফ্রেম থেকেই ঠিক মাঝখানে, নড়ে না; অ্যানিমেশন ওখান থেকেই শুরু ===== */
#fpsplash{display:block;background:#c40f5e}
#fpsplash .fps-lg{position:absolute;left:50%;top:50%;width:160px;height:160px;margin:-80px 0 0 -80px;max-width:none}
#fpsplash .lglogo{width:160px;height:160px}
#fpsplash .fps-txt{position:absolute;left:0;right:0;top:calc(50% + 98px);display:flex;flex-direction:column;align-items:center}
#fpsplash .fps-name{margin-top:0}
#fpsplash .fps-tag{animation-delay:.95s}
#fpsplash .fps-ld{left:50%;margin-left:-23px;animation-delay:1.1s}
#fpsplash .fps-orb{opacity:0;animation:fps-in .9s ease .2s forwards,fpa-float 9s ease-in-out infinite}
@keyframes fps-in{to{opacity:1}}
#fpsplash .fpa-spin{animation:fpa-sn 7s linear infinite}
#fpsplash .fpa-ry{animation:fps-ray 2.2s ease-in-out .3s infinite}
@keyframes fps-ray{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.4;transform:scale(.9)}}

/* =====================================================================
   v2.32 — ভাগ ১ (এই ব্লক সবার শেষে, তাই আগের নিয়ম বদলে দেয়)
   ===================================================================== */

/* ---- ১) লগইন: লোগো + Good night এর ঠিক নিচেই ফর্ম ---- */
.fl.pinp{justify-content:flex-start}
.fl.pinp .phead{flex:none!important;padding:calc(70px + var(--st)) 20px 18px!important;justify-content:flex-start}
.fl.pinp .phead .lglogo.fpa{width:clamp(84px,14dvh,108px)}
.fl.pinp .phead b{margin-top:6px;font-size:21px}
.fl.pinp .psheet.bkl{flex:none;margin:0 16px;border-radius:24px;padding:16px 16px 16px;box-shadow:0 16px 36px rgba(60,0,30,.28);animation:fup .5s var(--ease) .08s both}
html.pinkb .fl.pinp .psheet.bkl{padding-bottom:16px}
.fl.pinp .psheet .bkf{margin-bottom:0}
.fl.pinp .psheet .bkf+.bkf{margin-top:14px}
.fl.pinp .psheet .bkf label{margin-bottom:7px;display:block;line-height:1.3}
.fl.pinp .bkn{padding:12px 16px;border-radius:14px;font-size:17px;border-width:1px}
/* PIN ঘর: চিকন */
.fl.pinp .bkp{min-height:0!important;height:48px;padding:0 6px 0 14px!important;border:1px solid #e8d7e1;border-radius:14px;box-shadow:none;background:#fff;gap:6px}
.fl.pinp .bkp:focus-within{border-color:#e2136e;box-shadow:0 0 0 3px rgba(226,19,110,.10)}
.fl.pinp .bkp input.pinin{height:44px!important;font-size:18px!important}
.fl.pinp .bkfp{width:36px;height:36px;border-radius:11px;border-width:1px}
.fl.pinp .bkfp svg{width:23px;height:23px}
.fl.pinp .psheet.bkl .le{min-height:16px;margin-top:6px}
.fl.pinp .pgbtn{margin-top:6px}
@media (max-height:640px){.fl.pinp .phead{padding-top:calc(52px + var(--st))!important}}

/* ---- ২) ফিঙ্গারপ্রিন্ট সুইচ: স্মুথ স্লাইড ---- */
.sw{transition:background-color .3s cubic-bezier(.4,0,.2,1)!important}
.sw b{transition:transform .3s cubic-bezier(.4,0,.2,1)!important;will-change:transform}

/* ---- ৩) আমার QR: নিচে ফাঁকা নেই ---- */
.pgx:has(.qpage) .stp{flex:1 0 auto;display:flex;flex-direction:column;min-height:100%}
.qpage{flex:1 0 auto}
.qcard{padding-top:26px}
.qcard b{font-size:20px}
.qcard small{font-size:12.5px;line-height:1.5;padding:0 8px}

/* ---- ৪) কনফার্ম পেজ: ছোট ✕, লেখার সোজাসুজি; ২ সেকেন্ড হোল্ড ---- */
.c4h{align-items:center!important;padding:calc(14px + var(--st)) 16px 4px 18px!important}
.c4h b.c4t{line-height:1.25!important;font-size:18px}
.c4x{width:30px!important;height:30px!important;box-shadow:none!important;background:#fff;border:1px solid #f0dfe8;align-self:center}
.c4x svg{width:14px!important;height:14px!important;stroke-width:2.8!important}
.lgh.hd .r1{transition:stroke-dashoffset 2s linear!important}
.lgh .r1{transition:stroke-dashoffset .3s ease-out}
.c4g>div:not(.c4tot),.c4n{animation:fade .28s ease both!important}

/* ---- ৫) সফল পেজ: চোখ ঘরের ডান কিনারায়, মাঝখানে, বড় ---- */
.bkg .nbc{position:relative}
.bkg .nbc .nbv{padding-right:44px}
.bkg .nbc .nbv .eye{position:absolute!important;right:8px;top:50%;margin:0!important;transform:translateY(-50%);width:40px;height:40px;display:grid;place-items:center;border-radius:50%}
.bkg .nbc .nbv .eye svg{width:24px!important;height:24px!important}
.bkg .nbc .nbv .eye:active{background:#fde7f1}

/* ---- ৬) পেজ বদল: লাফানো বন্ধ — শুধু স্লাইড, ঝাপসা/অন্ধকার ব্যাকড্রপ নেই ---- */
.sh.pgx{background:transparent!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important;animation:none!important}
.sh.pgx .box{animation:pgSlideIn .3s cubic-bezier(.2,.8,.2,1) both!important;will-change:transform;box-shadow:-10px 0 28px rgba(60,0,30,.14)}
.sh.pgx.re,.sh.pgx.re .box{animation:none!important}
.sh.pgx.out{animation:none!important}
.sh.pgx.out .box{animation:pgSlideOut .22s cubic-bezier(.4,0,1,1) both!important}
@keyframes pgSlideIn{from{transform:translate3d(100%,0,0)}to{transform:translate3d(0,0,0)}}
@keyframes pgSlideOut{from{transform:translate3d(0,0,0)}to{transform:translate3d(100%,0,0)}}
.sh.dlg{-webkit-backdrop-filter:none!important;backdrop-filter:none!important}
.sh.dlg .box{-webkit-backdrop-filter:none!important;backdrop-filter:none!important;background:#fff!important}
.stp.go{animation:fade .18s ease both!important}
/* ট্যাব বদল: শুধু ফেড, নিচের বার নড়ে না */
.pg.in{animation:fade .18s ease both!important}
.pg.in .it,.pg.in .tr,.pg.in .tri div,.pg.in .fc,.pg.in .mr,.pg.in>*{animation:none!important}
nav.fx{animation:none!important}
.hero,.wsheet,nav{backface-visibility:hidden}

/* ---- ৭) রিফ্রেশ: বিকাশের মতো ছোট গোল, ওপর থেকে নামে ---- */
#ptrv{display:none!important}
#ptr{position:fixed!important;left:50%!important;top:calc(var(--st,0px) + 66px)!important;margin:0!important;width:40px!important;height:40px!important;border-radius:50%!important;background:#fff!important;box-shadow:0 4px 14px rgba(120,10,60,.28)!important;display:grid;place-items:center;opacity:0;pointer-events:none;z-index:60!important;will-change:transform,opacity;transform:translate3d(-50%,-60px,0) scale(.6)}
#ptr .lgl{width:26px!important;height:26px!important}

/* ---- ৮) লোডিং লোগো (নেটওয়ার্ক ধীর হলে) ---- */
#fpld{position:fixed;inset:0;z-index:99;display:grid;place-items:center;background:rgba(0,0,0,.42);opacity:0;pointer-events:none;transition:opacity .2s ease}
#fpld.on{opacity:1;pointer-events:auto}
#fpld .ldb{width:88px;height:88px;border-radius:20px;background:#fff;display:grid;place-items:center;box-shadow:0 10px 30px rgba(0,0,0,.25);animation:ldpulse 1.1s ease-in-out infinite}
#fpld .ldb img{width:54px;height:54px;object-fit:contain}
@keyframes ldpulse{0%,100%{transform:scale(1)}50%{transform:scale(.93)}}

/* ---- ৯) ব্যালেন্স দেখুন: স্পিনার → সংখ্যা গুনে ওঠে → আস্তে মিলিয়ে যায় ---- */
.bp span{font-variant-numeric:tabular-nums}
.bp.pk-ld span{position:relative;color:transparent}
.bp.pk-ld span::after{content:"";position:absolute;left:50%;top:50%;width:14px;height:14px;margin:-7px 0 0 -7px;border-radius:50%;border:2px solid rgba(226,19,110,.22);border-top-color:#e2136e;animation:lgspin .7s linear infinite}
.bp.pk-ld u{animation:ldpulse .7s ease-in-out infinite}
.bp span.pk-n{font-weight:700;color:#e2136e;animation:fade .2s ease both}
.bp span.pk-o{opacity:0;transition:opacity .22s ease}

/* =====================================================================
   v2.33 — ভাগ ২ (এই ব্লক সবার শেষে)
   ===================================================================== */
/* ফোনের কিবোর্ডের ওপরের বার (নাম্বার/পরিমাণ ঘর) */

html.pinkb .v3fab{display:none!important}
/* স্ট্যাক পেজ */
.v3p .box,.v3s1 .box{position:relative}
.v3p .pbody,.v3s1 .pbody{background:#fff}
.v3s{padding:12px 16px 4px;background:#fff}
.v3s .fld.sf{height:48px;border-radius:12px;background:#f6f6f7;border:1px solid #e3e1e4}
.v3s .err{min-height:0}
.v3s1 .pbody .stp>.pcard.v3l{margin:0;padding:0 16px;background:#fff;box-shadow:none;border-radius:0;border:0}
.v3s1 .pfoot{display:none}
.v3s1.v3g .pfoot{display:block}
.qrbtn.v3q{width:calc(100% - 32px);margin:10px 16px 4px;height:48px;border-radius:10px;font-size:15px}
.v3tr{display:flex;gap:10px;overflow-x:auto;padding:14px 16px 12px;scrollbar-width:none;-webkit-overflow-scrolling:touch;background:#fff;border-bottom:1px solid #f1edf1}
.v3tr::-webkit-scrollbar{display:none}
.v3t{flex:none;width:92px;min-height:96px;border:1px solid #f0e8ee;border-radius:12px;background:#fff;padding:10px 8px 8px;display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;gap:10px;cursor:pointer;font-family:inherit;-webkit-tap-highlight-color:transparent}
.v3t:active{background:#fdf0f6}
.v3t span svg{width:30px;height:30px;fill:none;stroke:#e2136e;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.v3t b{font-size:12.5px;font-weight:600;color:#2b2428;text-align:left;line-height:1.3}
.v3h{font-size:12.5px;color:var(--mu);font-weight:700;padding:14px 0 4px;margin:0}
.v3s1 .v3h{padding-left:0}
.v3rr{border-top:0!important;padding:9px 0!important;gap:14px}
.v3rr b{font-size:14.5px;font-weight:600}
.v3cb{width:22px;height:22px;border:2px solid #cfc6cb;border-radius:4px;margin-left:auto;display:grid;place-items:center;flex:none;transition:background-color .15s,border-color .15s}
.v3cb svg{width:14px;height:14px;fill:none;stroke:#fff;stroke-width:3.2;opacity:0;transition:opacity .15s}
.v3cb.on{background:#e2136e;border-color:#e2136e}
.v3cb.on svg{opacity:1}
.v3fab{position:absolute;right:16px;bottom:calc(20px + var(--sb,0px));z-index:3;height:44px;padding:0 18px;border:0;border-radius:24px;background:linear-gradient(180deg,#ec2c80,#dc1068);color:#fff;font-weight:700;font-size:14.5px;display:flex;align-items:center;gap:6px;font-family:inherit;box-shadow:0 6px 18px rgba(226,19,110,.38);cursor:pointer}
.v3fab svg{width:20px;height:20px;fill:none;stroke:#fff;stroke-width:2.6;stroke-linecap:round}
.v3fab:active{transform:scale(.97)}
.v3pm{margin:14px 0;padding:16px;border-radius:12px;background:#fdf0f6;text-align:center}
.v3pm p{margin:0 0 10px;font-size:13.5px;color:#5a4a53}
.v3pm small{display:block;margin-top:4px;color:#a08a96;font-size:11px}
.v3pm button{height:40px;padding:0 22px;border:0;border-radius:10px;background:#e2136e;color:#fff;font-weight:700;font-family:inherit;font-size:14px}
.v3sk i{display:block;height:44px;margin:12px 0;border-radius:10px;background:linear-gradient(90deg,#f3eef1 25%,#faf7f9 50%,#f3eef1 75%);background-size:200% 100%;animation:v3sh 1.2s linear infinite}
@keyframes v3sh{to{background-position:-200% 0}}
.v3pre{margin:0;padding:12px 16px;font-size:13px;color:#5a4a53;background:#fdf6f9}
.v3cl .v3h,.v3cl .v3list{padding-left:16px;padding-right:16px}
.v3cl .v3list{padding-bottom:70px}
.v3bar{width:100%;height:52px;border:0;background:#9e9a9f;color:#fff;font-weight:700;font-size:16px;font-family:inherit;display:flex;align-items:center;justify-content:space-between;padding:0 20px;transition:background-color .2s}
.v3bar.on{background:linear-gradient(90deg,#e2136e,#f0549a)}
.v3bar svg{width:26px;height:26px;fill:none;stroke:#fff;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.pgx .pfoot:has(.v3bar){padding:0;background:transparent;box-shadow:none}
/* প্রিয় নাম্বার */
.v3fv .pbody{background:#fff;padding-bottom:90px}
.v3fx{padding:0}
.v3fs{display:block;padding:10px 16px;font-size:11.5px;color:var(--mu);background:#fbf7f9;border-bottom:1px solid #f1edf1}
.v3fu{text-align:center;padding:18px 16px 16px;border-bottom:8px solid #f6f1f4}
.v3fu span{font-size:12.5px;color:var(--mu)}
.v3fu b{display:block;font-size:26px;color:#e2136e;font-weight:700;margin:4px 0 6px}
.v3fu p{margin:0;font-size:12.5px;color:#4a3d44;font-weight:600}
.v3fu i{display:inline-grid;place-items:center;width:16px;height:16px;border-radius:50%;border:1.3px solid #e2136e;color:#e2136e;font-style:italic;font-size:10px;font-weight:700;vertical-align:middle;margin-left:4px;cursor:pointer}
.v3fh{display:flex;justify-content:space-between;padding:12px 16px 6px;font-size:12.5px;color:var(--mu);font-weight:700}
.v3fh em{font-style:normal}
.v3fr{display:flex;align-items:center;gap:14px;padding:11px 16px;border-top:1px solid #f4eff2}
.v3fr b,.v3pw b{display:block;font-size:14.5px;font-weight:600}
.v3fr span,.v3pw span{display:block;font-size:12.5px;color:var(--mu);margin-top:1px}
.v3fr>div{flex:1;min-width:0}
.v3rm{border:0;background:none;color:#e0182d;font-weight:600;font-size:13.5px;font-family:inherit;padding:8px 2px}
/* PIN পেজ */
.v3pc{padding:0}
.v3pw{display:flex;align-items:center;gap:14px;padding:16px;border-bottom:1px solid #f1edf1;background:#fff}
.v3fi{width:44px;height:44px;border-radius:50%;background:#fdf0f6;display:grid;place-items:center;flex:none}
.v3fi svg{width:24px;height:24px;stroke:#e2136e;fill:none}
.v3sm{display:flex;justify-content:space-between;padding:14px 16px;border-bottom:1px solid #f1edf1;font-size:13.5px}
.v3sm b{color:#e2136e;font-size:16px}
.v3nl{margin:0;padding:16px 16px 4px;font-size:12.5px;color:var(--mu);font-weight:600}
.v3nt{margin:0;padding:0 16px 14px;font-size:13.5px;line-height:1.55;color:#4a3d44}
.v3pr{display:flex;align-items:center;gap:10px;margin:0;padding:0 12px 0 16px;height:54px;border-top:1px solid #f1edf1;border-bottom:1px solid #f1edf1;background:#fff}
.v3pr>svg{width:20px;height:20px;color:#e2136e;flex:none}
.v3pr input{flex:1;min-width:0;border:0;outline:0;background:transparent;font-size:16px;font-family:inherit;text-align:center;letter-spacing:2px}
.v3pr input::placeholder{letter-spacing:0;color:#a89aa2}
.v3pr .fpb{width:40px;height:40px;border:0;background:none;display:grid;place-items:center;flex:none}
.v3pr .fpb svg{width:30px;height:30px;stroke:#e2136e;fill:none}
.v3pc .err{text-align:center;padding:8px 16px 0;min-height:22px}
/* রিকোয়েস্ট মানি */
.v3ac{padding:0 0 20px}
.v3cd{background:#fff;border-top:1px solid #f1edf1;border-bottom:1px solid #f1edf1}
.v3cd .fld.big{border:0;background:transparent}
.v3nf input{width:100%;height:50px;border:0;outline:0;padding:0 16px;font-size:15px;font-family:inherit;background:transparent}
.v3tabs{display:flex;border-bottom:1px solid #eee7ec;background:#fff;position:sticky;top:0;z-index:2}
.v3tabs button{flex:1;height:46px;border:0;background:none;font-family:inherit;font-size:13.5px;color:var(--mu);font-weight:600;border-bottom:2.5px solid transparent;transition:color .2s,border-color .2s}
.v3tabs button.on{color:#e2136e;border-bottom-color:#e2136e}
.v3em{text-align:center;padding:64px 40px;color:var(--mu);font-size:13.5px;line-height:1.6}
.v3em svg{width:84px;height:84px;fill:none;stroke:#e2136e;stroke-width:1.1;opacity:.75;margin-bottom:10px}
.v3rl{padding:8px 0}
.v3rq{padding:12px 16px;border-bottom:1px solid #f4eff2}
.v3rh{display:flex;align-items:center;gap:12px}
.v3rh>div{flex:1;min-width:0}
.v3rh b{display:block;font-size:14.5px;font-weight:600}
.v3rh span{display:block;font-size:12.5px;color:var(--mu)}
.v3rh em{font-style:normal;font-weight:700;color:#e2136e;font-size:15px}
.v3rq p{margin:8px 0 0;font-size:13px;color:#4a3d44}
.v3rf{display:flex;justify-content:space-between;align-items:center;margin-top:8px;gap:8px}
.v3rf small{font-size:11.5px;color:var(--mu)}
.v3rf u{text-decoration:none;font-weight:700}
.v3rf u.s-pending{color:#d98a00}.v3rf u.s-paid{color:#1a9d5c}.v3rf u.s-declined,.v3rf u.s-cancelled{color:#c0182b}
.v3rf span{display:flex;gap:8px}
.v3b1,.v3b2{height:34px;padding:0 16px;border-radius:9px;font-weight:700;font-size:13px;font-family:inherit}
.v3b1{border:1px solid #e2136e;background:#fff;color:#e2136e}
.v3b2{border:0;background:#e2136e;color:#fff}
.v3dn{text-align:center;padding:70px 28px}
.v3ok{width:84px;height:84px;border-radius:50%;background:#e8f7ef;display:inline-grid;place-items:center;margin-bottom:16px}
.v3ok svg{width:44px;height:44px;fill:none;stroke:#1a9d5c;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.v3dn h3{margin:0 0 6px;font-size:19px;color:#1a9d5c}
.v3dn p{margin:0 0 6px;font-size:15px;font-weight:600}
.v3dn small{color:var(--mu);font-size:12.5px}
/* টাচ/ফেস আইডি পেজ */
.v3bp .pbody{background:#fff}
.v3bh{text-align:center;padding:16px 20px 22px;border-bottom:6px solid #f4f1f3}
.v3fa{width:150px;height:150px;display:block;margin:0 auto 10px}
.v3bh b{display:block;font-size:17px;font-weight:700;margin-bottom:4px}
.v3bh p{margin:0;font-size:14px;color:var(--mu)}
.v3sel{margin:0;padding:14px 16px 8px;font-size:13px;color:var(--mu)}
.v3opt{display:flex;align-items:center;gap:10px;margin:0 16px 14px;padding:14px 14px 14px 16px;border:1.5px solid #e8e2e6;border-radius:12px;cursor:pointer;transition:border-color .2s,background-color .2s}
.v3opt>div{flex:1}
.v3opt b{display:block;font-size:15px;font-weight:600;margin-bottom:6px}
.v3opt span{display:block;font-size:14px;color:#4a3d44;line-height:1.4}
.v3opt u{display:inline-block;margin-top:6px;font-size:13.5px;color:#e2136e;text-decoration:none;font-weight:500}
.v3opt.on{border-color:#e2136e}
.v3rd{width:26px;height:26px;border-radius:50%;background:#e2136e;display:grid;place-items:center;flex:none;transform:scale(0);transition:transform .2s cubic-bezier(.2,.8,.2,1)}
.v3rd svg{width:15px;height:15px;fill:none;stroke:#fff;stroke-width:3.2;stroke-linecap:round;stroke-linejoin:round}
.v3opt.on .v3rd{transform:scale(1)}
.v3nb{margin:6px 16px 20px;padding:14px 16px;border-radius:8px;background:#f5f5f6;font-size:14px;line-height:1.5;color:#2b2428;animation:fade .2s ease both}
/* স্মুথ: নতুন স্তরে GPU, ঝাপসা নেই */
#sheet2 .sh.pgx{z-index:10}
#sheet2 .sh.pgx .box{will-change:transform}
.v3s1 .sh,.v3s1{backface-visibility:hidden}
.rr.v3rr:active{background:#fdf0f6}

.v3cd .fld.big{display:flex;justify-content:center;align-items:center;gap:6px;padding:12px 16px}
.v3cd .fld.big u{position:static;text-decoration:none}


/* =====================================================================
   v2.34 — নগদের মতো নরম ব্যাকগ্রাউন্ড, লগইন/কোড পেজ গোছানো, KYC পেজ নতুন ডিজাইন
   ===================================================================== */
/* ---- হালকা পেজের ব্যাকগ্রাউন্ড (লগইন, কোড, অ্যাকাউন্ট খোলা) ---- */
.fl.light{
  background:
    radial-gradient(75% 40% at 112% -6%, rgba(255,140,190,.55) 0%, rgba(255,140,190,0) 72%),
    radial-gradient(62% 36% at -14% 4%, rgba(255,206,164,.50) 0%, rgba(255,206,164,0) 72%),
    linear-gradient(180deg,#fff1f7 0%,#fdf5f9 40%,#fbf8fa 100%);
}
.fl.light::after{content:"";position:absolute;right:-84px;bottom:-40px;width:320px;height:320px;background:url(../icons/logo-pink.png) center/contain no-repeat;opacity:.055;pointer-events:none;z-index:0;transform:rotate(-12deg)}
.fl.light>*{position:relative;z-index:1}

/* ---- লগইন পেজ: ফাঁকা কমানো, পরবর্তী বাটন কিবোর্ডের ওপরেই দেখা যায় ---- */
.fl.light .fbar{padding-top:calc(8px + var(--st))}
.fl.light .fbody{padding:6px 22px 16px}
.fl.light .fbody .mini{width:46px;margin:0 0 8px}
.fl.light .fbody h2{font-size:19px;line-height:1.3}
.fl.light .fbody label{margin:12px 0 6px}
.fl.light .le{min-height:0;margin-top:8px}
.fl.light .le:empty{margin:0}
.fl.light .terms{margin-top:10px;font-size:12.5px;line-height:1.45}
.nbar.nin{position:relative;bottom:auto;width:100%;height:54px;margin-top:14px;padding:0 22px;border-radius:16px;background:linear-gradient(90deg,#e2136e,#f0549a);box-shadow:0 10px 22px rgba(226,19,110,.28)}
.fl.light:focus-within .nbar.nin{background:linear-gradient(90deg,#e2136e,#f0549a)}
.nbar.nin:active{transform:scale(.98)}
.nbar.nin.ld{background:var(--lp,#e2136e)!important}

/* ---- কোড যাচাই পেজ ---- */
.otpv .otpph{display:block;width:max-content;max-width:100%;margin:16px 0 4px;padding:11px 22px;border-radius:28px;background:linear-gradient(180deg,#fff,#fde7f1);border:1.5px solid #f6c3d9;color:#c40f5e;font-size:24px;font-weight:700;letter-spacing:.6px;box-shadow:0 8px 20px rgba(226,19,110,.14)}
.otpv .otpb{gap:10px;margin:22px 0 2px}
.otpv .otpb i{height:62px;border-radius:17px;box-shadow:0 4px 12px rgba(160,40,100,.08)}
.otpv .otst{margin-top:12px;min-height:26px}
.otpv .otpact{display:flex;gap:12px;margin:16px 0 0}
.otpv .otpact .otpp,.otpv .otpact .otprs{flex:1;height:54px;border-radius:27px;font-size:15px;font-weight:700;gap:9px;transition:transform .18s var(--ease),box-shadow .25s,background .25s}
.otpv .otpact .otprs{border:1.5px solid #ecdce6;background:#fff;color:#9a8f98;box-shadow:0 4px 12px rgba(160,40,100,.06)}
.otpv .otpact .otprs.rdy{border-color:#f3b9d3;background:#fff;color:var(--lp);box-shadow:0 6px 16px rgba(226,19,110,.14)}
.otpv .otpact .otpp{border:0;background:linear-gradient(135deg,#e2136e,#f0549a);color:#fff;box-shadow:0 10px 22px rgba(226,19,110,.3)}
.otpv .otpact .otpp svg{width:19px;height:19px;stroke:#fff;fill:none}
.otpv .otpact .otpp:active,.otpv .otpact .otprs:active{transform:scale(.96)}

/* ---- KYC তথ্য পাতা: ঘরগুলো আরও সুন্দর, জন্মতারিখের এডিট বাটন ডানে মাঝখানে ---- */
#kyc .kbody .kf{position:relative;padding:11px 14px;gap:12px;border-radius:20px;margin-bottom:10px;background:#fff;box-shadow:0 8px 22px rgba(170,20,95,.09)}
#kyc .kbody .kf .kfi{width:42px;height:42px;border-radius:14px;background:linear-gradient(160deg,#fff0f7,#fbd3e5)}
#kyc .kbody .kf .kfi svg{width:21px;height:21px}
#kyc .kbody .kf label{font-size:11.5px;font-weight:700;letter-spacing:.2px;margin-bottom:2px}
#kyc .kbody .kf input,#kyc .kbody .kf textarea{font-size:15.5px;font-weight:700}
#kyc .kbody .kf.gd{background:linear-gradient(180deg,#fff,#f6fdf9)}
#kyc .kbody .kf .kt2{width:28px;height:28px}
#kyc .kbody .kf .kt2 svg{width:15px;height:15px}
#kyc .kbody .ksum{border-radius:20px;padding:12px 16px;box-shadow:0 8px 22px rgba(170,20,95,.09)}
#kyc .kdb{position:static;min-height:34px;padding:0}
#kyc .kdb em{position:absolute;right:56px;top:50%;transform:translateY(-50%);display:inline-flex;align-items:center;gap:6px;font-size:14px;font-weight:700;padding:9px 15px;border-radius:22px;background:linear-gradient(135deg,#fde7f1,#fbd3e5);color:var(--p);box-shadow:0 4px 10px rgba(226,19,110,.14)}
#kyc .kdb em svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
#kyc .kdb:active em{transform:translateY(-50%) scale(.94)}

/* ---- KYC ক্যামেরা পাতা (আইডি কার্ড + মুখ): হালকা গোলাপি ব্যাকগ্রাউন্ড, লোগো দিয়ে ডিজাইন ---- */
#kyc .kcam.kn{--fw:min(60vw,236px);background:linear-gradient(180deg,#fff4fa 0%,#ffe3ef 52%,#ffd0e4 100%);color:#2a1020}
#kyc .kcam.kn .kbg .b1{left:50%;top:44%;width:150vmin;height:150vmin;margin:-75vmin 0 0 -75vmin;background:radial-gradient(circle,rgba(255,255,255,.95) 0%,rgba(255,255,255,.5) 34%,rgba(255,255,255,0) 66%);animation:kaura 5.5s ease-in-out infinite}
#kyc .kcam.kn .kbg .b2{display:block;left:-20vmin;right:auto;top:-18vmin;bottom:auto;width:70vmin;height:70vmin;border-radius:50%;background:radial-gradient(circle,rgba(255,150,196,.55),rgba(255,150,196,0) 70%);filter:none;opacity:1}
#kyc .kcam.kn .kbg .b3{position:absolute;inset:0;background:url(../icons/logo-pink.png) 0 0/56px 56px space;opacity:.07;-webkit-mask-image:linear-gradient(180deg,#000 0%,rgba(0,0,0,.25) 38%,rgba(0,0,0,.25) 62%,#000 100%);mask-image:linear-gradient(180deg,#000 0%,rgba(0,0,0,.25) 38%,rgba(0,0,0,.25) 62%,#000 100%)}
#kyc .kcam.kn .ktp{padding-top:calc(8px + var(--st))}
#kyc .kcam.kn .kbk{color:var(--p);background:#fff;box-shadow:0 4px 12px rgba(226,19,110,.16);width:40px;height:40px;margin-top:2px}
#kyc .kcam.kn .kbk:active{background:#fde7f1}
#kyc .kcam.kn .ktp b{left:60px;right:60px;color:#2a1020;font-size:15.5px;line-height:44px}
#kyc .kcam.kn .ktp em{background:#fff;color:var(--p);box-shadow:0 4px 12px rgba(226,19,110,.16)}
#kyc .kcam.kn .klg{top:calc(76px + var(--st));flex-direction:column;gap:5px;color:#c40f5e;font-size:18px;letter-spacing:.6px}
#kyc .kcam.kn .klg img{width:70px;height:70px;border-radius:0;background:none;padding:0;box-shadow:none;filter:drop-shadow(0 6px 12px rgba(226,19,110,.25))}
#kyc .kcam.kn .kbt{background:linear-gradient(0deg,rgba(255,214,232,.97) 46%,rgba(255,214,232,0));color:#2a1020}
#kyc .kcam.kn .kbt p{color:#6a3350;opacity:1;font-weight:600}
#kyc .kcam.kn .knc{color:#c40f5e}
/* আইডি কার্ডের ঘর */
#kyc .kcam.kn .kwr:not(.ov){top:50%}
#kyc .kcam.kn .kwr:not(.ov) .kwin{border-radius:20px;box-shadow:0 0 0 5px #fff,0 0 0 7px rgba(226,19,110,.35),0 18px 40px rgba(226,19,110,.26)}
#kyc .kcam.kn .kfr i{border-color:var(--p)}
#kyc .kcam.kn .kfr.dn i{border-color:#12a15b}
#kyc .kcam.kn .kchk{top:50%}
#kyc .kcam.kn .kshut{border-color:var(--p);background:#fff}
#kyc .kcam.kn .kshut i{background:linear-gradient(135deg,#e2136e,#f0549a)}
#kyc .kcam.kn .kgal{background:#fff;color:var(--p);box-shadow:0 4px 12px rgba(226,19,110,.16)}
#kyc .kcam.kn .kgal.sp{visibility:hidden}
#kyc .kcam.kn .kgh{background:#fff;color:var(--p);border:1.5px solid #f3b9d3}
/* মুখের ঘর (ডিম্বাকৃতি) */
#kyc .kcam.kn .kwr.ov{top:46%;width:var(--fw);aspect-ratio:.78}
#kyc .kcam.kn .kwr.ov .kwin{inset:3.4%;box-shadow:0 0 0 5px #fff,0 0 0 7px rgba(226,19,110,.3),0 18px 44px rgba(226,19,110,.28)}
#kyc .kcam.kn .kov u{top:46%;width:var(--fw);box-shadow:none;border:0}
#kyc .kcam.kn .kov u.dn{box-shadow:0 0 26px #12a15b66}
#kyc .kcam.kn .kcnt{top:46%;color:var(--p);text-shadow:0 4px 18px #fff}
#kyc .kcam.kn .kfok{top:46%}
#kyc .kcam.kn .krt{stroke:rgba(226,19,110,.22);stroke-width:3}
#kyc .kcam.kn .krf{stroke:var(--p);stroke-width:3.6}
#kyc .kcam.kn .kra.on{filter:drop-shadow(0 0 5px rgba(226,19,110,.55))}
#kyc .kcam.kn .kra.on .krt{stroke:rgba(226,19,110,.75);stroke-width:3.8}
#kyc .kcam.kn .kra.dn2 .krt,#kyc .kcam.kn .kra.dn2 .krf{stroke:#12a15b}
#kyc .kcam.kn .kfarr.up{top:calc(46% - var(--fw) / 1.56 - 64px)}
#kyc .kcam.kn .kfarr.down,#kyc .kcam.kn .kfarr.blink{top:calc(46% + var(--fw) / 1.56 + 12px)}
#kyc .kcam.kn .kfarr.left,#kyc .kcam.kn .kfarr.right{top:46%}
/* কী করতে হবে: গাইড কার্ড */
#kyc .kcam.kn .kdir{gap:14px;border-radius:26px;padding:12px 18px 12px 12px;margin:0 0 12px;background:linear-gradient(180deg,#fff,#fff5fa);border:1.5px solid #f8cde1;box-shadow:0 14px 34px rgba(226,19,110,.2)}
#kyc .kcam.kn .kgd{width:80px;height:80px;box-shadow:0 0 0 4px #fff,0 0 0 6px rgba(226,19,110,.25),0 8px 18px rgba(226,19,110,.25)}
#kyc .kcam.kn .kdir .kfm{font-size:16.5px;font-weight:700;line-height:1.3;color:#2a1020}
#kyc .kcam.kn .kdots{gap:7px;margin-top:10px}
#kyc .kcam.kn .kdots i{height:7px;border-radius:4px;background:#f3dbe7}
#kyc .kcam.kn .kdots.d5 i{height:7px}
#kyc .kcam.kn .kpg .kfbar{height:8px;background:rgba(226,19,110,.15)}
#kyc .kcam.kn .kpg .kfbar i{background:linear-gradient(90deg,#e2136e,#ff7ab4 60%,#12a15b)}
#kyc .kcam.kn .kpg .kfpc{color:var(--p);font-size:15px}

/* =====================================================================
   v2.35 — KYC ধাপ বদলের অ্যানিমেশন, অটো ছবির ঝলক, যাচাইয়ের লাইভ তালিকা
   ===================================================================== */
@keyframes kpIf{from{opacity:0;transform:translateX(44px) scale(.97)}to{opacity:1;transform:none}}
@keyframes kpIb{from{opacity:0;transform:translateX(-44px) scale(.97)}to{opacity:1;transform:none}}
@keyframes kpOf{from{opacity:1;transform:none}to{opacity:0;transform:translateX(-52px) scale(.96)}}
@keyframes kpOb{from{opacity:1;transform:none}to{opacity:0;transform:translateX(52px) scale(.96)}}
#kyc .kpi-f{animation:kpIf .46s cubic-bezier(.22,1,.36,1) backwards}
#kyc .kpi-b{animation:kpIb .46s cubic-bezier(.22,1,.36,1) backwards}
#kyc .kpo{position:absolute!important;top:0;bottom:0;left:0;right:0;margin:0 auto;height:auto!important;z-index:80;pointer-events:none}
#kyc .kpo-f{animation:kpOf .34s cubic-bezier(.4,0,1,1) both}
#kyc .kpo-b{animation:kpOb .34s cubic-bezier(.4,0,1,1) both}
@keyframes kfl{from{opacity:.95}to{opacity:0}}
#kyc .kflash{position:absolute;inset:0;border-radius:18px;background:#fff;z-index:5;pointer-events:none;animation:kfl .5s ease-out both}
#kyc .kn .kfr.lk i{border-color:#12a15b;animation:none;filter:drop-shadow(0 0 6px rgba(18,161,91,.55))}
#kyc .kgo{position:relative;overflow:hidden}
@keyframes kcd{from{width:0}to{width:100%}}
#kyc .kgo.cd::after{content:"";position:absolute;left:0;bottom:0;height:4px;background:rgba(255,255,255,.8);animation:kcd 2.3s linear forwards}
#kyc .krep.busy .rc{background:#f3dbe7}
#kyc .krep.busy .ri.pn{background:#fff3f8;color:#7a3a58;animation:kri .35s calc(.1s + var(--n) * .08s) both}
#kyc .krep.busy .ri.pn i{background:#f3dbe7}
#kyc .krep.busy .kspin{display:block;width:16px;height:16px;border-width:2.5px;border-color:rgba(226,19,110,.25);border-top-color:#e2136e}
#kyc .krep.busy .ri.pn i .kspin{width:11px;height:11px;border-width:2px}

/* =====================================================================
   v2.36 — স্মুথ পেজ বদল, কিবোর্ডের সাথে বার, কোড যাচাই পেজ, আমার প্রোফাইল
   ===================================================================== */
/* ---- পেজ বদল: আগের পেজ ঘোস্ট হয়ে সরে যায়, নতুন পেজ নরমভাবে আসে ---- */
@keyframes vtIf{from{opacity:0;transform:translate3d(9%,0,0)}to{opacity:1;transform:none}}
@keyframes vtIb{from{opacity:0;transform:translate3d(-9%,0,0)}to{opacity:1;transform:none}}
@keyframes vtIn{from{opacity:0;transform:scale(.985)}to{opacity:1;transform:none}}
@keyframes vtOf{from{opacity:1;transform:none}to{opacity:0;transform:translate3d(-9%,0,0)}}
@keyframes vtOb{from{opacity:1;transform:none}to{opacity:0;transform:translate3d(9%,0,0)}}
@keyframes vtOn{from{opacity:1;transform:none}to{opacity:0;transform:scale(1.012)}}
.fl.vtf,.pg.vtf,.pg.in.vtf{animation:vtIf .46s var(--ease) backwards}
.fl.vtb,.pg.vtb,.pg.in.vtb{animation:vtIb .46s var(--ease) backwards}
.fl.vtn,.pg.vtn,.pg.in.vtn{animation:vtIn .42s var(--ease) backwards}
.vgh{position:fixed;top:0;bottom:0;z-index:4;max-width:430px;overflow:hidden;pointer-events:none;will-change:transform,opacity}
.vgh *{animation:none!important;transition:none!important}
.vgh.vgf{animation:vtOf .3s cubic-bezier(.4,0,.8,.6) both!important}
.vgh.vgb{animation:vtOb .3s cubic-bezier(.4,0,.8,.6) both!important}
.vgh.vgn{animation:vtOn .3s ease-in both!important}
/* হোম/ইনবক্স/প্রোফাইলের ভেতরের জিনিস: স্প্রিং লাফ নয়, নরম ফেড-আপ */
.pg.in .it,.pg.in .tri div,.pg.in .fc{animation-name:fup}
.pg.in .tr,.pg.in .mr,.pg.in .nf{animation-name:fup}
.pg.in{animation-duration:.01s}
.pg.vtf.in,.pg.vtb.in{animation-duration:.46s}
/* নিচের বার: ঢোকার অ্যানিমেশন শেষে আর ট্রান্সফর্ম আটকে রাখে না (কিবোর্ডের সাথে গড়ানো যেন কাজ করে) */
.nbar{animation:fup .45s var(--ease) .2s backwards}
.nbar.ld{animation:none}

/* ---- PIN কিপ্যাড: নিচ থেকে নরমভাবে ওঠে ও নামে ---- */
#kpad{transition:transform .36s var(--ease)!important;will-change:transform}
#kpad:not(.show){transition-duration:.26s!important;transition-timing-function:cubic-bezier(.4,0,1,1)!important}
/* কিপ্যাড ওঠার সময় নিচের বাটন-বার হঠাৎ মুছে না গিয়ে গুটিয়ে যায় */
.pgx .pfoot{max-height:160px;overflow:hidden;transition:max-height .32s var(--ease),padding .32s var(--ease),opacity .22s ease,box-shadow .3s}
html.pinkb .pgx .pfoot{display:block;max-height:0;padding-top:0;padding-bottom:0;opacity:0;box-shadow:none;pointer-events:none}
.pgx .pbody{transition:padding-bottom .32s var(--ease)}
/* নতুন অ্যাকাউন্ট পাতা: কিপ্যাডের ওপরে PIN ঘর সবসময় দেখা যায় */
.regv .fbody{transition:padding-bottom .34s var(--ease)}
html.rkp .regv .fbody{padding-bottom:calc(var(--kph,300px) + 26px)}
html.rkp .regv .lb2{opacity:0;pointer-events:none}
.regv .lb2{transition:opacity .2s ease,background-color .2s}

/* ---- কোড যাচাই পাতা (বিকাশের মতো সাজানো) ---- */
.otpv .fbody{display:flex;flex-direction:column;padding-bottom:28px}
.otpv .fbody h2{font-size:22px;font-weight:400;line-height:1.38;margin-top:2px}
.otpv .fbody h2 b{font-weight:700;color:#2b2530}
.otrow{display:flex;align-items:center;justify-content:space-between;margin-top:26px;min-height:30px}
.otl{font-size:13.5px;color:#8a8490;font-weight:500}
.otrow .otprs{flex:none;display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 10px;margin-right:-10px;border:0;background:transparent;color:var(--lp);font-size:13px;font-weight:700;border-radius:15px;white-space:nowrap;transition:background-color .2s,transform .18s var(--ease)}
.otrow .otprs:disabled{color:var(--lp);opacity:1}
.otrow .otprs .otrg{width:16px;height:16px}
.otrow .otprs.rdy{border:0;background:#fde7f1;color:var(--lp);animation:otrdy .5s var(--spring) both}
.otrow .otprs:active{transform:scale(.95)}
.otpv .otpb{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px;margin:10px 0 0}
.otpv .otpb i{flex:none;width:auto;max-width:none;height:50px;border-radius:12px;border:1.5px solid #e9dfe6;background:#fff;font-size:21px;font-weight:600;box-shadow:none}
.otpv .otpb i.f{background:#fff7fb;border-color:#f3b9d3}
.otpv .otpb i.a{border-color:var(--lp);background:#fff;box-shadow:0 0 0 3px rgba(226,19,110,.10);transform:none}
.otpv .otpact{display:flex;align-items:center;gap:12px;margin-top:14px;min-height:38px}
.otpv .otpact .otpp{flex:none;height:36px;padding:0 14px;margin:0;border-radius:18px;display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:700;border:1.5px solid #f3b9d3;background:#fff7fb;color:var(--lp);white-space:nowrap}
.otpv .otpact .otpp svg{width:16px;height:16px}
.otpv .otpact .otpp.tap{animation:otptap .4s var(--ease)}
@keyframes otptap{0%{transform:scale(.92)}60%{transform:scale(1.04)}100%{transform:scale(1)}}
.otpv .otpact .otst{margin:0;min-height:0;flex:1;min-width:0;font-size:13.5px}
.otsent{margin-top:18px;font-size:14px;line-height:1.6;color:#4a444d}
.otsent b{font-weight:700;color:#2b2530;white-space:nowrap}
.otchg{color:var(--lp);font-weight:600;cursor:pointer;white-space:nowrap}
.otwarn{position:relative;overflow:hidden;margin-top:22px;border-radius:18px;padding:16px 16px 16px 14px;display:flex;align-items:center;gap:14px;background:linear-gradient(120deg,#e2136e,#b80c58);color:#fff;box-shadow:0 12px 28px rgba(226,19,110,.26)}
.otwarn:before{content:"";position:absolute;right:-34px;top:-40px;width:130px;height:130px;border-radius:50%;background:rgba(255,255,255,.10)}
.otwarn:after{content:"";position:absolute;right:30px;bottom:-50px;width:90px;height:90px;border-radius:50%;background:rgba(255,255,255,.07)}
.otwarn svg{width:56px;height:56px;flex:none;position:relative;z-index:1;animation:otsh 2.4s ease-in-out infinite}
.otwarn .ws{fill:#fff}.otwarn .wl{fill:none;stroke:#e2136e;stroke-width:6;stroke-linecap:round}.otwarn .wd{fill:#e2136e}
.otwarn div{position:relative;z-index:1;min-width:0}
.otwarn b{display:block;font-size:16px;line-height:1.38;font-weight:700;color:#fff}
.otwarn span{display:block;margin-top:5px;font-size:12px;line-height:1.45;color:rgba(255,255,255,.9)}
@keyframes otsh{0%,100%{transform:scale(1)}50%{transform:scale(1.07)}}

/* ---- আমার প্রোফাইল ---- */
.prof{padding:18px 16px;gap:16px;position:relative;overflow:hidden;border-radius:20px}
.prof:before{content:"";position:absolute;right:-46px;top:-56px;width:170px;height:170px;border-radius:50%;background:radial-gradient(circle,rgba(226,19,110,.13),transparent 70%);pointer-events:none}
.prof .pavw .big{width:68px;height:68px;font-size:28px;box-shadow:0 0 0 3px #fff,0 0 0 5px rgba(226,19,110,.35),0 10px 22px rgba(226,19,110,.26)}
.pi2{position:relative}
.pi2 h3{font-size:18px;font-weight:700;color:#2a1722}
.pi2 p{font-size:13.5px;color:#7a727c;letter-spacing:.2px;margin-top:3px}
.vfy{display:inline-flex;align-items:center;gap:4px;margin-top:8px;padding:3px 11px 3px 7px;border-radius:12px;background:#e6f7ee;color:#0f8a52;font-style:normal;font-size:11.5px;font-weight:700}
.vfy svg{width:13px;height:13px;fill:none;stroke:#0f8a52;stroke-width:3}
.msec{padding:2px 0 6px}
.msec h4{padding:16px 18px 6px;font-size:11.5px;font-weight:700;letter-spacing:.5px;color:#a38c9c}
.mr{position:relative;min-height:58px;gap:14px;padding:0 16px 0 16px;font-size:15px;font-weight:600;color:#2f2a32}
.mr+.mr:before{content:"";position:absolute;left:68px;right:16px;top:0;height:1px;background:#f4ecf1}
.mic{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;flex:none;background:#fde7f1;color:#e2136e;transition:transform .2s var(--ease)}
.mic svg.i{width:20px;height:20px;color:inherit}
.mr:active .mic{transform:scale(.9)}
.mic.t1{background:#fde7f1;color:#e2136e}.mic.t2{background:#efeaff;color:#6a4df0}.mic.t3{background:#e4f1ff;color:#1f7ae0}.mic.t4{background:#fff0de;color:#e5820a}
.mic.t5{background:#e4f6ec;color:#12a15b}.mic.t6{background:#e0f6f6;color:#0e9aa7}.mic.t7{background:#e4f6ec;color:#12a15b}.mic.t8{background:#ffe8ec;color:#e5324b}
.chv{width:18px;height:18px;flex:none;fill:none;stroke:#cbbac4;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.mr small{font-weight:600}
.mr .lgp{padding:3px 11px;border-radius:10px;background:#f7eef3;color:#8a3a62;font-weight:700;margin-right:2px}
.mr .kok{color:#0f8a52;background:#e6f7ee;padding:3px 10px;border-radius:10px;font-weight:700}
.mr.out span{color:#e5324b;font-weight:700}
.mr.out:before{display:block}
@media(prefers-reduced-motion:reduce){.fl.vtf,.fl.vtb,.fl.vtn,.pg.vtf,.pg.vtb,.pg.vtn{animation-duration:.01s}.vgh{display:none}}

/* =====================================================================
   v2.37 — কোড পেজ, সতর্কতা ব্যানার, স্ট্যাটাস বারের সাথে মেলানো পেজ, KYC বাংলা লেআউট, কাঁপা কমানো
   ===================================================================== */
/* ---- কাঁপা/লাফানো কমানো ---- */
html{overflow-anchor:none;scroll-behavior:auto}
#app,#kyc{-webkit-backface-visibility:hidden;backface-visibility:hidden;overflow-anchor:none}
.nbar,.pfoot,.bknx,.kbtm{-webkit-backface-visibility:hidden;backface-visibility:hidden}
/* নিচের বার পেজ বদলে/আবার আঁকলে নিচ থেকে লাফিয়ে ওঠে না, শুধু নরমে ফুটে ওঠে */
@keyframes nbfade37{from{opacity:0}to{opacity:1}}
.v237 .nbar,.v237 .pfoot,.v237 .bknx,.v237 .kbtm{animation:nbfade37 .28s ease both!important}
.v237 .lpanel{animation:nbfade37 .4s ease .1s both!important}

/* ---- স্ট্যাটাস বারের ঠিক নিচে পেজের ওপরের রং একই (সাদা ফালি দেখা যায় না) ---- */
:root{--sbc:#fdeef4}
body:before{background:linear-gradient(180deg,#fdeef4 0,#fdeef4 4px,rgba(253,238,244,0) 140px),radial-gradient(70vmax 46vmax at 96% -6%,rgba(226,19,110,.24),transparent 62%),radial-gradient(54vmax 44vmax at -14% 40%,rgba(150,95,235,.14),transparent 62%),radial-gradient(56vmax 40vmax at 104% 86%,rgba(255,140,175,.22),transparent 62%),linear-gradient(180deg,#fcedf4,#f6eff6 46%,#f5f0f5)!important}

/* ---- কোড যাচাই পেজ ---- */
.otpv .otpb{width:100%;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px}
.otpv .otpb i,.otpv .otpb.ok i,.otpv .otpb.chk i,.otpv .otpb i.a,.otpv .otpb i.pp{width:auto!important;max-width:none!important;height:52px;transform:none!important;animation:none!important}
.otpv .otpb.ok i{border-color:#2cc47c;background:#ecfaf3;color:#0f8a52;box-shadow:none;transition:background-color .35s,border-color .35s,color .35s}
.otpv .otpb.chk i{border-color:#f3b9d3;background:#fff7fb}
/* "যাচাই হয়েছে" বামে, "কোড পেস্ট করুন" ডানে, দুটোই এক লাইনে ঠিক মাঝ বরাবর */
.otpv .otpact{display:flex;flex-direction:row;align-items:center;justify-content:space-between;gap:10px;margin-top:14px;min-height:42px}
.otpv .otpact .otst{order:0;flex:1 1 auto;min-width:0;margin:0;display:flex;align-items:center;justify-content:flex-start;gap:7px;text-align:left;white-space:nowrap;font-size:14px;line-height:1.2}
.otpv .otpact .otst svg{width:19px;height:19px;flex:none}
.otpv .otpact .otpp{order:1;flex:none;margin:0 0 0 auto;height:40px;padding:0 16px;display:inline-flex;align-items:center;justify-content:center;gap:7px;text-align:center;border:1.5px solid #f3b9d3;background:#fff7fb;color:var(--lp);border-radius:20px;font-size:13.5px;font-weight:700;line-height:1;box-shadow:0 4px 12px rgba(226,19,110,.10)}
.otpv .otpact .otpp svg{display:block;flex:none;width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;opacity:1}
.otpv .otpact .otpp span{display:block;line-height:1;padding:0;margin:0;transform:none}
/* সতর্কতা ব্যানার: ছোট, দুই লাইনের শিরোনাম, আরও সুন্দর */
.otpv .otwarn{margin-top:20px;padding:14px 15px 14px 14px;gap:13px;border-radius:20px;background:linear-gradient(125deg,#ee2b7d 0%,#d0126a 45%,#a80b52 100%);box-shadow:0 12px 26px rgba(196,15,94,.28),inset 0 1px 0 rgba(255,255,255,.28),inset 0 0 0 1px rgba(255,255,255,.08)}
.otpv .otwarn svg{box-sizing:border-box;width:46px;height:46px;padding:8px;border-radius:15px;background:rgba(255,255,255,.17);box-shadow:inset 0 0 0 1px rgba(255,255,255,.22)}
.otpv .otwarn b{font-size:15px;line-height:1.3;font-weight:700;letter-spacing:0}
.otpv .otwarn span{margin-top:4px;font-size:11.5px;line-height:1.4;color:rgba(255,255,255,.92)}

/* ---- KYC পাতা: লোগোর নিচে শিরোনাম, ফর্মের লেখা সমান ---- */
#kyc .klg strong{display:block;margin-top:3px;color:#2a1020;font-size:17px;font-weight:700;letter-spacing:.1px;line-height:1.3;text-align:center;white-space:nowrap}
#kyc .kcam.kn .ktp b{display:none}
#kyc .kdb{font-size:16px;font-weight:600;line-height:1.35}
#kyc .kdb span{font-size:16px;font-weight:600;line-height:1.35;letter-spacing:0;color:#2a262b}
#kyc .kfb input,#kyc .kfb textarea{font-size:16px;font-weight:600}
#kyc .krep.busy .rg{grid-template-columns:1fr 1fr}

/* =====================================================================
   v2.40 — নেটিভ অ্যাপের মতো ভারি ও স্মুথ অনুভূতি
   (এই ব্লক সবার শেষে, তাই আগের নিয়মের ওপর বসে)
   ===================================================================== */
:root{--nat:cubic-bezier(.32,.72,0,1);--natout:cubic-bezier(.4,0,.6,1)}

/* ১) কাচের মতো ঝাপসা (blur) আগের মতোই থাকে — এখানে কিছু বদলানো হয়নি */

/* ২) স্পর্শের অনুভূতি: চাপলে ছোট হয়, ছাড়লে নরমভাবে ফেরে (স্ক্রল শুরু করলে ঝিলিক দেয় না) */
button:not(.hold):not(.lgh):not(.kpb):not(.fpb):not(:disabled),.it,.tr,.mr,.fc,.bn,.v3t,.qrb{transition:transform .26s var(--nat),background-color .2s ease,opacity .2s ease;-webkit-tap-highlight-color:transparent}
button:not(.hold):not(.lgh):not(.kpb):not(.fpb):not(:disabled):active,.it:active,.tr:active,.mr:active,.fc:active,.bn:active,.v3t:active{transform:scale(.965);transition:transform .11s ease-out .045s,background-color .11s ease}
nav button:active{transform:scale(.9)}
.btn:active,#kyc .kbtn:active{transform:scale(.975)}

/* ৩) পেজ খোলা/বন্ধ: iOS-এর মতো ভারি স্লাইড, নিচের পেজ সামান্য সরে যায় (parallax) */
.sh.pgx .box{animation:pgSlideIn .42s var(--nat) both!important;will-change:transform;box-shadow:-14px 0 34px rgba(60,0,30,.16)}
.sh.pgx.out .box{animation:pgSlideOut .32s var(--natout) both!important}
.sh.pgx.re .box{animation:none!important}
.sh.dlg .box{animation:up .38s var(--nat) both;will-change:transform}
.sh.dlg.out .box{animation:down .28s var(--natout) both}
.sh{animation-duration:.22s}
.sh.out{animation-duration:.26s}
#app{transition:transform .42s var(--nat),filter .42s var(--nat)}
body:has(#sheet .sh.pgx:not(.out)) #app{transform:translate3d(-22%,0,0);filter:brightness(.9)}
body:has(#sheet .sh.pgx.out) #app{transition-duration:.32s;transition-timing-function:var(--natout)}

/* ৪) ট্যাব বদল: নরম ফেড + সামান্য ওঠা, কাটাকাটি নেই */
.pg.in{animation:fp40in .3s var(--nat) both!important}
@keyframes fp40in{from{opacity:0;transform:translate3d(0,10px,0)}to{opacity:1;transform:none}}

/* ৫) ঘর ফোকাস/রং বদল নরম */
input,textarea{transition:border-color .2s ease,box-shadow .2s ease,background-color .2s ease}

/* ৬) ওয়েবের মতো আচরণ বন্ধ: ছবি টানা, লেখা বাছাই, টেনে রিফ্রেশ/ওভারস্ক্রল, ঝিলিক */
img,svg{-webkit-user-drag:none;user-drag:none}
html,body,#app,.pbody,#kyc .kbody{overscroll-behavior:none;-webkit-overflow-scrolling:touch}
#app,.pbody,#kyc .kbody{scroll-behavior:auto}
a{-webkit-touch-callout:none}
*{-webkit-font-smoothing:antialiased}

/* ৭) GPU-তে ভারি অংশ আলাদা স্তরে (শুধু যেগুলো সত্যিই নড়ে) */
nav,#pinbar,#kbar,#kpad{transform-style:flat;backface-visibility:hidden}

/* ৮) অ্যাপ ব্যাকগ্রাউন্ডে গেলে অনন্ত অ্যানিমেশন থেমে থাকে (ব্যাটারি + ফিরে এলে কাটে না) */
html.fpbg *,html.fpbg *:before,html.fpbg *:after{animation-play-state:paused!important}

/* =====================================================================
   v2.42 — কাচের (glass) ভাব সব জায়গায়: নিচের বার, হেডার, শিট, ডায়ালগ, কার্ড, কিপ্যাড, নোটিশ, KYC কার্ড
   (আগের "*{backdrop-filter:none!important}" ঠেলে দিতে এখানে !important লাগে)
   ===================================================================== */
:root{--gblur:blur(22px) saturate(1.7);--gblur2:blur(30px) saturate(1.9)}

/* ১) পেজের হেডার (শিট-পেজ): পেজের ওপর ভাসে, নিচ দিয়ে লেখা স্ক্রল করলে ঝাপসা দেখা যায় */
.pgx .box{position:relative}
.pgx .ph{position:absolute;top:0;left:0;right:0;z-index:6;background:linear-gradient(180deg,rgba(226,19,110,.84),rgba(238,56,138,.76))!important;-webkit-backdrop-filter:var(--gblur)!important;backdrop-filter:var(--gblur)!important;border-bottom:1px solid rgba(255,255,255,.28);box-shadow:0 6px 22px rgba(190,20,100,.16)}
.pgx .ph~.pbody{padding-top:calc(52px + var(--st,0px))!important}
.tbar{background:linear-gradient(180deg,rgba(226,19,110,.86),rgba(238,56,138,.78))!important;-webkit-backdrop-filter:var(--gblur)!important;backdrop-filter:var(--gblur)!important}

/* ২) নিচের বার (আগের কাচ আবার নিশ্চিত) ও কিপ্যাড */
nav,nav.fx{-webkit-backdrop-filter:var(--gblur)!important;backdrop-filter:var(--gblur)!important}
#kpad{background:rgba(244,244,246,.8)!important;-webkit-backdrop-filter:var(--gblur2)!important;backdrop-filter:var(--gblur2)!important}
.pfoot:not(:has(.v3bar)):not(:has(.bknx)){background:rgba(255,255,255,.8)!important;-webkit-backdrop-filter:var(--gblur)!important;backdrop-filter:var(--gblur)!important}

/* ৩) শিটের পেছনের পর্দা ও ডায়ালগ বক্স */
.sh:not(.pgx):not(.scanx){background:rgba(48,8,30,.32)!important;-webkit-backdrop-filter:blur(10px)!important;backdrop-filter:blur(10px)!important}
.sh.dlg .box{background:rgba(255,255,255,.8)!important;-webkit-backdrop-filter:var(--gblur2)!important;backdrop-filter:var(--gblur2)!important;border:1px solid rgba(255,255,255,.75);border-bottom:0;box-shadow:0 -10px 40px rgba(60,0,30,.18)}

/* ৪) কার্ড/সেকশন: আধা-স্বচ্ছ সাদা + ঝাপসা। পেজের পেছনে হালকা রঙিন আভা, যেন কাচের ভেতর দিয়ে দেখা যায় */
.wsheet,.sec,.pcard,.msec,.prof,.balc,.nt,.pg>.seg,.pg>.srch,.pg>.note,.fc,.bp{background:rgba(255,255,255,.66)!important;-webkit-backdrop-filter:var(--gblur)!important;backdrop-filter:var(--gblur)!important;border:1px solid rgba(255,255,255,.8);box-shadow:0 8px 26px rgba(170,20,95,.09),inset 0 1px 0 rgba(255,255,255,.9)}
.pg{background-image:radial-gradient(280px 280px at 100% 34%,rgba(226,19,110,.11),transparent 72%),radial-gradient(320px 320px at 0% 70%,rgba(110,80,255,.08),transparent 72%),radial-gradient(260px 260px at 90% 96%,rgba(255,170,60,.08),transparent 72%)}

/* ৫) টোস্ট/অফলাইন বার, ব্যানারের আইকন, লগইনের প্যানেল, সেগমেন্ট ট্যাব */
.toast,#offbar{background:rgba(42,22,32,.78)!important;-webkit-backdrop-filter:blur(16px) saturate(1.5)!important;backdrop-filter:blur(16px) saturate(1.5)!important}
.bn svg.bv{-webkit-backdrop-filter:blur(10px)!important;backdrop-filter:blur(10px)!important}
.lpanel{-webkit-backdrop-filter:blur(16px)!important;backdrop-filter:blur(16px)!important}
.sctabs{-webkit-backdrop-filter:blur(10px)!important;backdrop-filter:blur(10px)!important}

/* ৬) KYC: কার্ড, তালিকা, ফলাফল বক্স, স্ক্যানের চিপ */
#kyc .kcard,#kyc .kf{background:rgba(255,255,255,.72)!important;-webkit-backdrop-filter:var(--gblur)!important;backdrop-filter:var(--gblur)!important;border:1px solid rgba(255,255,255,.8)}
#kyc .krep{background:rgba(255,255,255,.84)!important;-webkit-backdrop-filter:var(--gblur2)!important;backdrop-filter:var(--gblur2)!important;border:1px solid rgba(255,255,255,.8)}
#kyc .kchk{-webkit-backdrop-filter:blur(12px)!important;backdrop-filter:blur(12px)!important;background:rgba(14,4,10,.62)}
#kyc .kchk.gd{background:rgba(18,161,91,.9)}

/* =====================================================================
   v2.44 — আইডি কার্ড ছবি তোলার পর ফলাফল পাতা: শুধু ঘরের মাপ ও জায়গা (লেখা বদলায়নি)
   ১) ফলাফল বক্স ও দুই বাটন চিকন ও ছোট  ২) নিচের বাড়তি ফাঁকা কমিয়ে সব নিচে নামানো
   ৩) কার্ডের ছবির ঘর আর ফলাফল বক্সের মাঝে ফাঁক
   ===================================================================== */
/* ছবির ঘরের ঠিক নিচ থেকে নিচ পর্যন্ত জায়গা; ভেতরের জিনিস নিচে বসে, ছবির ঘরের সাথে অন্তত ২২px ফাঁক থাকে */
#kyc .kcam.kn .kwr.pv~.kbt{top:calc(50% + min(88vw,380px) / 3.172 + 22px);padding:0 16px calc(14px + var(--sb,0px));display:flex;flex-direction:column;justify-content:flex-end;background:none}
#kyc .kcam.kn .kwr.pv~.kbt .knc{display:none}

/* ফলাফল বক্স: ছোট ও চিকন */
#kyc .kcam.kn .krep{border-radius:16px;padding:8px 9px 7px;margin:0 0 9px;box-shadow:0 6px 20px rgba(170,20,95,.16)}
#kyc .kcam.kn .krep .rh{gap:8px;margin-bottom:6px}
#kyc .kcam.kn .krep .rc{width:28px;height:28px;font-size:15px}
#kyc .kcam.kn .krep .rc svg{width:15px;height:15px}
#kyc .kcam.kn .krep .rh b{font-size:14px;line-height:1.15}
#kyc .kcam.kn .krep .rh small{font-size:11px;margin-top:1px}
#kyc .kcam.kn .krep .rg{gap:4px}
#kyc .kcam.kn .krep .ri{gap:6px;padding:4px 7px;border-radius:9px;font-size:11.5px}
#kyc .kcam.kn .krep .ri i{width:16px;height:16px;font-size:10px}
#kyc .kcam.kn .krep .ri i svg{width:10px;height:10px}

/* "আবার তুলুন" ও "ঠিক আছে" বাটন: চিকন ও ছোট */
#kyc .kcam.kn .krow{gap:10px}
#kyc .kcam.kn .kgh,#kyc .kcam.kn .kgo{height:40px;border-radius:12px;font-size:14px}
#kyc .kcam.kn .kgo{box-shadow:0 5px 12px rgba(226,19,110,.28)}

/* v2.45 — আইডি কার্ডের ফ্রন্ট/ব্যাক পেজ: শিরোনাম (লেখা) লোগোর থেকে আরেকটু নিচে; শুধু জায়গা বদল, লোগো যেখানে ছিল সেখানেই */
#kyc .kcam.kn:has(.kwr:not(.ov)) .klg strong{margin-top:16px}

/* =====================================================================
   v2.46 — লগইন / রেজিস্ট্রেশন পেজ (শুধু এই পেজগুলো): বিকাশের মতো
   ১) ঘেরা বক্স/আলাদা ঘর নেই, শুধু নিচে একটা লাইন
   ২) "পরবর্তী" বার দুই পাশে ফাঁকা ছাড়া পুরো চওড়া, নিচে বসা; কিবোর্ড উঠলে কিবোর্ডের মাথায় লেগে থাকে
   ৩) PIN পেজে সাদা অংশ পুরো চওড়া (দুই পাশে গোলাপি ফাঁক নেই)
   ===================================================================== */

/* ---- নম্বর পেজ + নতুন অ্যাকাউন্ট পেজ: সমতল ঘর ---- */
.fl.light .pfield,.regv .pfield{border:0!important;border-bottom:1.5px solid #cfc8d2!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;padding:0!important;gap:12px}
.fl.light .pfield:focus-within,.regv .pfield:focus-within{border-bottom-color:var(--lp)!important;box-shadow:none!important}
.regv .pfield.okf{border-bottom-color:#2cc47c!important;box-shadow:none!important}
.regv .pfield.badf{border-bottom-color:#ef5a73!important;box-shadow:none!important}
.fl.light .pfield.ro{background:transparent!important}
.fl.light .pfield.ro input{color:#6f6973}
.fl.light .cfield{border:0!important;border-radius:6px!important;background:#efecef!important;height:50px!important;box-shadow:none!important}

/* ---- "পরবর্তী" বার (নম্বর পেজ): পুরো চওড়া, নিচে, ধূসর → নম্বর পুরো হলে গোলাপি ---- */
.fl.light .nbar.bkbar{position:sticky;bottom:0;flex:none;width:100%;height:calc(52px + var(--sb));margin:0;padding:0 20px var(--sb);border-radius:0;box-shadow:none;background:#9e9a9f;color:#fff;font-size:16px;font-weight:700;animation:nbfade37 .3s ease both!important;transition:background-color .2s}
.fl.light:focus-within .nbar.bkbar:not(.on){background:#9e9a9f}
.fl.light .nbar.bkbar.on,.fl.light:focus-within .nbar.bkbar.on{background:linear-gradient(90deg,#e2136e,#f0549a)}
.fl.light .nbar.bkbar svg{width:26px;height:26px;stroke-width:2.2}
.fl.light .nbar.bkbar.ld{background:var(--lp,#e2136e)!important}

/* ---- PIN পেজ: সাদা অংশ পুরো চওড়া ও নিচ পর্যন্ত, ঘর সমতল, নিচের বাটন বার ---- */
.fl.pinp .psheet.bkl{flex:1 1 auto!important;margin:0!important;border-radius:22px 22px 0 0!important;box-shadow:none!important;padding:20px 22px calc(16px + var(--sb))!important}
html.pinkb .fl.pinp .psheet.bkl{padding-bottom:16px!important}
.fl.pinp .bkn{border:0!important;border-bottom:1.5px solid #cfc8d2!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;padding:2px 0 10px!important;font-size:18px}
.fl.pinp .bkp{border:0!important;border-bottom:1.5px solid #cfc8d2!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;padding:0!important;height:50px;gap:8px}
.fl.pinp .bkp:focus-within{border-bottom-color:var(--lp,#e2136e)!important;box-shadow:none!important}
.fl.pinp .bkp input.pinin{text-align:left!important;height:48px!important;padding:0!important}
.fl.pinp .bkp input.pinin::placeholder{text-align:left!important}
.fl.pinp .bkfp{border:0!important;background:none!important;border-radius:50%;width:44px;height:44px;box-shadow:none!important}
.fl.pinp .bkfp:active{background:#e2136e14!important}
.fl.pinp .bkfp svg{width:30px;height:30px}
.fl.pinp .psheet .pgbtn{align-self:stretch;width:auto!important;margin:auto -22px calc(-16px - var(--sb)) -22px!important;height:calc(52px + var(--sb));padding:0 0 var(--sb);border-radius:0!important;box-shadow:none!important}

/* =====================================================================
   v2.47 — স্মুথ পেজ বদল, ঝিলিক/রং লাফ বন্ধ, লগইন বিকাশের ধাঁচে
   ===================================================================== */
/* ১) পেজ খুলতে/বন্ধ হতে #app নড়ে না, ফিল্টার নেই (আগে নিচের বার/ফিক্সড অংশ লাফাত আর রং বদলাত) */
#app{transition:none!important}
body:has(#sheet .sh.pgx:not(.out)) #app,body:has(#sheet .sh.pgx.out) #app{transform:none!important;filter:none!important}
/* ২) পেজ নিজে স্লাইড করে ওঠে, পেছনে ঝাপসা/আধা-স্বচ্ছ স্তর নেই, দুই পেজ মিশে দেখা যায় না */
.sh.pgx,.sh.pgx.out{background:transparent!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important;animation:none!important}
.sh.pgx .box{animation:pgSlideIn .3s cubic-bezier(.22,.9,.3,1) both!important;box-shadow:-8px 0 24px rgba(60,0,30,.12);will-change:transform;backface-visibility:hidden}
.sh.pgx.out .box{animation:pgSlideOut .24s cubic-bezier(.4,0,.8,.6) both!important}
.sh.pgx.re .box,.sh.pgx.re.out .box{animation:none!important}
.sh.pgx.re.out .box{animation:pgSlideOut .24s cubic-bezier(.4,0,.8,.6) both!important}
/* ৩) হেডারের ঝাপসা (backdrop blur) বন্ধ: স্লাইডের সময় ঝিলিক কাটত */
.pgx .ph,.tbar{-webkit-backdrop-filter:none!important;backdrop-filter:none!important;background:linear-gradient(180deg,#e2136e,#ec2f84)!important}
/* ৪) কিবোর্ড নামলে নিচে গাঢ় গোলাপি ব্লক নয়: পেছনের রং পেজের রঙের সাথে মেলে */
html:has(#app.au),html:has(#app.au) body{background:#f5f0f5!important}
html:has(.fl.pinp),html:has(.fl.pinp) body{background:#fff!important}
html:has(.fl.light),html:has(.fl.light) body{background:#f7f5f7!important}
/* ৫) লগইনের সাদা অংশে হালকা লোগো প্যাটার্ন, পেছনে স্থির */
.fl.pinp .psheet.bkl{background:linear-gradient(rgba(255,255,255,.93),rgba(255,255,255,.93)),url(/icons/logo-pink.png) 0 0/56px 56px space fixed,#fff!important}
.fl.light{background:linear-gradient(rgba(247,245,247,.92),rgba(247,245,247,.92)),url(/icons/logo-pink.png) 0 0/56px 56px space fixed,#f7f5f7!important}
/* ৬) ফিঙ্গারপ্রিন্ট আইকন: বিকাশের মতো চার কোণা ব্র্যাকেট ঘর */
.fl.pinp .bkfp{position:relative;width:46px!important;height:46px!important;border-radius:0!important;background:none!important}
.fl.pinp .bkfp::after{content:"";position:absolute;inset:0;border:2.5px solid #e2136e;border-radius:12px;pointer-events:none;
  -webkit-mask:linear-gradient(#000,#000) 0 0/13px 13px no-repeat,linear-gradient(#000,#000) 100% 0/13px 13px no-repeat,linear-gradient(#000,#000) 0 100%/13px 13px no-repeat,linear-gradient(#000,#000) 100% 100%/13px 13px no-repeat;
  mask:linear-gradient(#000,#000) 0 0/13px 13px no-repeat,linear-gradient(#000,#000) 100% 0/13px 13px no-repeat,linear-gradient(#000,#000) 0 100%/13px 13px no-repeat,linear-gradient(#000,#000) 100% 100%/13px 13px no-repeat}
.fl.pinp .bkfp svg{width:26px!important;height:26px!important}
.fl.pinp .bkfp:active{background:#e2136e14!important}

/* =====================================================================
   v2.48 — পেজ বদল স্থির (ঘোস্ট নেই), নিচের বার কাচের মতো (বিকাশের ধাঁচে), স্ক্যানারে ক্যামেরা দেখা, প্রিয় নাম্বার যোগ পেজ
   ===================================================================== */
/* ১) পেজ বদল: পুরনো পেজের কপি/ফেড নেই; ট্যাব বদল সরাসরি, ভেতরের জিনিস একটা একটা করে ওঠা নেই */
.vgh{display:none!important}
.pg.vtf,.pg.vtb,.pg.vtn,.pg.in,.pg.in.vtf,.pg.in.vtb,.pg.in.vtn{animation:none!important}
.pg.in>*,.pg.in :is(.it,.tr,.mr,.nf,.fc,.tri div,.wsheet,.sec,.msec,.prof,.balc,.nt,.pcard){animation:none!important}
.fl.vtf,.fl.vtb,.fl.vtn{animation:fp48fl .16s ease-out both!important}
@keyframes fp48fl{from{opacity:.4}to{opacity:1}}
/* ২) হাত দিলে পেজ নড়ে না: শুধু ওপর-নিচ স্ক্রল, পাশে টান নেই; বড় কার্ড চাপলে ছোট/বড় হয় না; পেজ খোলা থাকলে নিচের পেজ স্ক্রল হয় না */
#app,.sh .box,.pbody{touch-action:pan-y}
.pbody{overscroll-behavior:contain}
.bn:active,.fc:active,.sec:active,.pcard:active,.wsheet:active,.msec:active,.prof:active,.balc:active{transform:none!important}
html:has(.sh.pgx:not(.out)) #app{overflow:hidden}

/* ৩) নিচের বার: কাচের মতো (পেছনের রং ঝাপসা দেখা যায়), বিকাশের মতো পুরো-প্রস্থ বার */
nav,nav.fx{bottom:0!important;width:100%!important;max-width:430px!important;height:calc(60px + var(--sb,0px))!important;padding-bottom:var(--sb,0px)!important;border-radius:0!important;
  background:linear-gradient(180deg,rgba(255,255,255,.70),rgba(255,255,255,.58))!important;
  -webkit-backdrop-filter:blur(18px) saturate(1.9)!important;backdrop-filter:blur(18px) saturate(1.9)!important;
  border-top:1px solid rgba(255,255,255,.75)!important;box-shadow:0 -1px 0 rgba(150,20,90,.07),0 -10px 26px rgba(170,20,95,.08)!important}
nav .qrb .ni{margin-top:-14px;box-shadow:0 6px 16px rgba(226,19,110,.38),0 0 0 4px rgba(255,255,255,.55)!important}
/* কম শক্তির ফোন: কাচ নেই, সাধারণ সাদা বার ও সাধারণ কার্ড, ঝাপসা (blur) পুরো বন্ধ — স্বাভাবিক গতিতে চলে */
html.lowend *,html.lowend *:before,html.lowend *:after{-webkit-backdrop-filter:none!important;backdrop-filter:none!important}
html.lowend nav,html.lowend nav.fx{background:rgba(255,255,255,.97)!important;box-shadow:0 -1px 0 rgba(150,20,90,.10),0 -4px 14px rgba(170,20,95,.08)!important}
html.lowend .wsheet,html.lowend .sec,html.lowend .pcard,html.lowend .msec,html.lowend .prof,html.lowend .balc,html.lowend .nt,html.lowend .pg>.seg,html.lowend .pg>.srch,html.lowend .pg>.note,html.lowend .fc,html.lowend .bp{background:#fff!important;box-shadow:0 2px 10px rgba(170,20,95,.07)!important}
html.lowend .sh.dlg .box{background:#fff!important}
html.lowend .sh:not(.pgx):not(.scanx){background:rgba(48,8,30,.45)!important}
html.lowend nav button.on .ni{animation:none}
html.lowend .sh.pgx .box{box-shadow:none}

/* ৪) স্ক্যানার: ক্যামেরার ছবি দেখা যায় না কারণ পেছনের html/body গাঢ় রঙে আটকানো ছিল (v2.47) — স্ক্যান চলাকালীন স্বচ্ছ */
html.scanning,html.scanning body,html.scanning #app,html.scanning:has(#app.au),html.scanning:has(#app.au) body,html.scanning:has(#app),html.scanning:has(#app) body{background:transparent!important}

/* ৫) প্রিয় নাম্বার যোগ পেজ */
#fnum{width:100%;border:0;background:none;outline:0;font-size:22px;font-weight:700;letter-spacing:.6px;color:#2a1020;padding:6px 2px}
.v3fc{display:flex!important;flex-direction:row!important;align-items:center;gap:12px;width:100%;margin-top:18px;padding:12px 14px;background:#fff;border:1px solid #f0dbe6;border-radius:14px;text-align:left}
.v3fc span{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:#fdeaf3;color:#e2136e}
.v3fc span svg{width:22px;height:22px}
.v3fc b{font-size:15px;font-weight:700;color:#2a1020}
.v3fc b{flex:1;text-align:left}
.v3ac .v3nl{padding-left:16px}
#fnum{padding-left:16px;text-align:left}


/* =====================================================================
   v2.49 — লগইনের ব্যাকগ্রাউন্ডে ৩টি বড় স্থির লোগো (বামে, ডানে, নিচে), কিবোর্ড-বার, ফোনের ক্ষমতা অনুযায়ী অ্যানিমেশন
   ===================================================================== */
/* ১) পিন লগইনের সাদা অংশ: ছোট ছোট অনেক লোগোর বদলে ৩টি বড় লোগো, কোনোটা নড়ে না */
.fl.pinp .psheet.bkl{
  background:
    linear-gradient(rgba(255,255,255,.90),rgba(255,255,255,.90)),
    url(/icons/logo-pink.png) no-repeat left -78px top 34%/200px 200px,
    url(/icons/logo-pink.png) no-repeat right -84px top 52%/210px 210px,
    url(/icons/logo-pink.png) no-repeat left 50% bottom 6px/180px 180px,
    #fff!important;
  background-attachment:scroll!important;
}
/* ২) আমার QR ও স্ক্যান পাতা: ছোট ভাসমান লোগো বাদ, ৩টি বড় স্থির লোগো */
.qdeco .qwm{display:none!important}
.qdeco:before,.qdeco:after,.qdeco .qwm.q1,.qdeco .qwm.q2,.qdeco .qwm.q3{display:block!important}
.qdeco .qwm.q4,.qdeco .qwm.q5,.qdeco .qwm.q6{display:none!important}
.qdeco .qwm.q1,.qdeco .qwm.q2,.qdeco .qwm.q3{animation:none!important;width:150px!important;height:150px!important;opacity:.13!important}
.qdeco .qwm.q1{left:-52px!important;right:auto!important;top:auto!important;bottom:34%!important;transform:rotate(-14deg)!important}
.qdeco .qwm.q2{right:-52px!important;left:auto!important;top:auto!important;bottom:46%!important;transform:rotate(14deg)!important}
.qdeco .qwm.q3{left:calc(50% - 75px)!important;right:auto!important;top:auto!important;bottom:-34px!important;transform:rotate(6deg)!important}
.sh.scanx .scbg .wm{display:none!important;animation:none!important}
.sh.scanx .scbg .wm.w1,.sh.scanx .scbg .wm.w2,.sh.scanx .scbg .wm.w3{display:block!important;width:150px!important;height:150px!important;opacity:.22!important}
.sh.scanx .scbg .wm.w1{left:-54px!important;right:auto!important;top:36%!important;bottom:auto!important;transform:rotate(-14deg)!important}
.sh.scanx .scbg .wm.w2{right:-54px!important;left:auto!important;top:36%!important;bottom:auto!important;transform:rotate(14deg)!important}
.sh.scanx .scbg .wm.w3{left:calc(50% - 75px)!important;right:auto!important;top:auto!important;bottom:-36px!important;transform:rotate(6deg)!important}
.sh.scanx .scbg .wm.w4{display:none!important}

/* ৩) ফোনের কিবোর্ডের ওপরের বার: কিবোর্ড উঠে যাওয়ার পরই দেখায়, তাই ফাঁক থাকে না; নামলে সাথে সাথে সরে */

/* ৪) ফোনের ক্ষমতা অনুযায়ী অ্যানিমেশন: কম RAM → কম অ্যানিমেশন, ভালো ফোন → পুরো শক্তিতে মসৃণ */
html.lowend .orb,html.lowend .fps-orb,html.lowend .fpa-ry,html.lowend .fpa-rp,html.lowend .fpa-spin,
html.lowend .otwarn svg,html.lowend button.hold,html.lowend .qdeco .qwm{animation:none!important}
html.lowend .fpa-dt{animation:none!important}
html.lowend .fpa-ry{opacity:1!important}
html.lowend .fpa-ct{animation:none!important;opacity:1!important}
html.lowend .fpa-rg{animation:none!important;opacity:.55!important}
html.lowend .pg.in>*,html.lowend .pg.in .it,html.lowend .pg.in .tr,html.lowend .pg.in .mr,html.lowend .pg.in .tri div{animation:none!important}
html.lowend .fl.vtf,html.lowend .fl.vtb,html.lowend .fl.vtn,html.lowend .pg.vtf,html.lowend .pg.vtb,html.lowend .pg.vtn{animation-duration:.14s!important}
html.lowend #kpad{transition-duration:.14s!important}
html.lowend .sh .box{transition-duration:.18s!important}
html.lowend *{scroll-behavior:auto!important}
html.hiend #kpad{transition:transform .38s cubic-bezier(.22,1,.36,1)!important}
html.hiend .pg.in>*{animation-timing-function:cubic-bezier(.22,1,.36,1)}
html.hiend .fpa-spin{animation-duration:20s}

/* ফোন নম্বর / কোড / নতুন অ্যাকাউন্ট পেজ (.fl.light): ছোট ছোট অনেক লোগোর বদলে ৩টি বড় স্থির লোগো (বামে, ডানে, নিচে) */
.fl.light{
  background:
    linear-gradient(rgba(247,245,247,.90),rgba(247,245,247,.90)),
    url(/icons/logo-pink.png) no-repeat left -78px top 30%/200px 200px,
    url(/icons/logo-pink.png) no-repeat right -84px top 50%/210px 210px,
    url(/icons/logo-pink.png) no-repeat left 50% bottom 90px/180px 180px,
    #f7f5f7!important;
  background-attachment:scroll!important;
}
.fl.light::after{display:none!important}


/* =====================================================================
   v2.49 — এক স্থায়ী বার (পরবর্তী / এগিয়ে যান / পিন কনফার্ম) + বিকাশ স্টাইল ফিঙ্গারপ্রিন্ট আইকন
   ===================================================================== */
#kbar{position:fixed;left:0;right:0;bottom:0;z-index:96;box-sizing:border-box;height:calc(52px + var(--sb,0px));padding:0 20px var(--sb,0px);display:flex;align-items:center;justify-content:space-between;background:#9e9a9f;color:#fff;font-weight:700;font-size:16px;font-family:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent;-webkit-user-select:none;user-select:none;touch-action:manipulation;overflow:hidden;
  transform:translate3d(0,calc(100% + 6px),0);opacity:0;pointer-events:none;will-change:transform;
  transition:transform .26s cubic-bezier(.2,.8,.2,1),opacity .18s ease}
#kbar.show{transform:translate3d(0,calc(var(--dko,0px) * -1),0);opacity:1;pointer-events:auto}
#kbar.nt{transition:none!important}
#kbar::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,#e2136e,#f0549a);opacity:0;transition:opacity .22s ease}
#kbar.on::before{opacity:1}
#kbar>*{position:relative;z-index:1}
#kbar svg{width:26px;height:26px;fill:none;stroke:#fff;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;transition:transform .25s cubic-bezier(.2,.8,.2,1)}
#kbar.on svg{transform:translateX(3px)}
#kbar:active{filter:brightness(.94)}
#kbar.sk>*{animation:shake .4s}
#kbar.ld{pointer-events:none}
#kbar.ld>*{visibility:hidden}
#kbar.ld::after{content:"";position:absolute;left:50%;top:26px;width:32px;height:32px;margin:-16px 0 0 -16px;border-radius:50%;background:#fff url(../icons/logo-pink.png) center/26px no-repeat;animation:lgspin .9s linear infinite}
/* বারের সাথে থাকা পেজে নিজের নিচের বাটন লুকানো থাকে (জায়গা ধরে রাখে), বার নিজেই সেই জায়গায় বসে */
html .pgx.dkp .pfoot{display:block!important;visibility:hidden!important;height:calc(52px + var(--sb,0px))!important;min-height:0!important;max-height:none!important;padding:0!important;margin:0!important;overflow:hidden!important;opacity:1!important;box-shadow:none!important;pointer-events:none!important}
html.phkb .pgx.dkp .pbody{padding-bottom:calc(var(--kbo,0px) + 16px)}
html.pinkb .pgx.dkp .pbody{padding-bottom:calc(var(--kph,300px) + 16px)!important}
/* অ্যাপের কিপ্যাড: নিজের বার নেই, বারটা ওপরে আলাদা; ওঠা-নামা বারের সাথে একই গতিতে */
#kpad{border-radius:0;transition:transform .26s cubic-bezier(.2,.8,.2,1)!important}
html.lowend #kpad{transition:none!important}
html.lowend #kbar{transition:transform .18s ease-out,opacity .12s ease}
#kpad .kpb{display:none}
html.phkb .v3fab{display:none!important}

/* ---- ফিঙ্গারপ্রিন্ট আইকন: ফ্রেম + (মুখ ↔ আঙুলের ছাপ) ---- */
svg.fpx{overflow:visible;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round}
svg.fpx *{fill:none}
svg.fpx .fc path{stroke-width:2.3;transform-box:fill-box;transform-origin:center;animation:fpCor 6s cubic-bezier(.45,0,.2,1) infinite}
svg.fpx .c1{--dx:-1;--dy:-1}svg.fpx .c2{--dx:1;--dy:-1}svg.fpx .c3{--dx:1;--dy:1}svg.fpx .c4{--dx:-1;--dy:1}
svg.fpx .ff{stroke-width:2.2;transform-box:fill-box;transform-origin:center;animation:fpFace 6s cubic-bezier(.45,0,.2,1) infinite}
svg.fpx .fg{stroke-width:2.9;transform-box:fill-box;transform-origin:center;opacity:0;animation:fpPrint 6s cubic-bezier(.45,0,.2,1) infinite}
@keyframes fpCor{0%,38%{transform:none}45%{transform:translate(calc(var(--dx) * 2.8px),calc(var(--dy) * 2.8px))}53%,88%{transform:none}94%{transform:translate(calc(var(--dx) * 2.8px),calc(var(--dy) * 2.8px))}100%{transform:none}}
@keyframes fpFace{0%,38%{opacity:1;transform:none}44%{opacity:0;transform:rotate(-10deg) scale(.7)}48%,90%{opacity:0;transform:scale(.7)}96%{opacity:1;transform:rotate(8deg) scale(1.08)}100%{opacity:1;transform:none}}
@keyframes fpPrint{0%,40%{opacity:0;transform:scale(.55)}48%{opacity:1;transform:scale(1.14)}56%{opacity:1;transform:scale(.9)}62%,86%{opacity:1;transform:none}92%,100%{opacity:0;transform:scale(.55)}}
html.lowend svg.fpx *,.fpx.still *{animation:none!important}
html.lowend svg.fpx .ff,.fpx.still .ff{opacity:0}
html.lowend svg.fpx .fg,.fpx.still .fg{opacity:1}
@media (prefers-reduced-motion:reduce){svg.fpx *{animation:none!important}svg.fpx .ff{opacity:0}svg.fpx .fg{opacity:1}}
/* বিকাশের মতো: বাটনে বাক্স/বর্ডার নেই, শুধু বড় আইকন */
html .fpb,html .bk3 .bkpin .fpb,html .v3pr .fpb{width:50px!important;height:50px!important;border:0!important;background:transparent!important;box-shadow:none!important;border-radius:14px!important;color:#e2136e}
html .fpb:active,html .bkfp:active{background:#e2136e14!important}
html .fpb svg.fpx,html .bk3 .bkpin .fpb svg.fpx,html .v3pr .fpb svg.fpx{width:36px!important;height:36px!important}
html .bkfp svg.fpx{width:38px!important;height:38px!important;fill:none!important;stroke:#e2136e}
html .bkfp.on svg.fpx .fg{animation-duration:6s}
html .fl.pinp .bkfp,html .fl.pinp .bkfp.on{width:48px!important;height:48px!important;border:0!important;background:none!important;border-radius:14px!important;box-shadow:none!important;animation:none!important}
html .fl.pinp .bkfp::after,html .fl.pinp .bkfp::before{display:none!important;content:none!important}
html .fl.pinp .bkfp svg.fpx{width:38px!important;height:38px!important}
.v3fi{color:#e2136e}
.v3fi svg.fpx{width:30px;height:30px;stroke:#e2136e}
.ok .tick svg.fpx{width:46px;height:46px;stroke:#fff;fill:none}
.mic svg.fpx{width:24px;height:24px}
svg.fpx{stroke:currentColor}
.fpb svg.fpx,.v3pr .fpb svg.fpx,.bk3 .bkpin .fpb svg.fpx{stroke:#e2136e!important;fill:none!important}
.ok .tick svg.fpx{stroke:#fff!important}
/* কিপ্যাড উঠলে লগইন/রেজিস্ট্রেশনের নিজের নিচের বাটন লুকায় (ওপরের স্থায়ী বারটাই কাজ করে), তাই কিপ্যাডের নিচ দিয়ে ঝাপসা দেখা যায় না */
html.pinkb .fl .nbar,html.pinkb .fl .lpanel{opacity:0!important;pointer-events:none!important}


/* =====================================================================
   v2.50 — লগইনের নিচের বাটন বাদ, ট্রানজেকশন পেজে ক্রস + সেন্ড মানি, স্ক্যান পাতার লোগো,
   ঘরগুলো দুই পাশে লাগানো, ধাপে ধাপে স্মুথ পেজ বদল, সফল পেজের অ্যানিমেশন, চাপার আবরণ বন্ধ, লেখা বোল্ড
   ===================================================================== */

/* ১) লগইন (PIN) পেজ: নিচের "ঠিক আছে" বাটন নেই; কাজ কিবোর্ডের ওপরের "পিন কনফার্ম করুন" বার দিয়েই হয় (বাটনটা লুকানো, বার এর লেখা/অবস্থা ওখান থেকেই পড়ে) */
.fl.pinp .psheet .pgbtn{display:none!important}
.fl.pinp .psheet.bkl{padding-bottom:calc(18px + var(--sb))!important}

/* ২) ট্রানজেকশন পেজ: ডানে ওপরে ক্রস, নিচে "সেন্ড মানি" */
.trdd .box{position:relative}
.trdd .trx{position:absolute;top:12px;right:14px;z-index:3;width:38px;height:38px;border:0;border-radius:50%;background:#f3edf1;display:grid;place-items:center;padding:0;cursor:pointer;transition:transform .2s cubic-bezier(.2,.8,.2,1),background-color .2s}
.trdd .trx svg{width:20px;height:20px;fill:none;stroke:#5b4a54;stroke-width:2.6;stroke-linecap:round}
.trdd .trx:active{transform:scale(.88);background:#ead9e2}
.trdd .rbt .btn{font-weight:700}

/* ৩) স্ক্যান পাতা: দুই পাশের ও নিচের লোগো বাদ; ফাঁকা জায়গায় (ফ্রেমের ওপরে ও নিচে) বড় ২-৩টা লোগো, "স্ক্যান / আমার QR" বারের ওপরে */
html .sh.scanx .scbg .wm{display:none!important;animation:none!important}
html .sh.scanx .scbg .wm.w1,html .sh.scanx .scbg .wm.w2,html .sh.scanx .scbg .wm.w3{display:block!important;position:absolute!important;opacity:.2!important;animation:none!important}
html .sh.scanx .scbg .wm.w1{width:min(29vw,108px)!important;height:min(29vw,108px)!important;left:9%!important;right:auto!important;top:calc(var(--st,0px) + 13.5%)!important;bottom:auto!important;transform:rotate(-12deg)!important}
html .sh.scanx .scbg .wm.w2{width:min(21vw,78px)!important;height:min(21vw,78px)!important;right:13%!important;left:auto!important;top:calc(var(--st,0px) + 19%)!important;bottom:auto!important;transform:rotate(14deg)!important;opacity:.15!important}
html .sh.scanx .scbg .wm.w3{width:min(32vw,120px)!important;height:min(32vw,120px)!important;right:14%!important;left:auto!important;top:auto!important;bottom:19.5%!important;transform:rotate(10deg)!important}
html .sh.scanx .scbg .wm.w4{display:none!important}

/* ৪) সব ঘর দুই পাশে একদম লাগানো (কিবোর্ডের মতো): শুধু শুভেচ্ছা কার্ড ও কুপনের ঘর আগের মতো */
html .pgx .pcard:not(.cpcard),html .pgx .stp>.pcard:not(.cpcard){margin-left:0!important;margin-right:0!important;border-radius:0!important;border-left:0!important;border-right:0!important;box-shadow:none!important;border-top:0!important;border-bottom:1px solid #f0e3ea!important}
html .pgx .bk2>.bkc,html .pgx .bk3>.bkc{margin-left:0!important;margin-right:0!important;border-radius:0!important;box-shadow:none!important}
html .pgx .bk2>.bkc:first-child,html .pgx .bk3>.bkc:first-child{background:#fff!important;padding:14px 16px!important;border-bottom:1px solid #f0e3ea}
html .pgx .bk2>.bkc{background:#fff}
html .pgx .bk3 .bk3t,html .pgx .bk3 .bkref,html .pgx .bk3 .gmrow,html .pgx .bk3 .pinrow.bkpin{margin-left:0!important;margin-right:0!important;border-radius:0!important;border-left:0!important;border-right:0!important;box-shadow:none!important}
html .pgx .bk3 .bk3t,html .pgx .bk3 .bkref,html .pgx .bk3 .gmrow{border-bottom:1px solid #f0e3ea}
html .pgx .bk3 .pinrow.bkpin{border-top:1.5px solid #f1dce8!important;border-bottom:1.5px solid #f1dce8!important;margin-top:10px!important;padding-left:16px!important;padding-right:10px!important}
html .pgx .bk3 .pinrow.bkpin:focus-within{border-top-color:var(--p,#e2136e)!important;border-bottom-color:var(--p,#e2136e)!important;box-shadow:none!important}
html .pgx .bk2 .tw{margin-left:16px;margin-right:16px}
/* সফল পেজের কার্ড: পুরো চওড়া */
html .pgx .pcard.bkr{padding:16px 16px 4px!important}
html .pgx .pcard.bkr .bkg{margin:0 -16px}
html .pgx .pcard.cfm{padding:14px 16px 16px!important}

/* ৫) ধাপে ধাপে স্মুথ পেজ বদল (সেন্ড মানি / পেমেন্ট / ক্যাশ আউট): ভেতরের অংশ ডান থেকে ঢোকে, পেছনে গেলে বাম থেকে; কোনো ঝিলিক নেই */
@keyframes fp50in{from{opacity:0;transform:translate3d(34px,0,0)}to{opacity:1;transform:translate3d(0,0,0)}}
@keyframes fp50bk{from{opacity:0;transform:translate3d(-34px,0,0)}to{opacity:1;transform:translate3d(0,0,0)}}
html .pgx .stp.go{animation:fp50in .36s cubic-bezier(.22,1,.36,1) both!important;will-change:transform,opacity}
html .pgx .stp.go.bw{animation:fp50bk .36s cubic-bezier(.22,1,.36,1) both!important}
html.lowend .pgx .stp.go,html.lowend .pgx .stp.go.bw{animation-duration:.2s!important}
/* ধাপের ভেতরের কার্ডগুলো আলাদা করে আবার নড়ে না (দ্বিগুণ অ্যানিমেশন বন্ধ) */
html .pgx .stp.go .pcard,html .pgx .stp.go .bkc,html .pgx .stp.go .bk3t,html .pgx .stp.go .bkref{animation:none!important}

/* ৬) পেমেন্ট সফল হলে: কার্ড নিচ থেকে ভেসে ওঠে, টিক বৃত্ত স্প্রিং-এ ফোটে ও টিক আঁকা হয়, ঘরগুলো একটা একটা করে আসে, নিচের বার ওপরে ওঠে */
@keyframes fp50rise{0%{opacity:0;transform:translate3d(0,46px,0) scale(.97)}100%{opacity:1;transform:translate3d(0,0,0) scale(1)}}
@keyframes fp50pop{0%{transform:scale(0) rotate(-40deg);opacity:0}60%{transform:scale(1.18) rotate(6deg);opacity:1}100%{transform:scale(1) rotate(0)}}
@keyframes fp50ring{0%{transform:scale(.7);opacity:.55}100%{transform:scale(2);opacity:0}}
@keyframes fp50cell{from{opacity:0;transform:translate3d(0,14px,0)}to{opacity:1;transform:none}}
@keyframes fp50bar{from{transform:translate3d(0,100%,0)}to{transform:none}}
@keyframes fp50draw{to{stroke-dashoffset:0}}
html .pgx .stp.go .pcard.bkr{animation:fp50rise .6s cubic-bezier(.2,.9,.25,1) both!important}
html .pgx .pcard.bkr .bkck{position:relative;background:#e9f8f0;animation:fp50pop .65s cubic-bezier(.34,1.56,.64,1) .18s both}
html .pgx .pcard.bkr .bkck::after{content:"";position:absolute;inset:-2px;border-radius:50%;border:2px solid #1f9d63;opacity:0;animation:fp50ring .9s ease-out .45s 1 both}
html .pgx .pcard.bkr .bkck svg{animation:fp50draw .45s cubic-bezier(.4,0,.2,1) .5s forwards!important}
html .pgx .pcard.bkr .bkh b,html .pgx .pcard.bkr .bkh em,html .pgx .pcard.bkr .rcp{animation:fp50cell .5s cubic-bezier(.22,1,.36,1) both}
html .pgx .pcard.bkr .bkh b{animation-delay:.22s}html .pgx .pcard.bkr .bkh em{animation-delay:.3s}html .pgx .pcard.bkr .rcp{animation-delay:.38s}
html .pgx .pcard.bkr .bkg>div{animation:fp50cell .5s cubic-bezier(.22,1,.36,1) both}
html .pgx .pcard.bkr .bkg>div:nth-child(1){animation-delay:.46s}html .pgx .pcard.bkr .bkg>div:nth-child(2){animation-delay:.52s}
html .pgx .pcard.bkr .bkg>div:nth-child(3){animation-delay:.58s}html .pgx .pcard.bkr .bkg>div:nth-child(4){animation-delay:.64s}
html .pgx .pcard.bkr .bkg>div:nth-child(5){animation-delay:.7s}html .pgx .pcard.bkr .bkg>div:nth-child(6){animation-delay:.76s}
html .pgx .pcard.bkr .bkg>div:nth-child(n+7){animation-delay:.82s}
html .pgx .pcard.bkr .bks{animation:fp50cell .5s cubic-bezier(.22,1,.36,1) .85s both}
html .pgx .pfoot:has(.bknx) .bknx{animation:fp50bar .5s cubic-bezier(.22,1,.36,1) .55s both}
html.lowend .pgx .pcard.bkr .bkg>div,html.lowend .pgx .pcard.bkr .bks,html.lowend .pgx .pcard.bkr .rcp,html.lowend .pgx .pcard.bkr .bkh b,html.lowend .pgx .pcard.bkr .bkh em{animation-duration:.2s!important;animation-delay:0s!important}
@media (prefers-reduced-motion:reduce){html .pgx .stp.go,html .pgx .stp.go .pcard.bkr,html .pgx .pcard.bkr *{animation-duration:.01s!important;animation-delay:0s!important}}

/* ৭) চাপলে পেছনে কোনো রঙের আবরণ/ছায়া পড়বে না (অ্যাপের কোথাও): ট্যাপ-হাইলাইট, টেক্সট সিলেকশন, ফোকাস রিং, কার্ড/সারির চাপা-রং সব বন্ধ */
*,*::before,*::after{-webkit-tap-highlight-color:rgba(0,0,0,0)!important;-webkit-touch-callout:none}
html,body,#app,#sheet,#sheet2,.sh,.sh *{-webkit-user-select:none;user-select:none}
input,textarea{-webkit-user-select:text!important;user-select:text!important}
:focus{outline:none}
:focus-visible{outline:none}
button::-moz-focus-inner{border:0}
.sh .box:active,.tgrid>div:active,.bkg>div:active,.bkc:active,.bk3t:active,.bkref:active,.pcard:active,.rcp:active,.tgrid:active,.bkr:active,.ok:active{background-color:inherit!important;filter:none!important}
.pcard:active,.bkr:active,.wsheet:active,.sec:active,.msec:active,.prof:active,.balc:active{background:#fff!important}
.rr:active,.tr:active,.mr:active,.fr:active,.dmi:active,.pho:active,.tl:active,.it:active .ic{background:transparent!important}
.rr:active,.tr:active,.mr:active{transform:none!important;opacity:1!important}
html .tr:active{background:transparent!important}

/* ৮) লেখা: বিকাশের মতো স্বাভাবিক ওজন — নাম/সংখ্যা মাঝারি (500), শিরোনাম/বাটন বোল্ড (700); বেশি মোটা (800) নয় */
html .pgx .bkp b,html .pgx .bk3t b,html .pgx .bkg b,html .pgx .tgrid b,html .pgx .avl b,html .pgx .rcp b{font-weight:500!important}
html .trdd .amt,html .pgx .bkh b,html .pgx .bkh em{font-weight:700!important}
html .pgx .bk3t span,html .pgx .bkg span,html .pgx .bkl,html .tgrid span,html .pgx .bkref>div,html .pgx .bkp span{font-weight:400!important}
html .pgx .bk2 .fld.big input,html .bk3 .bkpin input{font-weight:500!important}
html .pgx .qa button,html .pgx .btn,html .pgx .gadd b{font-weight:700!important}
html .pgx .bkref input,html .pgx .bkref input::placeholder{font-weight:400!important}
html #kbar,html .nbar,html .bknx,html .pfoot .btn{font-weight:700}
#kpad .kpg button{font-weight:500}
html .c4g b{font-weight:500}

/* ৯) ফিঙ্গারপ্রিন্ট আইকন: আরও পরিষ্কার, পাতলা রেখা (মোটা নয়) */
svg.fpx .fc path{stroke-width:1.9}
svg.fpx .ff{stroke-width:1.8}
svg.fpx .fg{stroke-width:2.1}
html .bkfp svg.fpx,html .fl.pinp .bkfp svg.fpx{width:34px!important;height:34px!important}
html .fpb svg.fpx,html .bk3 .bkpin .fpb svg.fpx,html .v3pr .fpb svg.fpx{width:32px!important;height:32px!important}
svg.fpx{shape-rendering:geometricPrecision}

/* ১০) OTP: "ভেরিফাই হয়েছে" লেখা ঠিক পেস্ট বাটনের পাশে একদম সোজা, নিচে নামে না */
.otpact{align-items:center!important}
.otpact .otst{margin:0!important;min-height:0!important;height:48px;align-self:center;display:flex;align-items:center;line-height:1}
.otpact .otst svg{flex:none}

/* সেন্ড মানির প্রাপকের ঘর: আলাদা গোল-করা কার্ড নয়, পুরো চওড়া সাদা সারি */
html .pgx .bk2 .bkp,html .pgx .bk3 .bkp{border:0!important;border-radius:0!important;box-shadow:none!important;background:transparent!important;min-height:0!important;padding:0!important}

/* "নিশ্চিত করুন" (ধাপ ৪) পাতার ঘরও দুই পাশে লাগানো */
html .c4b{padding:10px 0 16px!important}
html .c4w{margin-bottom:10px!important;background:#fff;padding:12px 16px!important;border-bottom:1px solid #f0e3ea!important}
html .c4w .bkp{border:0!important;border-radius:0!important;box-shadow:none!important;background:transparent!important;min-height:0!important;padding:0!important}
html .c4g{gap:0!important;background:#fff;border-top:1px solid #f0e3ea}
html .c4g>div{border-radius:0!important;box-shadow:none!important;border-bottom:1px solid #f0e3ea!important;padding:12px 16px!important}
html .c4g>div:nth-child(even):not(.c4tot):not(.wide){border-left:1px solid #f0e3ea!important}
html .c4g>div.c4tot,html .c4g>div:first-child{border-radius:0!important;box-shadow:none!important}
html .c4n{margin:10px 0 0!important;border-radius:0!important;box-shadow:none!important;padding:12px 16px!important}
.otpact .otst{justify-content:flex-start!important}


/* =====================================================================
   v2.50 — ফন্ট: ইংরেজি অক্ষর ও সংখ্যা অ্যাপের ভেতরে ভরা Roboto (বিকাশের মতো, সব ফোনে একই); বাংলা ফোনের নিজস্ব Noto Sans Bengali।
   ===================================================================== */
@font-face{font-family:"FP Roboto";font-style:normal;font-weight:400 700;font-display:swap;src:url(data:font/woff;base64,) format("woff")}
:root{--fpfont:"FP Roboto","Noto Sans Bengali",system-ui,-apple-system,"Segoe UI",sans-serif}
html *,html input,html button,html textarea,html select{font-family:var(--fpfont)}
html body{-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;font-kerning:normal;letter-spacing:0}
html .pgx .avl,html .pgx .bkp,html .pgx .bkg,html .pgx .bk3t,html .tgrid,html .trdd .amt,#kbar,#kpad .kpg button,.bkc .fld.big input{font-variant-numeric:normal}

/* ===== v2.52: NID তথ্যের নতুন ঘর ও বাছাই পপ-আপ ===== */
#kyc .kshd{font-size:13px;font-weight:700;color:var(--p);margin:14px 4px 8px;letter-spacing:.2px}
#kyc .kpick span.kph{color:#c1bac6;font-weight:500;font-size:14px}
#kyc .kpick em{padding:3px 6px;line-height:0}
#kyc .kpick em svg{width:18px;height:18px;fill:none;stroke:var(--p);stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
#kyc .kpkw{position:fixed;inset:0;z-index:70;display:flex;flex-direction:column;justify-content:flex-end}
#kyc .kpkb{position:absolute;inset:0;background:rgba(20,6,14,.5);opacity:0;transition:opacity .25s}
#kyc .kpkw.in .kpkb{opacity:1}
#kyc .kpks{position:relative;background:#fff;border-radius:26px 26px 0 0;padding:14px 16px calc(14px + env(safe-area-inset-bottom));max-height:78vh;display:flex;flex-direction:column;transform:translateY(100%);transition:transform .3s cubic-bezier(.2,.8,.2,1)}
#kyc .kpkw.in .kpks{transform:none}
#kyc .kpks::before{content:"";width:40px;height:4px;border-radius:4px;background:#e4dde8;margin:-4px auto 10px}
#kyc .kpkh{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
#kyc .kpkh b{font-size:17px;font-weight:700;color:#2a262b}
#kyc .kpkx{width:34px;height:34px;border:0;border-radius:50%;background:#f2eef3;display:grid;place-items:center;padding:0}
#kyc .kpkx svg{width:16px;height:16px;fill:none;stroke:#5b505e;stroke-width:2.6;stroke-linecap:round}
#kyc .kpkq{display:flex;align-items:center;gap:8px;background:#f6f2f7;border-radius:14px;padding:0 12px;margin-bottom:8px}
#kyc .kpkq svg{width:18px;height:18px;fill:none;stroke:#9a8fa0;stroke-width:2.4;stroke-linecap:round;flex:none}
#kyc .kpkq input{flex:1;border:0;outline:0;background:transparent;font-size:15px;font-weight:600;color:#2a262b;padding:12px 0;min-width:0}
#kyc .kpkl{overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;margin:0 -4px;padding:0 4px}
#kyc .kpki{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;border:0;background:transparent;text-align:left;padding:13px 12px;border-radius:14px;font:inherit;color:#2a262b}
#kyc .kpki:active{background:#fdeef5}
#kyc .kpki b{display:block;font-size:15.5px;font-weight:600}
#kyc .kpki small{display:block;font-size:12px;font-weight:500;color:#9a8fa0;margin-top:1px}
#kyc .kpki.on{background:#fde7f1}
#kyc .kpki.on b{color:var(--p);font-weight:700}
#kyc .kpkc{width:24px;height:24px;border-radius:50%;background:var(--p);display:none;place-items:center;flex:none}
#kyc .kpki.on .kpkc{display:grid}
#kyc .kpkc svg{width:13px;height:13px}
#kyc .kpku b{color:var(--p)}
#kyc .kpke{text-align:center;color:#9a8fa0;font-size:14px;padding:22px 0;margin:0}

/* =====================================================================
   v2.54 — NID ছবির পরের অ্যানিমেশন: স্ক্যান-রেখা, সবুজ টিক, ঝলমলে ফ্রেম, নরম পাতা বদল
   ===================================================================== */
/* যাচাই চলার সময় ছবির ওপর স্ক্যান-রেখা */
#kyc .kswp{position:absolute;left:0;right:0;top:-42%;height:42%;z-index:2;pointer-events:none;background:linear-gradient(180deg,rgba(226,19,110,0),rgba(226,19,110,.22) 78%,rgba(255,255,255,.55) 98%,rgba(226,19,110,0));border-bottom:2px solid rgba(255,255,255,.85);box-shadow:0 6px 18px rgba(226,19,110,.45);animation:kswp 1.25s cubic-bezier(.45,0,.35,1) infinite}
@keyframes kswp{0%{transform:translateY(0)}100%{transform:translateY(340%)}}
#kyc .kwr.pv .kwin .kpvi{transition:filter .4s}
/* সফল: সবুজ টিক */
#kyc .kwr.okp .kwin::after{content:"";position:absolute;inset:0;background:rgba(255,255,255,.42);animation:kdfade .35s ease both;z-index:3}
@keyframes kdfade{from{opacity:0}to{opacity:1}}
#kyc .kwr.okp{animation:kwlift .7s cubic-bezier(.22,1,.36,1) both}
@keyframes kwlift{0%{transform:translate(-50%,-50%) scale(1)}35%{transform:translate(-50%,-50%) scale(1.035)}100%{transform:translate(-50%,-50%) scale(1)}}
#kyc .kwr .kdone{position:absolute;left:50%;top:50%;width:92px;height:92px;margin:-46px 0 0 -46px;z-index:6;pointer-events:none}
#kyc .kwr .kdone svg{position:relative;z-index:2;width:100%;height:100%;filter:drop-shadow(0 8px 20px rgba(18,161,91,.5))}
#kyc .kwr .kdone .kdb{fill:#12a15b;transform-origin:40px 40px;animation:kdpop .55s cubic-bezier(.2,1.5,.4,1) both}
#kyc .kwr .kdone .kdt{fill:none;stroke:#fff;stroke-width:6;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:60;stroke-dashoffset:60;animation:kdtk .42s .28s cubic-bezier(.4,0,.2,1) forwards}
#kyc .kwr .kdone i{position:absolute;inset:4px;border-radius:50%;border:3px solid #12a15b;opacity:0;animation:kdrip 1s .12s ease-out both}
#kyc .kwr .kdone i+i{animation-delay:.38s}
@keyframes kdpop{from{transform:scale(0)}to{transform:scale(1)}}
@keyframes kdtk{to{stroke-dashoffset:0}}
@keyframes kdrip{0%{transform:scale(.8);opacity:.75}100%{transform:scale(2);opacity:0}}
#kyc .kn .kfr.dn i{filter:drop-shadow(0 0 7px rgba(18,161,91,.55))}
#kyc .kn .kfr.dn.wn i{border-color:#e8a20c;filter:drop-shadow(0 0 7px rgba(232,162,12,.5))}
#kyc .kwr.okp .kfr i{border-color:#12a15b}
/* একটি লাইনের সতর্কতা (তালিকার বদলে) */
#kyc .kwn{display:flex;align-items:center;gap:9px;background:#fff6e0;color:#8a5a00;border:1.5px solid #f3d899;border-radius:14px;padding:9px 12px;margin:0 0 10px;font-size:13.5px;font-weight:700;line-height:1.3;text-align:left;animation:krin .4s cubic-bezier(.2,.9,.3,1.1) both}
#kyc .kwn i{width:22px;height:22px;border-radius:50%;background:#e8a20c;color:#fff;display:grid;place-items:center;flex:none;font-style:normal;font-size:13px;font-weight:700}
#kyc .kcam.kn .kwr.pv~.kbt .krow{animation:krin .45s cubic-bezier(.2,.9,.3,1.1) both}
#kyc .kcam.kn .kgh,#kyc .kcam.kn .kgo{height:46px;font-size:15px}
/* নতুন পাতায় (সামনে → পেছনে) ক্যামেরার ঘর নরমভাবে ভেসে আসে */
#kyc .kpi-f .kwr:not(.pv),#kyc .kpi-b .kwr:not(.pv){animation:kwin .62s .1s cubic-bezier(.22,1,.36,1) backwards}
@keyframes kwin{from{opacity:0;transform:translate(-50%,-46%) scale(.93)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
#kyc .kpi-f .klg,#kyc .kpi-b .klg{animation:kwlg .5s .05s cubic-bezier(.22,1,.36,1) backwards}
@keyframes kwlg{from{opacity:0;transform:translateY(-12px)}to{opacity:1;transform:none}}
#kyc .kpo-f,#kyc .kpo-b{animation-duration:.3s}

/* =====================================================================
   v2.55 — ফেস স্ক্যান: গোল ক্যামেরা + টিক-রিং (বাইরের সব আপনার রং ও লোগো)
   ===================================================================== */
#kyc .kcam.kn.kf3{--fw:min(76vw,290px)}
#kyc .kcam.kn.kf3 .kwr.ov{aspect-ratio:1}
#kyc .kcam.kn.kf3 .kwr.ov .kwin{inset:10.5%;border-radius:50%;box-shadow:0 0 0 4px #fff,0 0 0 5.5px rgba(226,19,110,.28),0 14px 40px rgba(226,19,110,.26)}
#kyc .kcam.kn.kf3 .kov u{aspect-ratio:1;border-radius:50%}
#kyc .kcam.kn.kf3 .krt{stroke-width:5!important;stroke-linecap:butt!important;stroke-dasharray:1.2 4.356!important;stroke:rgba(226,19,110,.2)}
#kyc .kcam.kn.kf3 .krf{stroke-width:5!important;stroke-linecap:butt!important;stroke:var(--p)}
#kyc .kcam.kn.kf3 .kra.on .krt{stroke:rgba(226,19,110,.5)!important;animation:none}
#kyc .kcam.kn.kf3 .kra.on{filter:drop-shadow(0 0 4px rgba(226,19,110,.5))}
#kyc .kcam.kn.kf3 .kra.on .krf{animation:krp 1.3s ease-in-out infinite}
#kyc .kcam.kn.kf3 .kra.dn2 .krt{stroke:#12a15b}
#kyc .kcam.kn.kf3 .kra.dn2 .krf{stroke:#12a15b}
#kyc .kcam.kn.kf3 .kra.dn2{filter:drop-shadow(0 0 4px rgba(18,161,91,.55))}
#kyc .kcam.kn.kf3 .kfarr.up{top:calc(46% - var(--fw) / 2 - 52px)}
#kyc .kcam.kn.kf3 .kfarr.down,#kyc .kcam.kn.kf3 .kfarr.blink{top:calc(46% + var(--fw) / 2 + 10px)}
#kyc .kcam.kn.kf3 .kfarr.right{right:1%}
#kyc .kcam.kn.kf3 .kfarr.left{left:1%}
#kyc .kcam.kn.kf3 .kwr.ov.burst::after{inset:2%;border-width:3px}


/* ===== v2.56: "আপনার তথ্য" — কম্প্যাক্ট ঘর (বিকাশের মতো, এক স্ক্রিনে বেশি ঘর) ===== */
#kyc .kbody .kf{padding:7px 12px!important;gap:10px!important;border-radius:14px!important;margin-bottom:7px!important;background:#fff!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important;box-shadow:0 2px 8px rgba(170,20,95,.07)!important;border:1.5px solid transparent!important;animation-duration:.22s!important;animation-delay:calc(var(--n) * .03s)!important}
#kyc .kbody .kf.gd{border-color:#bfe9d1!important}
#kyc .kbody .kf.bd{border-color:#ffc9d1!important}
#kyc .kbody .kf.op{border-color:#e6e1e8!important}
#kyc .kbody .kf .kfi{width:32px!important;height:32px!important;border-radius:10px!important}
#kyc .kbody .kf .kfi svg{width:17px!important;height:17px!important}
#kyc .kbody .kf label{font-size:11px!important;margin-bottom:0!important}
#kyc .kbody .kf input,#kyc .kbody .kf textarea{font-size:14.5px!important;line-height:1.3!important;padding:1px 0!important}
#kyc .kbody .kf textarea{min-height:0!important}
#kyc .kbody .kdb,#kyc .kbody .kdb span{font-size:14.5px!important;min-height:26px!important}
#kyc .kbody .kdb em{padding:5px 11px!important;font-size:12px!important;right:46px!important}
#kyc .kbody .kf .kt2{width:23px!important;height:23px!important;animation-delay:calc(var(--n) * .03s + .08s)!important}
#kyc .kbody .kf .kt2 svg{width:13px!important;height:13px!important}
#kyc .kbody .kf .kt2.op{background:#cfc8d3!important}
#kyc .kbody .kshd{margin:10px 4px 6px!important;font-size:12.5px!important}
#kyc .kbody .ksum{padding:9px 14px!important;margin-bottom:8px!important}
