/* =====================================================================
   v2.57 — ভাগ ১: স্থির ব্যাকগ্রাউন্ড, PIN ডট, ফিঙ্গারপ্রিন্ট, কোড পেজ, আপনার তথ্য পেজ
   ===================================================================== */
/* ১) নম্বর/কোড/নতুন অ্যাকাউন্ট পেজের ব্যাকগ্রাউন্ড: কিবোর্ড উঠলেও এক চুলও নড়ে না (পর্দার উচ্চতা --fh এ আটকানো, ওপর থেকে বসানো) */
.fl.light{background:#f7f5f7!important;background-attachment:scroll!important}
.fl.light::after{display:none!important}
.fl.light::before{content:"";position:fixed;left:0;top:0;width:100%;height:var(--fh,100dvh);z-index:0;pointer-events:none;
  background:
    linear-gradient(rgba(247,245,247,.90),rgba(247,245,247,.90)),
    url(/icons/logo-pink.png) no-repeat left -78px top 30%/200px 200px,
    url(/icons/logo-pink.png) no-repeat right -84px top 50%/210px 210px,
    url(/icons/logo-pink.png) no-repeat left 50% bottom 90px/180px 180px,
    #f7f5f7}
/* লগইনের সাদা অংশও একই ভাবে স্থির */
