/* ২) PIN এর ডট: সব জায়গায় একই মাপ, মাঝারি-মোটা */
input[type="password"]{font-family:Roboto,Arial,sans-serif!important;font-size:26px!important;font-weight:700!important;letter-spacing:.16em!important;line-height:1!important}
input[type="password"]::placeholder{font-size:15px!important;font-weight:400!important;letter-spacing:0!important}
#rk[type="text"],#rk2[type="text"]{font-size:20px!important;font-weight:600!important;letter-spacing:.2em!important}

/* ৩) ফিঙ্গারপ্রিন্ট: একটু বড়, ডান প্রান্তে দাগের শেষ বরাবর, নিচের দাগ থেকে স্পষ্ট ফাঁক */
.fl.pinp .bkp{height:66px!important;align-items:center!important}
.fl.pinp .bkfp{width:52px!important;height:52px!important;margin:0 0 8px 0!important;flex:none}
.fl.pinp .bkfp svg{width:30px!important;height:30px!important}

/* ৪) নাম ঘর: বাংলা প্লেসহোল্ডারে ফাঁক ফাঁক নয় */
#rn,#rn::placeholder{letter-spacing:0!important;word-spacing:0!important;font-kerning:normal;text-rendering:auto;font-feature-settings:normal}
/* নাম লেখার সময় "অ্যাকাউন্ট খুলুন" বার কিবোর্ডের সাথে ওঠে না */
html.rnf .regv .nbar{display:none!important}

/* ৫) কোড পেজ: "কোড পেস্ট করুন" ঘর/বর্ডার ছাড়া লেখা, "যাচাই হচ্ছে/হয়েছে" একই লাইনে সোজা */
.otpv .otpact{display:flex!important;flex-direction:row!important;align-items:center!important;justify-content:space-between!important;height:40px!important;min-height:40px!important;margin-top:14px!important;gap:10px}
.otpv .otpact .otst{height:40px!important;min-height:0!important;margin:0!important;padding:0!important;display:flex!important;align-items:center!important;line-height:1!important;align-self:center!important}
.otpv .otpact .otpp{height:40px!important;margin:0 -8px 0 auto!important;padding:0 8px!important;border:0!important;background:transparent!important;box-shadow:none!important;border-radius:8px;color:var(--lp);display:inline-flex!important;align-items:center!important;gap:6px;font-size:13px!important;font-weight:700!important;line-height:1!important}
.otpv .otpact .otpp:active{background:#fde7f1!important}
.otpv .otrow{display:flex;align-items:center;justify-content:space-between;height:40px;min-height:40px;margin-top:20px}
.otpv .otrow .otl,.otpv .otrow .otprs{line-height:1;display:inline-flex;align-items:center}
.otpv .otpb{margin-top:6px}

/* ৬) আপনার তথ্য পেজ: গণনার পাশের লেখা নেই, সব মান সাধারণ কালো, "নিশ্চিতভাবে পড়া হয়েছে" নেই */
#kyc .kbody.kflat .ksum span{display:none!important}
#kyc .kbody.kflat .kf.kfl .klk2{display:none!important}
#kyc .kbody.kflat .kf.kfl.lk input,#kyc .kbody.kflat .kf.kfl.lk textarea{color:#2a262b!important}
#kyc .kbody.kflat .kf.kfl .kdb em{display:inline-flex!important;align-items:center!important;gap:4px;line-height:1!important;height:20px}
#kyc .kbody.kflat .kf.kfl .kdb em svg{display:block;margin:0!important;transform:none!important;position:relative;top:0}
#kyc .kbody.kflat .kf.kfl .kdb{align-items:center!important}
/* বাছাই শিট খোলা/বন্ধে পেছনের পেজ না কাঁপে */
#kyc .kpkw,#kyc .kdw{contain:layout paint;will-change:opacity}
#kyc .kbody{overscroll-behavior:contain;scroll-behavior:auto!important}
/* (v2.57) পুরনো নিয়মের চেয়ে জোরালো, যেন সব PIN ঘরে একই ডট মাপ বসে */
html body .fl.pinp .bkp input.pinin,html body .regv .pfield input#rk,html body .regv .pfield input#rk2,html body #kyc input#kpin,html body #sheet input[type="password"],html body #sheet2 input[type="password"],html body #app input[type="password"]{font-family:Roboto,Arial,sans-serif!important;font-size:26px!important;font-weight:700!important;letter-spacing:.16em!important;line-height:1!important}
html body .fl.pinp .bkp input.pinin::placeholder,html body .regv .pfield input#rk::placeholder,html body .regv .pfield input#rk2::placeholder,html body #kyc input#kpin::placeholder{font-size:15px!important;font-weight:400!important;letter-spacing:0!important}
html body .regv .pfield input#rk[type="text"],html body .regv .pfield input#rk2[type="text"]{font-size:20px!important;font-weight:600!important;letter-spacing:.2em!important}
html body .regv .pfield input#rk::placeholder,html body .regv .pfield input#rk2::placeholder{font-size:26px!important;font-weight:700!important;letter-spacing:.16em!important;color:#cdc6d0!important}
.fl.pinp .bkfp{margin-bottom:4px!important}

/* =====================================================================
   v2.58 — ফোন অনুযায়ী অ্যানিমেশন: html.hiend = পুরো শক্তি; সাধারণ (মাঝারি) = শুধু সাজানোর অনন্ত লুপ বন্ধ; html.lowend = আরও কম
   (স্পিনার/লোডার সব ফোনেই চলে)
   ===================================================================== */
html.bgp *,html.bgp *:before,html.bgp *:after{animation-play-state:paused!important}
html:not(.hiend) .bn svg.bv,html:not(.hiend) button.hold,html:not(.hiend) .fps-orb,html:not(.hiend) .fpa-ry,html:not(.hiend) .fpa-rp,
html:not(.hiend) .bkfp.on,html:not(.hiend) #kyc .kov u,html:not(.hiend) #kyc .kcam .kbg .b1,html:not(.hiend) #kyc .kcam.kn .kbg .b1,
html:not(.hiend) .qdeco .qwm,html:not(.hiend) .sh.scanx .scbg .wm,html:not(.hiend) #kyc .kwm,html:not(.hiend) .otwarn svg,
html:not(.hiend) #kyc .kn .kfr i,html:not(.hiend) #kyc .kfr2,html:not(.hiend) .scf .sl{animation:none!important}
html:not(.hiend) #kyc .kcam .kbg .b1,html:not(.hiend) #kyc .kcam.kn .kbg .b1{filter:none!important;opacity:.5}
html.lowend #kyc .kbg *,html.lowend #kyc .kbg *:before{filter:none!important;animation:none!important}
html.lowend #kyc .kfa,html.lowend #kyc .kfc,html.lowend #kyc .kmf.sc::after,html.lowend #kyc .kml,html.lowend #kyc .kcir.wt svg{animation:none!important}
html.lowend #kyc .kpo,html.lowend #kyc .kpi-f,html.lowend #kyc .kpi-b{animation-duration:.16s!important}
html.lowend #kyc .kflash{animation-duration:.2s!important}
html.lowend *{will-change:auto!important}

/* =====================================================================
   v2.59 — কিবোর্ড ওঠার সময় "পরবর্তী/অ্যাকাউন্ট খুলুন" বারের নিচে সাদা ফাঁকা আর পেছনের পেজ ঝিলিক
   ===================================================================== */
/* বারের নিচে বারের রঙেরই "স্কার্ট": সিস্টেম কিবোর্ড আঁকার আগের মুহূর্তে নিচে সাদা/পেছনের পেজ আর দেখা যায় না, কিবোর্ড এসে এর ওপর বসে */
html #kbar{box-shadow:0 100vh 0 0 #9e9a9f;transition:transform .26s cubic-bezier(.2,.8,.2,1),opacity .18s ease,box-shadow .22s ease}
html #kbar.on{box-shadow:0 100vh 0 0 #e9157a}
html #kbar:not(.show){box-shadow:none}
html.lowend #kbar{transition:transform .18s ease-out,opacity .12s ease}
/* বাছাই-শিট খোলা থাকলে পেছনের পেজ নড়ে না/টানলে স্ক্রল ধরে না */
#kyc:has(#kpk) .kbody,#kyc:has(.kdw) .kbody{overflow:hidden!important}
#kyc .kpks{overscroll-behavior:contain}

/* =====================================================================
   v2.60 — বার কিবোর্ডের সাথে হুবহু একই গতিতে (নেটিভ থেকে প্রতি ফ্রেমে --kbd আসে)
   ===================================================================== */
html #kbar.show{transform:translate3d(0,calc(var(--kbd,0px) - var(--dko,0px)),0)}
html #kbar.kba,html #kbar.kba.show{transition:opacity .18s ease,box-shadow .22s ease!important}

/* =====================================================================
   v2.60 — বন্ধ হওয়ার অ্যানিমেশন শেষ হওয়ার আগেই পেজ/শিট মুছে যেত (JS টাইমার ২২০–২৬০ms, অ্যানিমেশন ২৪০–৩২০ms) → শেষ মুহূর্তে পেজ "টুক" করে ঝিলিক দিত।
   এখন সব বন্ধ-অ্যানিমেশন টাইমারের আগে (≤২০০ms) শেষ হয়।
   ===================================================================== */
html .sh.out{animation-duration:.2s!important}
html .sh.pgx.out .box,html .sh.pgx.re.out .box,html .sh.drw.out .box{animation-duration:.2s!important}
html .sh.dlg.out .box,html .sh.scanx.out .box{animation-duration:.2s!important}
html #kyc .kpkw:not(.in) .kpks{transition-duration:.2s!important}
html #kyc .kpkw:not(.in) .kpkb{transition-duration:.2s!important}
html #kyc .kdw:not(.in) .kds{transition-duration:.2s!important}
html #kyc .kdw:not(.in) .kdb{transition-duration:.2s!important}

/* =====================================================================
   v2.61 — (১) কিবোর্ড↔কিপ্যাড বদলে বার নিচ থেকে ওঠে (উপর থেকে নামে না) (২) প্রথম PIN ঘরেও টিক, দ্বিতীয় ঘর নজরে আসে
   (৩) KYC পেজ ফোটার সময় পেছনের হোম পেজ ঝলকে ওঠা বন্ধ
   ===================================================================== */
@keyframes kbup{from{transform:translate3d(0,calc(100% + 6px),0)}}
html #kbar.kup{animation:kbup .28s cubic-bezier(.2,.8,.2,1) backwards;transition:none!important}
html .regv .pfield .rgm{margin-right:2px}
html .regv .pfield.okf .rgm{display:grid}
@keyframes rgpl{0%{background:rgba(226,19,110,.14)}100%{background:transparent}}
html .regv .rgf.rgpulse .pfield{animation:rgpl .9s ease-out both!important}
/* KYC: স্বচ্ছ হয়ে নয়, শুধু নিচ থেকে উঠে আসে; পেছনের অ্যাপ লুকানো, তাই হোম পেজ দেখা যায় না */
@keyframes kin2{from{transform:translateY(26px)}to{transform:none}}
html #kyc.kin{animation:kin2 .3s var(--ease,cubic-bezier(.22,1,.36,1)) both}
html:has(#kyc.kin),body:has(#kyc.kin){background:var(--bg,#f5f0f5)!important}
body:has(#kyc.kin) #app{visibility:hidden}

/* v3.02 — কিপ্যাড ও বার একই সময়/গতিতে নিচ থেকে ওঠে */
html #kpad{transition:transform .28s cubic-bezier(.2,.8,.2,1)!important}
html.lowend #kpad{transition:none!important}
html #kbar.kup{animation-duration:.28s}

/* =====================================================================
   v3.03 — অ্যানিমেশন একই নিয়মে (শেষ ব্লক, আগের সব ওভাররাইড ছাপিয়ে)
   নিয়ম: ঢোকা = --t-in + --mi (শুরুতে দ্রুত, শেষে নরম), বেরোনো = --t-out + --mo (দ্রুত সরে যায়)
   সময় বদলাতে চাইলে শুধু নিচের চার মান বদলান। বেরোনোর সময় JS টাইমার (২২০–২৪০ms) এর কম রাখুন।
   ===================================================================== */
:root{--mi:cubic-bezier(.32,.72,0,1);--mo:cubic-bezier(.4,0,1,1);--t-in:.32s;--t-out:.2s}

/* পূর্ণ পেজ: ডান থেকে ঢোকে, ডানে বেরোয় */
html .sh.pgx .box{animation:pgSlideIn var(--t-in) var(--mi) both!important;will-change:transform;backface-visibility:hidden}
html .sh.pgx.out .box{animation:pgSlideOut var(--t-out) var(--mo) both!important}
html .sh.pgx.re .box,html .sh.pgx.re.out .box{animation:none!important}
html .sh.pgx.re.out .box{animation:pgSlideOut var(--t-out) var(--mo) both!important}

/* নিচ থেকে ওঠা ডায়ালগ ও পেছনের আবছা পর্দা */
html .sh:not(.pgx){animation:fade calc(var(--t-in) - .06s) ease both}
html .sh:not(.pgx).out{animation:fadeo var(--t-out) ease both}
html .sh.dlg .box,html .sh.scanx .box{animation:up var(--t-in) var(--mi) both;will-change:transform;backface-visibility:hidden}
html .sh.dlg.out .box,html .sh.scanx.out .box{animation:down var(--t-out) var(--mo) both}
html .sh.re,html .sh.re .box{animation:none}
html .sh.dlg.re.out .box{animation:down var(--t-out) var(--mo) both}

/* বাম থেকে আসা মেনু */
html .sh.drw .box{animation:dslin var(--t-in) var(--mi) both}
html .sh.drw.out .box{animation:dslout var(--t-out) var(--mo) both}

/* কিবোর্ড ↔ কিপ্যাড: কিপ্যাড ও বার হুবহু এক সময়ে, এক গতিতে নিচ থেকে ওঠে */
html #kpad{transition:transform var(--t-in) var(--mi)!important;will-change:transform}
html #kbar{transition:transform var(--t-in) var(--mi),opacity .18s ease}
html #kbar.nt{transition:none!important}
@keyframes kbup{from{transform:translate3d(0,calc(100% + 6px),0)}}
html #kbar.kup{animation:kbup var(--t-in) var(--mi) backwards;transition:none!important}
/* কিপ্যাড ওঠার সময় পেজের নিচের ফাঁকা অংশ প্রতি ফ্রেমে বদলে ঝাঁকুনি দিত; এখন একবারে বসে */
html .pgx .pbody,html #kyc .kbody{transition:none!important}
html.pinkb .pgx .pbody,html.pinkb #kyc .kbody{scroll-behavior:smooth}

/* ধাপ বদল ও ট্যাব পেজ */
html .stp.go{animation:stepin2 .26s var(--mi) both}
html .stp.go.bw{animation-name:stepinb}
@keyframes stepinb{from{opacity:0;transform:translateX(-14px)}to{opacity:1;transform:none}}
html .pg.in .it{animation-delay:min(calc(var(--i,0) * 30ms + 60ms),260ms)}

/* স্পর্শ: সব বাটন একই চাপ-অনুভূতি */
html button:not(:disabled):active,html .it:active,html .fc:active,html .mr:active,html .rr:active{transition-duration:.08s}

/* ফোন ধীর হলে (lowend) শুধু সরানো থাকে, আবছা/ঝাপসা ছাড়া */
html.lowend .sh:not(.pgx){-webkit-backdrop-filter:none!important;backdrop-filter:none!important;background:rgba(48,8,30,.42)!important}
html.lowend .sh.pgx .box{animation-duration:.22s!important}
html.lowend .sh.pgx.out .box{animation-duration:.16s!important}
/* পেজের ভেতরের ধাপ: একই সময়/ইজিং (আগে .36s আলাদা বক্ররেখায় ছিল) */
html .pgx .stp.go{animation:fp50in .3s var(--mi) both!important}
html .pgx .stp.go.bw{animation:fp50bk .3s var(--mi) both!important}
html.lowend .pgx .stp.go,html.lowend .pgx .stp.go.bw{animation-duration:.2s!important}
/* নামার সময়ও কিপ্যাড ও বার একই সময়/গতিতে */
html #kpad:not(.show){transition:transform var(--t-out) var(--mo)!important}
html #kbar:not(.show):not(.nt){transition:transform var(--t-out) var(--mo),opacity .16s ease}
html.lowend #kpad:not(.show){transition:none!important}

/* =====================================================================
   v3.05 — KYC পাতা বদলে ঝিলিক বন্ধ
   (১) আগে পুরনো-নতুন দুটো পাতা একসাথে ফেড হত: মাঝে দুটোই আধা-স্বচ্ছ, ফাঁকা দেখাত; আর পুরনো পাতার কার্ডগুলোর ঢোকার
       অ্যানিমেশন আবার চলে ভূতের মতো ভেসে উঠত। এখন ফেড নয়, iOS-এর মতো ঠেলে ঢোকা: নতুন পাতা পুরো ঢাকা অবস্থায় (opacity ১) ডান
       থেকে এসে পুরনোর ওপর বসে; ফেরার সময় বর্তমান পাতা ডানে সরে নিচের আগের পাতা দেখায়।
   (২) KYC চালু থাকলে পেছনের অ্যাপ (হোম) লুকানো (html.kycon, kycRender/kycClose এ বসে/সরে); ফিরে আসার সময় হোম ঝলকাত।
   সময়/বক্ররেখা সেই --t-in --t-out --mi --mo থেকেই আসে (v3.03)।
   ===================================================================== */
html.kycon #app{visibility:hidden}
@keyframes kpSf{from{transform:translate3d(100%,0,0)}to{transform:translate3d(0,0,0)}}
@keyframes kpSb{from{transform:translate3d(-24%,0,0)}to{transform:translate3d(0,0,0)}}
@keyframes kpDf{from{transform:translate3d(0,0,0)}to{transform:translate3d(-24%,0,0)}}
@keyframes kpDb{from{transform:translate3d(0,0,0)}to{transform:translate3d(100%,0,0)}}
html #kyc .kpi-f{animation:kpSf var(--t-in) var(--mi) both!important;z-index:81;background-color:#f3f1f4;box-shadow:-12px 0 28px rgba(60,0,30,.14);will-change:transform}
html #kyc .kpo-f{animation:kpDf var(--t-in) var(--mi) both!important;z-index:79;will-change:transform}
html #kyc .kpi-b{animation:kpSb var(--t-in) var(--mi) both!important;z-index:79;background-color:#f3f1f4;will-change:transform}
html #kyc .kpo-b{animation:kpDb var(--t-out) var(--mo) both!important;z-index:82;box-shadow:-12px 0 28px rgba(60,0,30,.14);will-change:transform}
/* নতুন পাতার ভেতরের জিনিস আলাদা করে ফেড-ইন করে না (পাতার সাথে একসাথেই আসে); নইলে ঢোকার মুহূর্তে ফাঁকা দেখায় */
html #kyc .kpi-f .kcard,html #kyc .kpi-b .kcard,html #kyc .kpi-f .kwr:not(.pv),html #kyc .kpi-b .kwr:not(.pv),html #kyc .kpi-f .klg,html #kyc .kpi-b .klg{animation:none!important;opacity:1!important}
html #kyc .kpi-b .kshield,html #kyc .kpi-b .kt2{animation:none!important}
html.lowend #kyc .kpi-f,html.lowend #kyc .kpi-b,html.lowend #kyc .kpo-f{animation-duration:.2s!important}
html.lowend #kyc .kpo-b{animation-duration:.16s!important}


/* =====================================================================
   v3.06 — KYC নতুন ডিজাইন: গ্রেডিয়েন্ট হেডার + ধাপ সূচক, ইন্ট্রো, ডকুমেন্ট বাছাই, স্থির বড় লোগোর ব্যাকগ্রাউন্ড
   ===================================================================== */
/* ব্যাকগ্রাউন্ড: লগইনের মতো ৩টি বড় স্থির লোগো (কোনোটা নড়ে না) */
#kyc .kw2{background:linear-gradient(rgba(248,244,247,.9),rgba(248,244,247,.9)),url(../icons/logo-pink.png) no-repeat left -78px top 36%/200px 200px,url(../icons/logo-pink.png) no-repeat right -84px top 56%/210px 210px,url(../icons/logo-pink.png) no-repeat left 50% bottom 70px/180px 180px,var(--bg)}
#kyc .kw2 .kbody,#kyc .kw2 .kbtm{background:transparent}
/* হেডার */
#kyc .kt.kt2{position:relative;overflow:hidden;display:block;width:100%;box-sizing:border-box;align-self:stretch;height:auto;padding:calc(10px + var(--st)) 14px 18px;background:linear-gradient(160deg,#ff4d9a,#e2136e 48%,#b80d58);border-radius:0 0 30px 30px;box-shadow:0 12px 30px rgba(226,19,110,.28);z-index:3}
#kyc .kt2 .kbb{position:absolute;border-radius:50%;background:rgba(255,255,255,.09);pointer-events:none;will-change:transform;animation:kfl 9s ease-in-out infinite alternate}
#kyc .kt2 .b1{width:170px;height:170px;right:-52px;top:-72px}
#kyc .kt2 .b2{width:110px;height:110px;left:-34px;bottom:-54px;animation-delay:-3.5s}
@keyframes kfl{to{transform:translate(14px,10px) scale(1.12)}}
#kyc .kt2 .ktr{position:relative;display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:44px}
#kyc .kt2 .ktr b{flex:1;text-align:center;font-size:17px;font-weight:700;letter-spacing:.2px}
#kyc .kt2 .kbk{background:rgba(255,255,255,.22);width:40px;height:40px;flex:none;backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}
#kyc .kt2 .ktr span{width:40px;flex:none}
#kyc .ksp{position:relative;display:flex;align-items:flex-start;padding:8px 8px 0}
#kyc .ksp .nd{width:56px;text-align:center;font-size:10.5px;color:rgba(255,255,255,.75);flex:none}
#kyc .ksp .nd i{display:grid;place-items:center;width:26px;height:26px;margin:0 auto 4px;border-radius:50%;background:rgba(255,255,255,.22);font-style:normal;font-size:12px;font-weight:700;color:#fff;transition:background .4s,color .4s}
#kyc .ksp .nd i svg{width:14px;height:14px;stroke:var(--p)}
#kyc .ksp .nd.d i{background:#fff;color:var(--p)}
#kyc .ksp .nd.a i{background:#fff;color:var(--p);animation:kpu 2s infinite}
#kyc .ksp .nd.a{color:#fff;font-weight:700}
#kyc .ksp s{flex:1;height:3px;margin-top:12px;background:rgba(255,255,255,.25);border-radius:3px;overflow:hidden;text-decoration:none}
#kyc .ksp s u{display:block;height:100%;width:0;background:#fff;border-radius:3px;text-decoration:none}
#kyc .ksp s.f u{width:100%;animation:kfw .8s .2s cubic-bezier(.22,1,.36,1) backwards}
@keyframes kpu{0%,100%{box-shadow:0 0 0 0 rgba(255,255,255,.5)}50%{box-shadow:0 0 0 6px rgba(255,255,255,0)}}
@keyframes kfw{from{width:0}}
/* ইন্ট্রো তালিকা */
#kyc .kli2{display:flex;align-items:center;gap:14px;padding:11px 0;font-size:15px;color:#3b3540}
#kyc .kli2+.kli2{border-top:1px solid var(--ln)}
#kyc .kli2 svg{width:42px;height:42px;padding:10px;border-radius:14px;background:linear-gradient(145deg,var(--pl),#fff0);color:var(--p);stroke-width:1.8;flex:none;box-shadow:inset 0 0 0 1px var(--ln)}
#kyc .kli2 b{flex:1;font-weight:700;font-size:14.5px}
#kyc .kli2 em{font-style:normal;font-size:12px;font-weight:700;color:var(--p);background:var(--pl);width:24px;height:24px;border-radius:50%;display:grid;place-items:center;flex:none}
#kyc .knote{display:flex;align-items:center;justify-content:center;gap:6px}
#kyc .knote svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:2}
/* ডকুমেন্ট বাছাই */
#kyc .kfld{display:flex;justify-content:space-between;align-items:center;background:#fff;border-radius:18px;padding:13px 16px;font-size:14.5px;font-weight:600;color:#2a262b;box-shadow:0 6px 20px rgba(170,20,95,.08);margin-bottom:12px;animation:kup .5s both}
#kyc .kfld small{display:block;color:var(--mu);font-size:11.5px;font-weight:500}
#kyc .kfld svg{width:22px;height:22px;color:var(--p);fill:none;stroke:currentColor;stroke-width:1.8}
#kyc .ksel{display:flex;gap:13px;align-items:center;background:#fff;border:2px solid transparent;border-radius:20px;padding:14px;text-align:left;width:100%;box-shadow:0 6px 20px rgba(170,20,95,.08);margin-bottom:12px;cursor:pointer;font:inherit;color:inherit;opacity:0;animation:kup .5s var(--d,0s) both;transition:border-color .35s,background .35s,transform .35s cubic-bezier(.22,1,.36,1)}
#kyc .ksel>svg{width:42px;height:42px;padding:10px;border-radius:14px;background:var(--pl);color:var(--p);stroke-width:1.8;flex:none}
#kyc .ksel b{display:block;font-size:15px;color:#2a262b}
#kyc .ksel span{font-size:12px;color:var(--mu)}
#kyc .ksel.on{border-color:var(--p);background:var(--pl);transform:scale(1.012)}
#kyc .ksel:active{transform:scale(.975)}
#kyc .krd2{margin-left:auto;width:24px;height:24px;border-radius:50%;border:2px solid var(--ln);flex:none;display:grid;place-items:center;transition:all .3s}
#kyc .krd2:after{content:"";width:10px;height:6px;border-left:2.6px solid #fff;border-bottom:2.6px solid #fff;transform:translateY(-1px) rotate(-45deg) scale(0);transition:transform .35s cubic-bezier(.22,1,.36,1)}
#kyc .ksel.on .krd2{border-color:var(--p);background:var(--p)}
#kyc .ksel.on .krd2:after{transform:translateY(-1px) rotate(-45deg) scale(1)}
@media (prefers-reduced-motion:reduce){#kyc .kt2 .kbb,#kyc .ksp .nd.a i{animation:none}}

/* ---- v3.06 ভাগ ২: ক্যামেরা চিপ/হিন্ট, যাচাই চেকলিস্ট ---- */
#kyc .kcam .kchp{position:absolute;left:50%;top:100%;margin-top:20px;transform:translateX(-50%);z-index:4;display:flex;align-items:center;gap:9px;padding:9px 16px;border-radius:22px;font-size:13.5px;font-weight:700;color:#4a3340;background:rgba(255,255,255,.82);box-shadow:0 6px 18px rgba(226,19,110,.16);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);white-space:nowrap;animation:kchi .45s cubic-bezier(.22,1,.36,1) both}
#kyc .kcam .kchp.gd{background:#12a15b;color:#fff;box-shadow:0 8px 20px rgba(18,161,91,.4)}
#kyc .kcam .kchp .kck{display:grid;place-items:center;width:20px;height:20px;border-radius:50%;background:rgba(255,255,255,.25)}
#kyc .kcam .kchp .kck svg{width:13px;height:13px;stroke-dasharray:30;stroke-dashoffset:30;animation:kdr .5s .12s ease forwards}
#kyc .kcam .kchp .kspin{width:15px;height:15px}
@keyframes kchi{from{opacity:0;transform:translateX(-50%) translateY(10px) scale(.94)}}
@keyframes kdr{to{stroke-dashoffset:0}}
#kyc .kcam .khint{position:absolute;left:50%;transform:translateX(-50%);bottom:100%;margin-bottom:18px;width:100%;z-index:4;display:flex;align-items:center;justify-content:center;gap:8px;text-align:center;font-size:13.5px;font-weight:700;line-height:1.35;color:#b3202f;background:rgba(255,255,255,.88);border-radius:16px;padding:9px 12px;box-shadow:0 6px 18px rgba(226,19,110,.14);animation:kchi .4s cubic-bezier(.22,1,.36,1) both}
#kyc .kcam .khint svg{width:20px;height:20px;flex:none}
/* যাচাই পাতা */
#kyc .kmh{display:none}
#kyc .kz{animation:none;opacity:1}
#kyc .kck2s{margin-top:16px;text-align:left;border-top:1px solid var(--ln);padding-top:4px}
#kyc .kck2{display:flex;align-items:center;gap:12px;padding:11px 2px;font-size:14px;font-weight:600;color:#3b3540;opacity:.35;transform:translateX(-6px);transition:opacity .5s,transform .5s cubic-bezier(.22,1,.36,1)}
#kyc .kck2+.kck2{border-top:1px solid var(--ln)}
#kyc .kck2 em{position:relative;width:24px;height:24px;border-radius:50%;background:var(--ln);display:grid;place-items:center;flex:none;transition:background .4s}
#kyc .kck2 em svg{width:13px;height:13px;opacity:0;transform:scale(.4);transition:opacity .3s,transform .45s cubic-bezier(.22,1,.36,1)}
#kyc .kck2 em .kspin{position:absolute;inset:3px;width:auto;height:auto;border:2.5px solid rgba(226,19,110,.25);border-top-color:var(--p);opacity:0}
#kyc .kck2.on{opacity:1;transform:none}
#kyc .kck2.on em{background:#12a15b}
#kyc .kck2.on em svg{opacity:1;transform:none}
/* চলার সময়: একে একে টিক (সময় ধরে), শেষটা ফলাফল না আসা পর্যন্ত ঘোরে */
#kyc .kck2.run{animation:kck2 .6s calc(.9s + var(--i)*1.05s) cubic-bezier(.22,1,.36,1) forwards}
#kyc .kck2.run em{animation:kck2e .01s calc(.9s + var(--i)*1.05s) forwards}
#kyc .kck2.run em svg{animation:kck2s .45s calc(.95s + var(--i)*1.05s) cubic-bezier(.22,1,.36,1) forwards}
#kyc .kck2.run:last-child{animation:kck2l .5s .2s forwards}
#kyc .kck2.run:last-child em{animation:none;background:var(--ln)}
#kyc .kck2.run:last-child em svg{animation:none}
#kyc .kck2.run:last-child em .kspin{opacity:1}
@keyframes kck2{to{opacity:1;transform:none}}
@keyframes kck2e{to{background:#12a15b}}
@keyframes kck2s{to{opacity:1;transform:none}}
@keyframes kck2l{to{opacity:1;transform:none}}

/* ---- v3.06 ভাগ ৫: ক্যামেরা পাতার ওপরের শিরোনাম দেখানো, বাদ দেওয়া লোগো-ব্লকের জায়গা ---- */
#kyc .kcam.kn .ktp b{display:block;text-align:center;white-space:nowrap}

/* ---- v3.06 ভাগ ৬: ক্যামেরা চালু থাকার সময়ের সমস্যার বার্তা (স্থির রাখুন / আরও কাছে ধরুন) ওপরের হিন্টের জায়গায়, ফ্রেমের ঠিক ওপরে ---- */
#kyc .kcam.kn .kwr:not(.pv)~.kbt #kst{position:fixed;left:50%;transform:translateX(-50%);width:min(88%,380px);top:calc(50% - min(88vw,380px) / 3.172 - 58px);margin:0;text-align:center;color:#b3202f;font-size:13.5px;font-weight:700;line-height:1.35;z-index:4;pointer-events:none}

/* =====================================================================
   v3.11 — ডেমো (funpay-intro-v4) অনুযায়ী: ইন্ট্রো, নতুন ইউজারের নম্বর পাতা,
   পুরনো ইউজারের PIN পাতা, ভাষা বোতামের গোল ঘর। (ভেতরের অ্যাপ অপরিবর্তিত)
   ===================================================================== */
:root{--fi-cur:radial-gradient(120% 65% at 50% 0%,rgba(255,130,180,.5),rgba(255,130,180,0) 62%),linear-gradient(165deg,#e8247a 0%,#c40f5e 50%,#8c0941 100%);--fe:cubic-bezier(.2,.9,.2,1)}

/* ---------- ভাষা বোতাম: গোল ঘর (ডান কোণেই) ---------- */
.flp{display:inline-flex;gap:2px;padding:3px;border-radius:99px;background:rgba(0,0,0,.24);border:1px solid rgba(255,255,255,.22);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);transition:background .5s,border-color .5s}
.flp button{height:30px;min-width:0;padding:0 11px;border:0;border-radius:99px;background:transparent;color:#fff;font:600 12px/1 system-ui,-apple-system,"Noto Sans Bengali","Segoe UI",sans-serif;display:grid;place-items:center;cursor:pointer;transition:background .5s,color .5s,transform .15s}
.flp button:active{transform:scale(.9)}
.flp button.on{background:#fff;color:#e2136e}
.flp.lt{background:#fff;border-color:#e8d8e1;-webkit-backdrop-filter:none;backdrop-filter:none}
.flp.lt button{color:#8a7683}
.flp.lt button.on{background:#e2136e;color:#fff}
html.lowend .flp{-webkit-backdrop-filter:none;backdrop-filter:none}

/* ---------- ইন্ট্রো ওভারলে (#fpi) ---------- */
#fpi{--aw:390px;--ah:760px;--L:128px;--tx:0px;--ty:0px;--ts:.235;--yl:#ffc83d;--dk:#c40f5e;--pk:#e2136e;position:fixed;inset:0;z-index:99990;overflow:hidden;pointer-events:none;contain:layout paint;font-family:system-ui,-apple-system,"Noto Sans Bengali","Segoe UI",sans-serif;opacity:1;transition:opacity .35s ease}
#fpi.s{z-index:4}
#fpi.off{opacity:0;visibility:hidden;transition:opacity .35s ease,visibility 0s .35s}
#fpi.nt,#fpi.nt *,#fpi.nt *::before,#fpi.nt *::after{transition:none!important;animation:none!important}
#fpi.fi-cn .fi-cur{transition:none!important}
#fpi .fi-cur{position:absolute;inset:0 0 -64px 0;z-index:2;overflow:hidden;background:var(--fi-cur);border-radius:0 0 50% 50%/0 0 7% 7%;transform:translate3d(0,0,0);transition:transform 1.25s cubic-bezier(.76,0,.2,1),opacity .75s ease .15s;will-change:transform;contain:paint}
#fpi.m-new.g .fi-cur{transform:translate3d(0,-102%,0)}
#fpi.m-old .fi-cur{bottom:0;border-radius:0}
#fpi.m-old.g .fi-cur{opacity:0}
#fpi.m-old.g .fi-cur b{display:none}
#fpi.s .fi-cur{visibility:hidden}
#fpi.m-old:not(.g):not(.nt) .fi-cur{pointer-events:auto}
#fpi .fi-orb{position:absolute;border-radius:50%;pointer-events:none;will-change:transform}
#fpi .fi-o1{width:380px;height:380px;right:-150px;top:-130px;background:radial-gradient(circle,rgba(255,190,222,.40),transparent 68%);animation:fiDrift 10s ease-in-out infinite alternate}
#fpi .fi-o2{width:440px;height:440px;left:-200px;bottom:-180px;background:radial-gradient(circle,rgba(255,120,185,.30),transparent 68%);animation:fiDrift 13s ease-in-out -5s infinite alternate-reverse}
@keyframes fiDrift{to{transform:translate3d(-28px,34px,0) scale(1.12)}}
#fpi .fi-cur b{position:absolute;top:100%;border-radius:50%;background:#fff;opacity:0;animation:fiRise var(--d) linear var(--dl) infinite;will-change:transform}
@keyframes fiRise{0%{transform:translate3d(0,0,0);opacity:0}12%{opacity:var(--po)}85%{opacity:var(--po)}100%{transform:translate3d(var(--dx),calc(var(--ah) * -1.1),0);opacity:0}}
html.lowend #fpi .fi-cur b{display:none}
html.lowend #fpi .fi-orb{animation:none}

/* লোগো */
#fpi .fi-lg{position:absolute;z-index:3;left:0;top:0;width:var(--L);height:var(--L);--w:#fff;--y:var(--yl);--t:var(--dk);transform:translate3d(calc(var(--aw)/2 - 64px),calc(var(--ah)*.5 - 64px),0);transition:transform 1.3s cubic-bezier(.25,.85,.2,1),opacity .35s;will-change:transform}
#fpi.w .fi-lg{transform:translate3d(calc(var(--aw)/2 - 64px),calc(var(--ah)*.47 - 50px - 64px),0)}
#fpi.g .fi-lg{transform:translate3d(var(--tx),var(--ty),0) scale(var(--ts));transition:transform 1.25s cubic-bezier(.66,0,.2,1),opacity .35s}
#fpi.g.s .fi-lg{transition:transform .45s cubic-bezier(.22,1,.36,1),opacity .35s}
#fpi.hl .fi-lg{opacity:0}
#fpi.L .fi-lg{--w:var(--pk);--t:#fff}
#fpi .fi-sv{position:absolute;inset:0}
#fpi .fi-lg svg{display:block;width:100%;height:100%;overflow:visible}
#fpi .fdw,#fpi .fcc{fill:var(--w)}#fpi .fdy{fill:var(--y)}#fpi .frl{stroke:var(--w);stroke-width:3;stroke-linecap:round}
#fpi .ftk{font:700 58px system-ui,-apple-system,"Noto Sans Bengali","Segoe UI",sans-serif;fill:var(--t);text-anchor:middle;dominant-baseline:central}
#fpi.g .fi-lg .fdw,#fpi.g .fi-lg .fcc,#fpi.g .fi-lg .frl,#fpi.g .fi-lg .ftk{transition:fill .4s .5s,stroke .4s .5s}
#fpi .frA{opacity:0;transform-origin:100px 100px}
#fpi .frB{transform-origin:100px 100px}
#fpi .fdw,#fpi .fdy,#fpi .fcc{transform-box:fill-box;transform-origin:center;transform:scale(0)}
#fpi .ftk{opacity:0;transform-box:fill-box;transform-origin:center}
#fpi .frl{stroke-dasharray:14;stroke-dashoffset:14}
#fpi.e .frA{animation:fiRin 1.7s cubic-bezier(.16,.84,.24,1) .05s both}
#fpi.e .frB{animation:fiSpin 60s linear infinite}
#fpi.e .fdw,#fpi.e .fdy{animation:fiDpop .6s cubic-bezier(.3,1.6,.5,1) calc(.25s + var(--i) * 42ms) both,fiWave 3.4s ease-in-out calc(2.2s + var(--i) * 110ms) infinite}
#fpi.e .frl{animation:fiTick .5s ease-out calc(.35s + var(--i) * 40ms) forwards}
#fpi.e .fcc{animation:fiCpop .9s cubic-bezier(.2,1.2,.3,1) .5s both}
#fpi.e .ftk{animation:fiTkin .7s cubic-bezier(.2,.9,.3,1) .85s both}
html.lowend #fpi.e .fdw,html.lowend #fpi.e .fdy{animation:fiDpop .6s cubic-bezier(.3,1.6,.5,1) calc(.25s + var(--i) * 42ms) both}
@keyframes fiRin{0%{transform:rotate(-210deg) scale(.5);opacity:0}35%{opacity:1}100%{transform:rotate(0) scale(1);opacity:1}}
@keyframes fiSpin{to{transform:rotate(360deg)}}
@keyframes fiDpop{0%{transform:scale(0)}100%{transform:scale(1)}}
@keyframes fiWave{0%,100%{transform:scale(1)}50%{transform:scale(1.45)}}
@keyframes fiTick{to{stroke-dashoffset:0}}
@keyframes fiCpop{0%{transform:scale(0)}100%{transform:scale(1)}}
@keyframes fiTkin{0%{opacity:0;transform:translateY(8px) scale(.6)}100%{opacity:1;transform:none}}

/* নাম, ট্যাগলাইন, লোডার */
#fpi .fi-nm,#fpi .fi-tg,#fpi .fi-ld{position:absolute;z-index:3;left:0;right:0}
#fpi .fi-nm{top:calc(var(--ah)*.47 + 28px);text-align:center;color:#fff;font-weight:700;font-size:38px;line-height:44px;letter-spacing:.6px}
#fpi .fi-nm span{display:inline-block;opacity:0;transform:translate3d(0,18px,0);filter:blur(7px);transition:opacity .7s,transform .8s var(--fe),filter .7s}
#fpi.w .fi-nm span{opacity:1;transform:none;filter:blur(0);transition-delay:calc(.25s + var(--i) * .07s)}
#fpi.g .fi-nm span{opacity:0;transform:translate3d(0,-12px,0);filter:blur(4px);transition-duration:.4s;transition-delay:0s}
#fpi .fi-tg{top:calc(var(--ah)*.47 + 82px);text-align:center;color:rgba(255,255,255,.9);font-size:14.5px;line-height:22px;letter-spacing:.2px;opacity:0;transform:translate3d(0,8px,0);transition:opacity .8s,transform .8s var(--fe)}
#fpi.w .fi-tg{opacity:1;transform:none;transition-delay:.85s}
#fpi.g .fi-tg{opacity:0;transform:translate3d(0,-8px,0);transition-duration:.35s;transition-delay:0s}
#fpi .fi-ld{top:calc(var(--ah)*.47 + 130px);left:50%;right:auto;width:108px;margin-left:-54px;height:3px;border-radius:3px;background:rgba(255,255,255,.22);overflow:hidden;opacity:0;transition:opacity .5s}
#fpi .fi-ld i{display:block;height:100%;border-radius:3px;background:#fff;transform:scaleX(0);transform-origin:left}
#fpi.w .fi-ld{opacity:1;transition-delay:1.2s}
#fpi.w .fi-ld i{animation:fiFill 1.3s cubic-bezier(.4,.1,.2,1) 1.3s forwards}
@keyframes fiFill{to{transform:scaleX(1)}}
#fpi.b .fi-ld,#fpi.g .fi-ld,#fpi.m-old.w .fi-ld.x{opacity:0;transition-delay:0s;transition-duration:.3s}

/* বোতাম */
#fpi .fi-bt{position:absolute;z-index:3;left:34px;right:34px;bottom:calc(20px + env(safe-area-inset-bottom,0px));height:48px;padding:0 46px 0 20px;border:0;border-radius:99px;overflow:hidden;display:flex;align-items:center;justify-content:center;background:linear-gradient(180deg,#fff,#ffeaf4);color:#e2136e;font:600 15px system-ui,-apple-system,"Noto Sans Bengali","Segoe UI",sans-serif;letter-spacing:.2px;box-shadow:0 10px 22px rgba(70,0,35,.26),inset 0 1px 0 rgba(255,255,255,.9);transform:translate3d(0,220%,0);opacity:0;transition:transform .9s var(--fe),opacity .6s;-webkit-tap-highlight-color:transparent;cursor:pointer}
#fpi .fi-bt::after{content:"";position:absolute;top:0;bottom:0;left:0;width:45%;background:linear-gradient(100deg,transparent,rgba(226,19,110,.18),transparent);transform:translate3d(-130%,0,0) skewX(-18deg)}
#fpi .fi-ch{position:absolute;right:6px;top:6px;width:36px;height:36px;border-radius:50%;background:#e2136e;color:#fff;display:grid;place-items:center}
#fpi .fi-ch svg{width:18px;height:18px;animation:fiNg 1.8s ease-in-out 1.4s infinite}
@keyframes fiNg{0%,100%{transform:none}50%{transform:translateX(3px)}}
#fpi.b.m-new:not(.g) .fi-bt{transform:none;opacity:1;pointer-events:auto}
#fpi.b.m-new:not(.g) .fi-bt::after{animation:fiShine 3.4s ease-in-out 1s infinite}
#fpi .fi-bt:active{transform:scale(.97);transition-duration:.15s}
#fpi.g.m-new .fi-bt,#fpi.g .fi-bt{transform:translate3d(0,220%,0);opacity:0;transition-duration:.5s;pointer-events:none}
@keyframes fiShine{0%{transform:translate3d(-130%,0,0) skewX(-18deg)}45%,100%{transform:translate3d(330%,0,0) skewX(-18deg)}}

/* ইন্ট্রোর ভাষা-ঘর */
#fpi .fi-lt{position:absolute;z-index:6;top:calc(12px + var(--st,0px));right:14px;opacity:0;pointer-events:none;transition:opacity .8s}
#fpi.w .fi-lt{opacity:1;pointer-events:auto;transition-delay:.7s}
#fpi.g .fi-lt{opacity:0;pointer-events:none;transition-duration:.25s;transition-delay:0s}

/* ---------- পেজগুলো ইন্ট্রো চলার সময় লুকানো থাকে (ইন্ট্রো শেষে নরমভাবে ওঠে) ---------- */
.fpi-ph{display:block;flex:none;width:30px;height:30px;pointer-events:none}
html.fpi-hold .fl.pinp .psheet.bkl{animation:none!important;transform:translate3d(0,102%,0);visibility:hidden}
html.fpi-hold .fl.pinp .phead b{animation:none!important;opacity:0}
html.fpi-hold .fph .fpn,html.fpi-hold .fph .fph-hd b{animation:none!important;opacity:0}
html.fpi-hold .fph .nbar{animation:none!important;opacity:0;transform:translate3d(0,102%,0)}
html.fpi-hold .fph .fph-sh .pfield::after{animation:none!important;transform:scaleX(0)}
html.fpi-hold .fl.land{background:var(--fi-cur)!important}

/* ---------- নতুন ইউজার: মোবাইল নম্বর (রেজিস্ট্রেশন) পাতা ---------- */
.fl.light.fph{background:#fbf2f7!important;color:#2b1a26;display:flex;flex-direction:column;height:100vh;height:100dvh;min-height:0;overflow:hidden}
.fph .fph-hz{position:absolute;left:0;right:0;top:0;height:330px;overflow:hidden;background:linear-gradient(180deg,#ffcde3 0%,#ffe4f0 55%,#fbf2f7 100%);pointer-events:none}
.fph .fph-hz::before,.fph .fph-hz::after{content:"";position:absolute;border-radius:50%}
.fph .fph-hz::before{width:280px;height:280px;right:-100px;top:-90px;background:radial-gradient(circle,rgba(255,255,255,.8),transparent 70%)}
.fph .fph-hz::after{width:220px;height:220px;left:-80px;top:110px;background:radial-gradient(circle,rgba(226,19,110,.13),transparent 70%)}
.fph .fph-top{position:relative;z-index:2;flex:none;display:flex;align-items:center;justify-content:space-between;padding:calc(12px + var(--st)) 14px 0 10px}
.fph .fph-hd{position:relative;z-index:2;flex:none;display:flex;align-items:center;gap:11px;height:30px;margin:28px 0 0 25px}
.fph .fph-hd b{font-weight:700;font-size:20px;line-height:26px;letter-spacing:.3px;color:#e2136e;animation:fpiHd .7s var(--fe) .1s both}
.fph.fph-i .fph-hd b{animation-delay:.95s}
.fph .fph-bn{position:relative;z-index:2;flex:none;margin:14px 18px 0 22px;height:108px;display:flex;align-items:center;justify-content:space-between;overflow:hidden;transition:height .3s ease,margin .3s ease,opacity .25s ease}
html.kbup .fph .fph-bn{height:0;margin-top:0;opacity:0}
.fph .fph-bn p{margin:0;font-size:12.5px;line-height:1.4;color:#6a3d55}
.fph .fph-bn strong{display:block;font-size:40px;line-height:1.1;font-weight:700;color:#e2136e;letter-spacing:-.3px}
.fph .fph-bn sup{font-size:20px;margin-left:2px;vertical-align:top}
.fph .fph-bn svg{width:128px;height:104px;flex:none;overflow:visible}
.fph .cn{animation:fiFl 3.2s ease-in-out infinite}.fph .c2{animation-delay:-1.5s}
@keyframes fiFl{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}
.fph .fph-sh{position:relative;z-index:2;flex:1 1 auto;min-height:0;margin-top:10px;padding:24px 22px 12px;background:#fff;border-radius:28px 28px 0 0;box-shadow:0 -12px 36px rgba(150,20,90,.10);overflow:hidden}
.fph .fph-sh .ti{margin:0 0 18px;font-size:20px;font-weight:700;line-height:1.4;color:#2b1a26}
.fph .fph-lb{margin:0 0 6px;font-size:12.5px;color:#8a7683}
.fl.light.fph .cfield{height:auto!important;display:flex;align-items:center;gap:10px;padding:12px 14px!important;border:1px solid #e8d8e1!important;border-radius:12px!important;background:#fff!important;font-size:15.5px;margin-bottom:20px;box-shadow:0 8px 22px rgba(120,20,70,.07)!important;color:#2b1a26}
.fph .cfield .flag{width:22px;height:22px}
.fph .cfield .fph-ch{width:18px;height:18px;margin-left:auto;color:#8a7683;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.fl.light.fph .pfield{position:relative;gap:10px!important;padding:8px 2px 2px!important;border:0!important;border-bottom:1px solid #e8d8e1!important}
.fl.light.fph .pfield::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:2px;background:#e2136e;transform-origin:left;animation:fiUl .9s var(--fe) .3s both}
.fph.fph-i .pfield::after{animation-delay:1.5s}
@keyframes fiUl{from{transform:scaleX(0)}to{transform:none}}
.fl.light.fph .pfield b{font-size:18px}
.fl.light.fph .pfield input{height:42px;font-size:18px}
.fl.light.fph .le{margin-top:8px;min-height:20px}
.fl.light.fph .terms{margin:6px 0 0;font-size:12.5px;line-height:1.5;color:#8a7683}
.fl.light.fph .terms b{color:#e2136e;font-weight:600}
.fph .sv4{margin-top:18px}
.fph .sv4 .st{margin:0 0 12px;font-size:13px;font-weight:600;color:#2b1a26}
.fph .sg{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;text-align:center}
.fph .sg div{display:flex;flex-direction:column;align-items:center;gap:7px;font-size:11.5px;line-height:1.3;color:#8a7683}
.fph .sg i{width:48px;height:48px;border-radius:50%;display:grid;place-items:center;color:#e2136e;background:linear-gradient(145deg,#fff1f7,#ffdcec)}
.fph .sg svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
@media (max-height:740px){.fph .sv4{display:none}}
html.kbup .fph .sv4{display:none}
.fph .fpn{animation:fpiIn .9s var(--fe) calc(var(--k) * .08s) both}
.fph.fph-i .fpn{animation-delay:calc(.5s + var(--k) * .08s)}
.fph.fph-i .nbar{animation:fpiBar .8s var(--fe) 1s both!important}
@keyframes fpiIn{from{opacity:0;transform:translate3d(0,22px,0)}to{opacity:1;transform:none}}
@keyframes fpiHd{from{opacity:0;transform:translate3d(-8px,0,0)}to{opacity:1;transform:none}}
@keyframes fpiBar{from{transform:translate3d(0,102%,0)}to{transform:none}}

/* ---------- পুরনো ইউজার: PIN পাতা ---------- */
.fl.pinp{background:var(--fi-cur)!important}
.fl.pinp .phead .fpi-ph{width:clamp(62px,15dvh,112px);height:auto;aspect-ratio:1/1;flex:none}
.fl.pinp .phead b{animation:fpiHd2 .7s var(--fe) .85s both}
@keyframes fpiHd2{from{opacity:0;transform:translate3d(0,10px,0)}to{opacity:1;transform:none}}
.fl.pinp .psheet.bkl{animation:fpiSheet .95s var(--fe) .1s both!important;overflow:hidden;position:relative}
@keyframes fpiSheet{from{transform:translate3d(0,102%,0)}to{transform:none}}
.fl.pinp .psheet.bkl>*:not(.wk){position:relative;z-index:1}
.psheet .wk{position:absolute;width:200px;height:200px;opacity:.11;pointer-events:none;z-index:0}
.psheet .w1{left:-78px;top:30%}.psheet .w2{right:-84px;top:52%;width:210px;height:210px}.psheet .w3{left:50%;margin-left:-90px;bottom:6px;width:180px;height:180px}
/* ---------- পাতা বদলে ঝিলিক নয়: লগইনের সব পাতায় শুধু নরম ফেড ---------- */
.fl.vtf,.fl.vtb,.fl.vtn{animation:fpiSoft .45s ease-out both!important}
@keyframes fpiSoft{from{opacity:0}to{opacity:1}}
#app>.fl.land{animation:none!important}
html.fpi-hold #app>.fl{animation:none!important}

/* =====================================================================
   v3.12 — (১) লগইন (PIN) পাতায় লোগোর ওপর লোগো: পুরনো ছবির ব্যাকগ্রাউন্ড আর নতুন .wk লোগো দুটোই আঁকা হচ্ছিল, এখন শুধু .wk
           (২) রেজিস্ট্রেশন (নম্বর) পাতা: দেশের কোড ও "যা যা পাবেন" সরানোর পর নিচের ফাঁকা অংশে হালকা লোগো
   ===================================================================== */
.fl.pinp .psheet.bkl{background:#fff!important}
.fph .fph-sh>*:not(.wk){position:relative;z-index:1}
.fph .fph-sh .wk{position:absolute;opacity:.11;pointer-events:none;z-index:0}
.fph .fph-sh .w1{left:-74px;bottom:-22px;width:190px;height:190px}
.fph .fph-sh .w2{right:-84px;bottom:104px;width:170px;height:170px}
.fph .fph-sh .w3{display:none}
